@Composable
private fun ReaderTopBar(
    request: ChimahonReaderRequest,
    currentPage: Int,
    pageCount: Int,
    canvas: ReaderCanvas = ReaderCanvas.Black,
    showTitle: Boolean = true,
    bookmarked: Boolean,
    bookmarkBusy: Boolean,
    onBack: () -> Unit,
    onToggleHud: () -> Unit = {},
    onToggleBookmark: (() -> Unit)?,
    downloadBusy: Boolean = false,
    onDownloadChapter: (() -> Unit)? = null,
    readBusy: Boolean = false,
    onMarkChapterRead: (() -> Unit)? = null,
    onToggleOcrLookup: (() -> Unit)? = null,
    onOpenChapterUrl: (() -> Unit)? = null,
    onShareChapter: (() -> Unit)? = null,
) {
    val hudBackground = readerHudBackground(canvas)
    val hudContent = readerHudContent(canvas)
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .height(52.dp)
            .background(hudBackground.copy(alpha = 0.96f))
            .border(1.dp, hudContent.copy(alpha = 0.08f))
            .clickable(role = Role.Button, onClick = onToggleHud)
            .padding(start = 2.dp, end = 6.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        ReaderAction(
            icon = UiIcon.Back,
            contentDescription = "Back",
            tint = hudContent,
            onClick = onBack,
        )
        Column(
            modifier = Modifier
                .weight(1f)
                .padding(start = 1.dp, end = 5.dp),
        ) {
            if (showTitle) {
                Label(
                    text = request.mangaTitle,
                    color = hudContent,
                    size = 13,
                    weight = FontWeight.SemiBold,
                    maxLines = 1,
                )
            }
            Row(
                modifier = Modifier.padding(top = if (showTitle) 2.dp else 0.dp),
                horizontalArrangement = Arrangement.spacedBy(5.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Label(
                    text = request.chapterName,
                    color = hudContent.copy(alpha = 0.70f),
                    size = if (showTitle) 10 else 13,
                    weight = if (showTitle) FontWeight.Normal else FontWeight.SemiBold,
                    maxLines = 1,
                    modifier = Modifier.weight(1f, fill = false),
                )
                ReaderTinyHudPill(
                    text = request.readerChapterMarker(),
                    canvas = canvas,
                )
                request.scanlator?.takeIf { it.isNotBlank() }?.let { scanlator ->
                    ReaderTinyHudPill(
                        text = scanlator,
                        canvas = canvas,
                        subdued = true,
                    )
                }
            }
        }
        if (pageCount > 0) {
            ReaderTinyHudPill(
                text = "$currentPage/$pageCount",
                canvas = canvas,
                modifier = Modifier.padding(horizontal = 2.dp),
            )
        }
        onToggleOcrLookup?.let {
            ReaderAction(
                icon = UiIcon.Search,
                contentDescription = "GLens OCR lookup",
                tint = hudContent,
                onClick = it,
            )
        }
        onDownloadChapter?.let {
            ReaderAction(
                icon = UiIcon.Download,
                contentDescription = "Download chapter",
                active = downloadBusy,
                enabled = !downloadBusy,
                tint = hudContent,
                onClick = it,
            )
        }
        onMarkChapterRead?.let {
            ReaderAction(
                icon = UiIcon.DoneAll,
                contentDescription = "Mark chapter read",
                active = readBusy,
                enabled = !readBusy,
                tint = hudContent,
                onClick = it,
            )
        }
        onOpenChapterUrl?.let {
            ReaderAction(
                icon = UiIcon.Web,
                contentDescription = "Open in WebView",
                tint = hudContent,
                onClick = it,
            )
        }
        onShareChapter?.let {
            ReaderAction(
                icon = UiIcon.Share,
                contentDescription = "Share chapter",
                tint = hudContent,
                onClick = it,
            )
        }
        onToggleBookmark?.let {
            ReaderAction(
                icon = if (bookmarked) UiIcon.Bookmark else UiIcon.BookmarkBorder,
                contentDescription = if (bookmarked) "Unbookmark chapter" else "Bookmark chapter",
                active = bookmarked || bookmarkBusy,
                enabled = !bookmarkBusy,
                tint = hudContent,
                onClick = it,
            )
        }
    }
}

@Composable
private fun ReaderTinyHudPill(
    text: String,
    canvas: ReaderCanvas,
    modifier: Modifier = Modifier,
    subdued: Boolean = false,
) {
    Label(
        text = text,
        color = readerHudContent(canvas).copy(alpha = if (subdued) 0.66f else 0.84f),
        size = 8,
        weight = FontWeight.SemiBold,
        maxLines = 1,
        modifier = modifier
            .clip(RoundedCornerShape(50))
            .background(readerHudContent(canvas).copy(alpha = if (subdued) 0.08f else 0.12f))
            .padding(horizontal = 5.dp, vertical = 2.dp),
    )
}

@Composable
private fun HomeNavigationRail(
    selected: HomeTab,
    state: ChimahonUiState,
    tabs: List<HomeTab>,
    compact: Boolean,
    appIcon: ChimahonAppIcon,
    showBadges: Boolean,
    onSelect: (HomeTab) -> Unit,
) {
    Column(
        modifier = Modifier
            .width(if (compact) 84.dp else 96.dp)
            .fillMaxHeight()
            .background(ChimahonPalette.surface)
            .endDivider()
            .padding(vertical = 12.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        AppMark(appIcon = appIcon)
        Spacer(Modifier.height(if (compact) 12.dp else 20.dp))
        tabs.forEach { tab ->
            RailItem(
                tab = tab,
                selected = tab == selected,
                badge = if (showBadges) state.badgeFor(tab) else null,
                compact = compact,
                onClick = { onSelect(tab) },
            )
        }
    }
}

@Composable
private fun RailItem(
    tab: HomeTab,
    selected: Boolean,
    badge: Int?,
    compact: Boolean,
    onClick: () -> Unit,
) {
    Column(
        modifier = Modifier
            .width(if (compact) 72.dp else 82.dp)
            .semantics(mergeDescendants = true) {
                contentDescription = tab.title
                this.selected = selected
                stateDescription = if (selected) "Selected" else "Not selected"
            }
            .clickable(role = Role.Tab, onClick = onClick)
            .padding(vertical = if (compact) 8.dp else 11.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        NavIcon(
            icon = tab.icon,
            contentDescription = tab.title,
            selected = selected,
            badge = badge,
        )
        Label(
            text = tab.title,
            color = if (selected) ChimahonPalette.primary else ChimahonPalette.secondaryText,
            size = if (compact) 11 else 12,
            weight = if (selected) FontWeight.SemiBold else FontWeight.Normal,
            maxLines = 1,
            modifier = Modifier.padding(top = if (compact) 4.dp else 5.dp),
        )
    }
}

@Composable
private fun HomeNavigationBar(
    selected: HomeTab,
    state: ChimahonUiState,
    tabs: List<HomeTab>,
    compact: Boolean,
    showLabels: Boolean,
    showBadges: Boolean,
    onSelect: (HomeTab) -> Unit,
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .height(
                when {
                    !showLabels -> 58.dp
                    compact -> 62.dp
                    else -> 74.dp
                },
            )
            .background(ChimahonPalette.surface)
            .topDivider()
            .padding(horizontal = 8.dp, vertical = 6.dp),
        horizontalArrangement = Arrangement.SpaceEvenly,
    ) {
        tabs.forEach { tab ->
            val selectedTab = tab == selected
            Column(
                modifier = Modifier
                    .weight(1f)
                    .fillMaxHeight()
                    .clip(RoundedCornerShape(20.dp))
                    .semantics(mergeDescendants = true) {
                        contentDescription = tab.title
                        this.selected = selectedTab
                        stateDescription = if (selectedTab) "Selected" else "Not selected"
                    }
                    .clickable(role = Role.Tab, onClick = { onSelect(tab) })
                    .padding(vertical = if (compact) 3.dp else 5.dp),
                horizontalAlignment = Alignment.CenterHorizontally,
            ) {
                NavIcon(
                    icon = tab.icon,
                    contentDescription = tab.title,
                    selected = selectedTab,
                    badge = if (showBadges) state.badgeFor(tab) else null,
                )
                if (showLabels) {
                    Label(
                        text = tab.title,
                        color = if (selectedTab) ChimahonPalette.primary else ChimahonPalette.secondaryText,
                        size = if (compact) 10 else 11,
                        weight = if (selectedTab) FontWeight.SemiBold else FontWeight.Normal,
                        maxLines = 1,
                        modifier = Modifier.padding(top = 3.dp),
                    )
                }
            }
        }
    }
}

@Composable
private fun NavIcon(
    icon: UiIcon,
    contentDescription: String,
    selected: Boolean,
    badge: Int?,
) {
    Box(
        modifier = Modifier.size(width = 56.dp, height = 34.dp),
        contentAlignment = Alignment.Center,
    ) {
        val showContainer = selected
        Box(
            modifier = Modifier
                .width(if (showContainer) 54.dp else 42.dp)
                .height(30.dp)
                .clip(RoundedCornerShape(15.dp))
                .background(if (showContainer) ChimahonPalette.primaryContainer.copy(alpha = 0.96f) else Color.Transparent)
                .border(
                    1.dp,
                    if (showContainer) ChimahonPalette.primary.copy(alpha = 0.10f) else Color.Transparent,
                    RoundedCornerShape(15.dp),
                ),
            contentAlignment = Alignment.Center,
        ) {
            IconGlyph(
                icon = icon,
                contentDescription = contentDescription,
                tint = if (selected) ChimahonPalette.onPrimaryContainer else ChimahonPalette.secondaryText,
                modifier = Modifier.size(22.dp),
                filled = selected,
            )
        }
        if (badge != null && badge > 0) {
            val badgeLabel = if (badge > 99) "99+" else badge.toString()
            Box(
                modifier = Modifier
                    .align(Alignment.TopEnd)
                    .height(16.dp)
                    .widthIn(min = 16.dp)
                    .clip(CircleShape)
                    .background(ChimahonPalette.error)
                    .padding(horizontal = 3.dp),
                contentAlignment = Alignment.Center,
            ) {
                Label(
                    text = badgeLabel,
                    color = Color.White,
                    size = 8,
                    weight = FontWeight.Bold,
                    maxLines = 1,
                )
            }
        }
    }
}

@Composable
private fun HomeContent(
    selected: HomeTab,
    snapshot: ChimahonSnapshot,
    selectedBrowseSection: BrowseSection,
    selectedAnimeSection: AnimeHomeSection,
    onBrowseSectionChange: (BrowseSection) -> Unit,
    onSelectTab: (HomeTab) -> Unit,
    onAnimeSectionChange: (AnimeHomeSection) -> Unit,
    homeSearchQuery: String,
    homeFiltersVisible: Boolean,
    feedManageMode: Boolean,
    migrateHelpVisible: Boolean,
    extensionRepoRequestKey: Int,
    requestedMorePage: MorePage?,
    onRequestedMorePageConsumed: () -> Unit,
    moreBackRequestId: Long?,
    onLoadSourcePreview: suspend (Long, ChimahonSourceBrowseMode, String, Int) -> ChimahonSourcePreview,
    onLoadRemoteMangaDetail: suspend (ChimahonRemoteMangaEntry) -> ChimahonRemoteMangaDetail,
    onOpenManga: (Long) -> Unit,
    onOpenRemoteManga: (ChimahonRemoteMangaEntry) -> Unit,
    onOpenReader: (ChimahonReaderRequest) -> Unit,
    onOpenSource: (Long, ChimahonSourceBrowseMode) -> Unit,
    onOpenLocalImport: () -> Unit,
    onAddRemoteMangaToLibrary: suspend (ChimahonRemoteMangaDetail) -> Long,
    onSetMangaFavorite: suspend (Long, Boolean) -> Unit,
    onSetMangasFavorite: suspend (Set<Long>, Boolean) -> ChimahonLibraryBulkActionResult,
    onCreateCategory: suspend (String) -> Long,
    onDeleteCategory: suspend (Long) -> Unit,
    onRenameCategory: suspend (Long, String) -> Unit,
    onSetCategoryHidden: suspend (Long, Boolean) -> Unit,
    onMoveCategory: suspend (Long, Int) -> Unit,
    onSetMangaCategories: suspend (Long, Set<Long>) -> Unit,
    onSetMangasCategories: suspend (Set<Long>, Set<Long>) -> ChimahonLibraryBulkActionResult,
    onResetHistoryEntry: suspend (Long) -> Unit,
    onResetHistoryForManga: suspend (Long) -> Unit,
    onClearHistory: suspend () -> Unit,
    onDismissUpdateIssue: suspend (Long) -> Unit,
    onClearUpdateIssues: suspend () -> Unit,
    onLoadDataMaintenance: suspend () -> ChimahonDataMaintenanceSnapshot,
    onClearThumbnailCache: suspend () -> ChimahonCacheClearResult,
    onClearCacheData: suspend () -> ChimahonCacheClearResult,
    onRunDatabaseMaintenance: suspend () -> ChimahonDatabaseMaintenanceResult,
    onSetChapterRead: suspend (Long, Boolean) -> Unit,
    onSetChapterBookmark: suspend (Long, Boolean) -> Unit,
    onSetMangasChaptersRead: suspend (Set<Long>, Boolean) -> ChimahonLibraryBulkActionResult,
    onEnqueueDownloads: suspend (Collection<Long>) -> ChimahonDownloadQueueData,
    onLoadDownloadSnapshot: suspend () -> ChimahonDownloadSnapshot,
    onLoadDownloadQueue: suspend () -> ChimahonDownloadQueueData,
    onPauseDownloadQueue: suspend () -> ChimahonDownloadQueueData,
    onResumeDownloadQueue: suspend () -> ChimahonDownloadQueueData,
    onProcessNextDownload: suspend () -> ChimahonDownloadQueueData,
    onPauseDownload: suspend (Long) -> ChimahonDownloadQueueData,
    onResumeDownload: suspend (Long) -> ChimahonDownloadQueueData,
    onRetryDownload: suspend (Long) -> ChimahonDownloadQueueData,
    onRemoveDownload: suspend (Long) -> ChimahonDownloadQueueData,
    onClearCompletedDownloads: suspend () -> ChimahonDownloadQueueData,
    onMoveDownloadToTop: suspend (Long) -> ChimahonDownloadQueueData,
    onMoveDownloadToBottom: suspend (Long) -> ChimahonDownloadQueueData,
    onAddExtensionRepo: suspend (String) -> ChimahonExtensionRepoEntry,
    onReplaceExtensionRepo: suspend (String, String) -> ChimahonExtensionRepoEntry,
    onDeleteExtensionRepo: suspend (String) -> Unit,
    onLoadExtensionRepoCatalog: suspend (ChimahonExtensionRepoEntry) -> ChimahonExtensionRepoCatalog,
    onInstallExtension: suspend (ChimahonRepoExtensionEntry) -> ChimahonInstalledExtensionEntry,
    onUninstallExtension: suspend (String, ChimahonExtensionPackageType) -> ChimahonExtensionUninstallResult,
    onRepoSaved: () -> Unit,
    downloadedOnlyMode: Boolean,
    incognitoMode: Boolean,
    settings: ChimahonSettings,
    onAppearanceSettingsChange: (ChimahonAppearanceSettings) -> Unit,
    onLibrarySettingsChange: (ChimahonLibrarySettings) -> Unit,
    onAnimeLibrarySettingsChange: (ChimahonAnimeLibrarySettings) -> Unit,
    onReaderSettingsChange: (ChimahonReaderSettings) -> Unit,
    onDownloadPreferencesChange: (ChimahonDownloadPreferences) -> Unit,
    onBrowseSettingsChange: (ChimahonBrowseSettings) -> Unit,
    onNavigationSettingsChange: (ChimahonNavigationSettings) -> Unit,
    onPlayerSettingsChange: (ChimahonPlayerSettings) -> Unit,
    onTrackingSettingsChange: (ChimahonTrackingSettings) -> Unit,
    onConnectionSettingsChange: (ChimahonConnectionSettings) -> Unit,
    onDictionarySettingsChange: (ChimahonDictionarySettings) -> Unit,
    onSecuritySettingsChange: (ChimahonSecuritySettings) -> Unit,
    onOpenExternalUrl: (String) -> Boolean,
    onDownloadedOnlyModeChange: (Boolean) -> Unit,
    onIncognitoModeChange: (Boolean) -> Unit,
) {
    when (selected) {
        HomeTab.Library -> LibraryHome(
            snapshot = snapshot,
            query = homeSearchQuery,
