@Composable
private fun SourceDetailHome(
    snapshot: ChimahonSnapshot,
    sourceId: Long,
    initialMode: ChimahonSourceBrowseMode,
    searchKey: Int,
    browseSettings: ChimahonBrowseSettings,
    onRefresh: () -> Unit,
    onLoadSourcePreview: suspend (Long, ChimahonSourceBrowseMode, String, Int) -> ChimahonSourcePreview,
    onOpenRemoteManga: (ChimahonRemoteMangaEntry) -> Unit,
    onOpenExternalUrl: (String) -> Boolean,
    onOpenLocalImport: () -> Unit,
) {
    val source = snapshot.sources.firstOrNull { it.id == sourceId }
    if (source == null) {
        val isLocalSourceRequest = sourceId == CHIMAHON_LOCAL_SOURCE_ID
        EmptyMobileState(
            marker = if (isLocalSourceRequest) "L" else "?",
            icon = if (isLocalSourceRequest) UiIcon.Storage else UiIcon.Browse,
            title = if (isLocalSourceRequest) "Local source unavailable" else "Source not found",
            detail = if (isLocalSourceRequest) {
                "Source ID $CHIMAHON_LOCAL_SOURCE_ID is not registered in this runtime. Open import status to review local data and storage prompts."
            } else {
                "This source is not available in the shared runtime registry."
            },
            action = if (isLocalSourceRequest) "Open import" else "Refresh",
            onAction = if (isLocalSourceRequest) onOpenLocalImport else onRefresh,
        )
        return
    }
    val isLocalSource = source.isLocalSource()

    val modes = if (source.supportsLatest) {
        ChimahonSourceBrowseMode.entries
    } else {
        listOf(ChimahonSourceBrowseMode.Popular, ChimahonSourceBrowseMode.Search)
    }
    var selectedMode by remember(sourceId, initialMode) { mutableStateOf(initialMode) }
    var searchText by remember(sourceId) { mutableStateOf("") }
    var submittedQuery by remember(sourceId) { mutableStateOf("") }
    var handledSearchKey by remember(sourceId) { mutableIntStateOf(searchKey) }
    var pageNumber by remember(sourceId, selectedMode, submittedQuery) { mutableIntStateOf(1) }
    var pageRequestKey by remember(sourceId, selectedMode, submittedQuery) { mutableIntStateOf(0) }
    var loadingMore by remember(sourceId, selectedMode, submittedQuery) { mutableStateOf(false) }
    var loadMoreError by remember(sourceId, selectedMode, submittedQuery) { mutableStateOf<String?>(null) }
    var localSourceMessage by remember(sourceId) { mutableStateOf<String?>(null) }
    var previewState by remember(sourceId, selectedMode, submittedQuery) {
        mutableStateOf<SourcePreviewUiState>(SourcePreviewUiState.Loading)
    }
    fun openDownloadsFolder() {
        localSourceMessage = if (onOpenExternalUrl(snapshot.runtime.downloadsDir)) {
            "Opening downloads folder"
        } else {
            "Could not open the downloads folder from this platform"
        }
    }

    LaunchedEffect(sourceId, searchKey) {
        if (searchKey != handledSearchKey) {
            handledSearchKey = searchKey
            selectedMode = ChimahonSourceBrowseMode.Search
        }
    }

    LaunchedEffect(sourceId, selectedMode, submittedQuery, pageNumber, pageRequestKey) {
        if (selectedMode == ChimahonSourceBrowseMode.Search && submittedQuery.isBlank()) {
            previewState = SourcePreviewUiState.Idle
            return@LaunchedEffect
        }
        if (pageNumber == 1) {
            previewState = SourcePreviewUiState.Loading
        } else {
            loadingMore = true
        }
        runCatching { onLoadSourcePreview(sourceId, selectedMode, submittedQuery, pageNumber) }
            .onSuccess { loaded ->
                val previous = (previewState as? SourcePreviewUiState.Ready)?.preview
                loadMoreError = null
                previewState = SourcePreviewUiState.Ready(
                    if (pageNumber > 1 && previous != null) {
                        loaded.copy(
                            entries = (previous.entries + loaded.entries).distinctBy { it.url },
                        )
                    } else {
                        loaded
                    },
                )
            }
            .onFailure { error ->
                if (pageNumber == 1) {
                    previewState = SourcePreviewUiState.Failed(error.message ?: "Unable to load source.")
                } else {
                    loadMoreError = error.message ?: "Unable to load more entries."
                }
            }
        loadingMore = false
    }

    Column(modifier = Modifier.fillMaxSize()) {
        SourceBrowseModeTabs(
            modes = modes,
            selected = selectedMode,
            onSelect = { selectedMode = it },
        )
        if (selectedMode == ChimahonSourceBrowseMode.Search) {
            SourceSearchPanel(
                query = searchText,
                onQueryChange = { searchText = it },
                onSearch = {
                    searchText.trim().takeIf(String::isNotEmpty)?.let { submittedQuery = it }
                },
            )
        }
        Box(modifier = Modifier.weight(1f)) {
            when (val preview = previewState) {
                SourcePreviewUiState.Idle -> {
                    EmptyMobileState(
                        marker = "Q",
                        icon = UiIcon.Search,
                        title = "Search ${source.name}",
                        detail = "Enter a title or keyword to search this source.",
                    )
                }
                SourcePreviewUiState.Loading -> {
                    EmptyMobileState(
                        marker = "S",
                        title = "Loading ${selectedMode.title.lowercase()}",
                        detail = "Fetching manga through the shared source engine.",
                    )
                }
                is SourcePreviewUiState.Failed -> {
                    if (isLocalSource) {
                        Column(modifier = Modifier.fillMaxSize()) {
                            EmptyMobileState(
                                marker = "!",
                                icon = UiIcon.Storage,
                                title = "Local source scan failed",
                                detail = preview.message,
                                action = "Retry",
                                onAction = { pageRequestKey++ },
                            )
                            LocalSourceImportPrompt(
                                title = "Open import status",
                                subtitle = "Review local source setup, import scope, and storage prompts.",
                                action = "Open",
                                onAction = onOpenLocalImport,
                            )
                        }
                    } else {
                        EmptyMobileState(
                            marker = "!",
                            title = "Source fetch failed",
                            detail = preview.message,
                            action = "Retry",
                            onAction = { pageRequestKey++ },
                        )
                    }
                }
                is SourcePreviewUiState.Ready -> {
                    val libraryRemoteKeys = snapshot.mangaDetails.values
                        .map { "${it.sourceId}:${it.url}" }
                        .toSet()
                    val sourceLibraryCount = snapshot.mangaDetails.values.count { it.sourceId == source.id }
                    val visiblePreview = preview.preview.copy(
                        entries = preview.preview.entries.filter { entry ->
                            !browseSettings.hideLibraryEntries ||
                                "${entry.sourceId}:${entry.url}" !in libraryRemoteKeys
                        },
                    )
                    if (visiblePreview.entries.isEmpty()) {
                        if (isLocalSource && preview.preview.entries.isEmpty()) {
                            Column(modifier = Modifier.fillMaxSize()) {
                                EmptyMobileState(
                                    marker = "L",
                                    icon = UiIcon.Storage,
                                    title = "No local manga found",
                                    detail = "Create one folder per manga under the platform local source directory, or stage archives in storage before refreshing.",
                                    action = "Open downloads",
                                    onAction = ::openDownloadsFolder,
                                )
                                LocalSourceImportPrompt(
                                    title = "Import status",
                                    subtitle = "See local library counts, category mappings, and folder-opening status.",
                                    action = "Open",
                                    onAction = onOpenLocalImport,
                                )
                                localSourceMessage?.let { message ->
                                    ExtensionStatusRow(
                                        title = "Local source",
                                        subtitle = message,
                                        error = message.startsWith("Could not"),
                                    )
                                }
                            }
                        } else {
                            EmptyMobileState(
                                marker = "S",
                                title = if (preview.preview.entries.isEmpty()) {
                                    "No entries returned"
                                } else {
                                    "No new entries"
                                },
                                detail = if (preview.preview.mode == ChimahonSourceBrowseMode.Search) {
                                    "No results matched \"$submittedQuery\"."
                                } else if (preview.preview.entries.isNotEmpty()) {
                                    "All returned titles are already in your library. Disable Hide library entries to show them."
                                } else {
                                    "${source.name} returned an empty ${preview.preview.mode.title.lowercase()} page."
                                },
                            )
                        }
                    } else {
                        val requestNextPage: () -> Unit = {
                            if (loadMoreError == null) {
                                loadingMore = true
                                pageNumber += 1
                            } else {
                                loadMoreError = null
                                loadingMore = true
                                pageRequestKey += 1
                            }
                        }
                        LaunchedEffect(
                            visiblePreview.entries.size,
                            visiblePreview.hasNextPage,
                            browseSettings.autoLoadMore,
                            loadingMore,
                            loadMoreError,
                        ) {
                            if (
                                browseSettings.autoLoadMore &&
                                visiblePreview.hasNextPage &&
                                !loadingMore &&
                                loadMoreError == null &&
                                visiblePreview.entries.size < SOURCE_CATALOG_PREFETCH_ITEM_COUNT
                            ) {
                                loadingMore = true
                                pageNumber += 1
                            }
                        }
                        if (browseSettings.sourceDisplayMode == ChimahonBrowseSourceDisplayMode.Grid) {
                            val gridState = rememberLazyGridState()
                            LaunchedEffect(
                                gridState,
                                visiblePreview.entries.size,
                                visiblePreview.hasNextPage,
                                browseSettings.autoLoadMore,
                                loadingMore,
                                loadMoreError,
                            ) {
                                if (
                                    !browseSettings.autoLoadMore ||
                                    !visiblePreview.hasNextPage ||
                                    loadingMore ||
                                    loadMoreError != null
                                ) {
                                    return@LaunchedEffect
                                }
                                snapshotFlow {
                                    val layoutInfo = gridState.layoutInfo
                                    val lastVisibleIndex = layoutInfo.visibleItemsInfo.lastOrNull()?.index ?: -1
                                    lastVisibleIndex >= (layoutInfo.totalItemsCount - 6).coerceAtLeast(0)
                                }
                                    .distinctUntilChanged()
                                    .collect { nearEnd ->
                                        if (nearEnd && !loadingMore && loadMoreError == null) {
                                            loadingMore = true
                                            pageNumber += 1
                                        }
                                    }
                            }
                            LazyVerticalGrid(
                                columns = GridCells.Adaptive(124.dp),
                                state = gridState,
                                modifier = Modifier.fillMaxSize(),
                                contentPadding = PaddingValues(10.dp),
                                horizontalArrangement = Arrangement.spacedBy(8.dp),
                                verticalArrangement = Arrangement.spacedBy(14.dp),
                            ) {
                                item(span = { GridItemSpan(maxLineSpan) }) {
                                    SourceDetailHeader(
                                        source = source,
                                        localCount = sourceLibraryCount,
                                    )
                                }
                                item(span = { GridItemSpan(maxLineSpan) }) {
                                    SourcePreviewHeader(visiblePreview)
                                }
                                items(
                                    visiblePreview.entries.withIndex().toList(),
                                    key = { indexed -> remoteMangaLazyKey("source-grid", indexed.index, indexed.value) },
                                ) { indexed ->
                                    val entry = indexed.value
                                    RemoteMangaGridCard(
                                        entry = entry,
                                        inLibrary = "${entry.sourceId}:${entry.url}" in libraryRemoteKeys,
                                        onClick = { onOpenRemoteManga(entry) },
                                    )
                                }
                                if (visiblePreview.hasNextPage) {
                                    item(span = { GridItemSpan(maxLineSpan) }) {
                                        SourceCatalogFooter(
                                            autoLoadMore = browseSettings.autoLoadMore,
                                            loadingMore = loadingMore,
                                            loadMoreError = loadMoreError,
                                            onLoadMore = requestNextPage,
                                        )
                                    }
                                }
                            }
                        } else {
                            val listState = rememberLazyListState()
                            val compactList = browseSettings.sourceDisplayMode == ChimahonBrowseSourceDisplayMode.CompactList
                            LaunchedEffect(
                                listState,
                                visiblePreview.entries.size,
                                visiblePreview.hasNextPage,
                                browseSettings.autoLoadMore,
                                loadingMore,
                                loadMoreError,
                            ) {
                                if (
                                    !browseSettings.autoLoadMore ||
                                    !visiblePreview.hasNextPage ||
                                    loadingMore ||
                                    loadMoreError != null
                                ) {
                                    return@LaunchedEffect
                                }
                                snapshotFlow {
                                    val layoutInfo = listState.layoutInfo
                                    val lastVisibleIndex = layoutInfo.visibleItemsInfo.lastOrNull()?.index ?: -1
                                    lastVisibleIndex >= (layoutInfo.totalItemsCount - 5).coerceAtLeast(0)
                                }
                                    .distinctUntilChanged()
                                    .collect { nearEnd ->
                                        if (nearEnd && !loadingMore && loadMoreError == null) {
                                            loadingMore = true
                                            pageNumber += 1
                                        }
                                    }
                            }
                            LazyColumn(
                                state = listState,
                                modifier = Modifier.fillMaxSize(),
                                contentPadding = PaddingValues(vertical = 8.dp),
                            ) {
                                item {
                                    SourceDetailHeader(
                                        source = source,
                                        localCount = sourceLibraryCount,
                                    )
                                }
                                item {
                                    SourcePreviewHeader(visiblePreview)
                                }
                                items(
                                    visiblePreview.entries.withIndex().toList(),
                                    key = { indexed -> remoteMangaLazyKey("source-list", indexed.index, indexed.value) },
                                ) { indexed ->
                                    val entry = indexed.value
                                    RemoteMangaListRow(
                                        entry = entry,
                                        inLibrary = "${entry.sourceId}:${entry.url}" in libraryRemoteKeys,
                                        compact = compactList,
                                        onClick = { onOpenRemoteManga(entry) },
                                    )
                                }
                                if (visiblePreview.hasNextPage) {
                                    item {
                                        SourceCatalogFooter(
                                            autoLoadMore = browseSettings.autoLoadMore,
                                            loadingMore = loadingMore,
                                            loadMoreError = loadMoreError,
                                            onLoadMore = requestNextPage,
                                        )
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun SourceBrowseModeTabs(
    modes: List<ChimahonSourceBrowseMode>,
    selected: ChimahonSourceBrowseMode,
    onSelect: (ChimahonSourceBrowseMode) -> Unit,
) {
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .background(ChimahonPalette.surface),
    ) {
        Row(modifier = Modifier.fillMaxWidth()) {
            modes.forEach { mode ->
                val isSelected = mode == selected
                Column(
                    modifier = Modifier
                        .weight(1f)
                        .clickable { onSelect(mode) },
                    horizontalAlignment = Alignment.CenterHorizontally,
                ) {
                    Box(
                        modifier = Modifier.height(45.dp),
                        contentAlignment = Alignment.Center,
                    ) {
                        Label(
                            mode.title,
                            if (isSelected) ChimahonPalette.primary else ChimahonPalette.secondaryText,
                            13,
                            weight = if (isSelected) FontWeight.SemiBold else FontWeight.Medium,
                            maxLines = 1,
                        )
                    }
                    Box(
                        modifier = Modifier
                            .width(42.dp)
                            .height(3.dp)
                            .clip(RoundedCornerShape(topStart = 2.dp, topEnd = 2.dp))
                            .background(if (isSelected) ChimahonPalette.primary else Color.Transparent),
                    )
                }
            }
        }
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(1.dp)
                .background(ChimahonPalette.divider),
        )
    }
}

@Composable
private fun SourceSearchPanel(
    query: String,
    onQueryChange: (String) -> Unit,
    onSearch: () -> Unit,
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .background(ChimahonPalette.surface)
            .padding(horizontal = 12.dp, vertical = 8.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(10.dp),
    ) {
        Box(
            modifier = Modifier
                .weight(1f)
                .height(42.dp)
                .clip(RoundedCornerShape(22.dp))
                .background(ChimahonPalette.surfaceVariant)
                .padding(horizontal = 12.dp),
            contentAlignment = Alignment.CenterStart,
        ) {
            if (query.isBlank()) {
                Label("Search manga", ChimahonPalette.secondaryText, 12, maxLines = 1)
            }
            BasicTextField(
                value = query,
                onValueChange = onQueryChange,
                singleLine = true,
                textStyle = TextStyle(
                    color = ChimahonPalette.onSurface,
                    fontSize = 13.sp,
                    lineHeight = 17.sp,
                ),
                modifier = Modifier.fillMaxWidth(),
            )
        }
        TextButtonLike(
            text = "Search",
            onClick = onSearch,
        )
    }
}

@Composable
private fun SourceDetailHeader(
    source: ChimahonSourceEntry,
    localCount: Int,
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(6.dp))
            .background(ChimahonPalette.surface)
