@Composable
private fun RemoteMangaDetailHome(
    remoteManga: ChimahonRemoteMangaEntry,
    existingMangaId: Long?,
    onLoadRemoteMangaDetail: suspend (ChimahonRemoteMangaEntry) -> ChimahonRemoteMangaDetail,
    onOpenReader: (ChimahonReaderRequest) -> Unit,
    onOpenLibraryManga: (Long) -> Unit,
    onOpenRemoteMangaUrl: (ChimahonRemoteMangaDetail) -> Boolean,
    onAddToLibrary: suspend (ChimahonRemoteMangaDetail) -> Unit,
) {
    var refreshKey by remember(remoteManga.sourceId, remoteManga.url) { mutableIntStateOf(0) }
    var detailState by remember(remoteManga.sourceId, remoteManga.url) {
        mutableStateOf<RemoteMangaDetailUiState>(RemoteMangaDetailUiState.Loading)
    }

    LaunchedEffect(remoteManga.sourceId, remoteManga.url, refreshKey) {
        detailState = RemoteMangaDetailUiState.Loading
        detailState = runCatching { onLoadRemoteMangaDetail(remoteManga) }
            .fold(
                onSuccess = RemoteMangaDetailUiState::Ready,
                onFailure = { RemoteMangaDetailUiState.Failed(it.message ?: "Unable to load manga details.") },
            )
    }

    when (val detail = detailState) {
        RemoteMangaDetailUiState.Loading -> {
            EmptyMobileState(
                marker = "M",
                title = "Loading manga",
                detail = "Fetching details and chapters through the shared source engine.",
                action = "Retry",
                onAction = { refreshKey++ },
            )
        }
        is RemoteMangaDetailUiState.Failed -> {
            EmptyMobileState(
                marker = "!",
                title = "Manga fetch failed",
                detail = detail.message,
                action = "Retry",
                onAction = { refreshKey++ },
            )
        }
        is RemoteMangaDetailUiState.Ready -> {
            RemoteMangaDetailContent(
                detail = detail.detail,
                existingMangaId = existingMangaId,
                onOpenReader = onOpenReader,
                onOpenLibraryManga = onOpenLibraryManga,
                onOpenRemoteMangaUrl = onOpenRemoteMangaUrl,
                onAddToLibrary = onAddToLibrary,
            )
        }
    }
}

@Composable
private fun RemoteMangaDetailContent(
    detail: ChimahonRemoteMangaDetail,
    existingMangaId: Long?,
    onOpenReader: (ChimahonReaderRequest) -> Unit,
    onOpenLibraryManga: (Long) -> Unit,
    onOpenRemoteMangaUrl: (ChimahonRemoteMangaDetail) -> Boolean,
    onAddToLibrary: suspend (ChimahonRemoteMangaDetail) -> Unit,
) {
    var chapterDescending by remember(detail.sourceId, detail.url) { mutableStateOf(true) }
    var chapterSort by remember(detail.sourceId, detail.url) { mutableStateOf(ChapterSort.SourceOrder) }
    var chapterFilter by remember(detail.sourceId, detail.url) { mutableStateOf(RemoteChapterFilter.All) }
    var chapterFiltersVisible by remember(detail.sourceId, detail.url) { mutableStateOf(false) }
    var chapterQuery by remember(detail.sourceId, detail.url) { mutableStateOf("") }
    val updateRemoteChapterSort: (ChapterSort) -> Unit = { sort ->
        val nextDescending = if (sort == chapterSort) {
            !chapterDescending
        } else {
            sort.defaultPersistedDescending()
        }
        chapterSort = sort
        chapterDescending = nextDescending
    }
    val clearRemoteChapterFilters: () -> Unit = {
        chapterFilter = RemoteChapterFilter.All
        chapterSort = ChapterSort.SourceOrder
        chapterDescending = true
        chapterQuery = ""
    }
    val chapterSummary = detail.chapters.toRemoteChapterListSummary()
    val searchedChapters = detail.chapters
        .filter { it.matchesRemoteChapterFilter(chapterFilter) }
        .filter { it.matchesRemoteChapterQuery(chapterQuery) }
    val visibleChapters = searchedChapters.sortedForRemoteDetail(
        sort = chapterSort,
        descending = chapterDescending,
    )
    BoxWithConstraints(modifier = Modifier.fillMaxSize()) {
        if (maxWidth >= 900.dp) {
            Row(modifier = Modifier.fillMaxSize()) {
                Column(
                    modifier = Modifier
                        .weight(0.42f)
                        .fillMaxHeight()
                        .verticalScroll(rememberScrollState())
                        .padding(horizontal = 12.dp, vertical = 10.dp),
                ) {
                    RemoteMangaDetailHeader(
                        detail = detail,
                        centered = true,
                    )
                    RemoteMangaActionRow(
                        detail = detail,
                        existingMangaId = existingMangaId,
                        onOpenReader = onOpenReader,
                        onOpenLibraryManga = onOpenLibraryManga,
                        onOpenRemoteMangaUrl = onOpenRemoteMangaUrl,
                        onAddToLibrary = onAddToLibrary,
                        modifier = Modifier.padding(top = 8.dp),
                    )
                    RemoteMangaDescriptionPanel(
                        detail = detail,
                        modifier = Modifier.padding(top = 6.dp),
                    )
                }
                Box(
                    modifier = Modifier
                        .width(1.dp)
                        .fillMaxHeight()
                        .background(ChimahonPalette.divider),
                )
                RemoteChapterPane(
                    detail = detail.copy(chapters = visibleChapters),
                    allChapterCount = detail.chapters.size,
                    summary = chapterSummary,
                    selectedFilter = chapterFilter,
                    filtersVisible = chapterFiltersVisible,
                    selectedSort = chapterSort,
                    descending = chapterDescending,
                    query = chapterQuery,
                    onToggleFilters = { chapterFiltersVisible = !chapterFiltersVisible },
                    onQueryChange = { chapterQuery = it },
                    onFilterChange = { chapterFilter = it },
                    onSortChange = updateRemoteChapterSort,
                    onSortDirectionChange = { chapterDescending = it },
                    onClearFilters = clearRemoteChapterFilters,
                    onOpenReader = onOpenReader,
                    modifier = Modifier
                        .weight(0.58f)
                        .fillMaxHeight(),
                )
            }
        } else {
            LazyColumn(
                modifier = Modifier.fillMaxSize(),
                contentPadding = PaddingValues(vertical = 12.dp),
            ) {
                item {
                    RemoteMangaDetailHeader(
                        detail = detail,
                        modifier = Modifier.padding(horizontal = 16.dp),
                    )
                }
                item {
                    RemoteMangaActionRow(
                        detail = detail,
                        existingMangaId = existingMangaId,
                        onOpenReader = onOpenReader,
                        onOpenLibraryManga = onOpenLibraryManga,
                        onOpenRemoteMangaUrl = onOpenRemoteMangaUrl,
                        onAddToLibrary = onAddToLibrary,
                        modifier = Modifier.padding(horizontal = 12.dp, vertical = 8.dp),
                    )
                }
                item {
                    RemoteMangaDescriptionPanel(
                        detail = detail,
                        modifier = Modifier.padding(horizontal = 12.dp),
                    )
                }
                item {
                    RemoteChapterHeader(
                        chapters = visibleChapters,
                        allChapterCount = detail.chapters.size,
                        selectedFilter = chapterFilter,
                        filtersVisible = chapterFiltersVisible,
                        selectedSort = chapterSort,
                        descending = chapterDescending,
                        query = chapterQuery,
                        onToggleFilters = { chapterFiltersVisible = !chapterFiltersVisible },
                        onSortDirectionChange = { chapterDescending = it },
                        modifier = Modifier.padding(top = 12.dp),
                    )
                }
                if (chapterFiltersVisible) {
                    item {
                        RemoteChapterFilterPanel(
                            selectedFilter = chapterFilter,
                            selectedSort = chapterSort,
                            descending = chapterDescending,
                            summary = chapterSummary,
                            query = chapterQuery,
                            onQueryChange = { chapterQuery = it },
                            onFilterChange = { chapterFilter = it },
                            onSortChange = updateRemoteChapterSort,
                            onSortDirectionChange = { chapterDescending = it },
                            onClearFilters = clearRemoteChapterFilters,
                        )
                    }
                }
                if (visibleChapters.isEmpty()) {
                    item {
                        EmptyListPanel(
                            marker = "C",
                            title = if (detail.chapters.isEmpty()) "No chapters returned" else "No matching chapters",
                            detail = if (detail.chapters.isEmpty()) {
                                "${detail.sourceName} did not return chapters for this manga."
                            } else {
                                "Try changing the source chapter filters or search term."
                            },
                        )
                    }
                } else {
                    items(
                        visibleChapters.withIndex().toList(),
                        key = { indexed -> remoteChapterLazyKey("remote", indexed.index, indexed.value) },
                    ) { indexed ->
                        val chapter = indexed.value
                        RemoteChapterListItem(
                            chapter = chapter,
                            onClick = {
                                onOpenReader(chapter.toReaderRequest(detail, visibleChapters))
                            },
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun RemoteChapterPane(
    detail: ChimahonRemoteMangaDetail,
    allChapterCount: Int,
    summary: RemoteChapterListSummary,
    selectedFilter: RemoteChapterFilter,
    filtersVisible: Boolean,
    selectedSort: ChapterSort,
    descending: Boolean,
    query: String,
    onToggleFilters: () -> Unit,
    onQueryChange: (String) -> Unit,
    onFilterChange: (RemoteChapterFilter) -> Unit,
    onSortChange: (ChapterSort) -> Unit,
    onSortDirectionChange: (Boolean) -> Unit,
    onClearFilters: () -> Unit,
    onOpenReader: (ChimahonReaderRequest) -> Unit,
    modifier: Modifier = Modifier,
) {
    LazyColumn(
        modifier = modifier,
        contentPadding = PaddingValues(top = 10.dp, bottom = 18.dp),
    ) {
        item {
            RemoteChapterHeader(
                chapters = detail.chapters,
                allChapterCount = allChapterCount,
                selectedFilter = selectedFilter,
                filtersVisible = filtersVisible,
                selectedSort = selectedSort,
                descending = descending,
                query = query,
                onToggleFilters = onToggleFilters,
                onSortDirectionChange = onSortDirectionChange,
            )
        }
        if (filtersVisible) {
            item {
                RemoteChapterFilterPanel(
                    selectedFilter = selectedFilter,
                    selectedSort = selectedSort,
                    descending = descending,
                    summary = summary,
                    query = query,
                    onQueryChange = onQueryChange,
                    onFilterChange = onFilterChange,
                    onSortChange = onSortChange,
                    onSortDirectionChange = onSortDirectionChange,
                    onClearFilters = onClearFilters,
                )
            }
        }
        if (detail.chapters.isEmpty()) {
            item {
                EmptyListPanel(
                    marker = "C",
                    title = if (allChapterCount == 0) "No chapters returned" else "No matching chapters",
                    detail = if (allChapterCount == 0) {
                        "${detail.sourceName} did not return chapters for this manga."
                    } else {
                        "Try changing the source chapter filters or search term."
                    },
                )
            }
        } else {
            items(
                detail.chapters.withIndex().toList(),
                key = { indexed -> remoteChapterLazyKey("remote-pane", indexed.index, indexed.value) },
            ) { indexed ->
                val chapter = indexed.value
                RemoteChapterListItem(
                    chapter = chapter,
                    onClick = {
                        onOpenReader(chapter.toReaderRequest(detail, detail.chapters))
                    },
                )
            }
        }
    }
}

@Composable
