@Composable
private fun RemoteMangaActionRow(
    detail: ChimahonRemoteMangaDetail,
    existingMangaId: Long?,
    onOpenReader: (ChimahonReaderRequest) -> Unit,
    onOpenLibraryManga: (Long) -> Unit,
    onOpenRemoteMangaUrl: (ChimahonRemoteMangaDetail) -> Boolean,
    onAddToLibrary: suspend (ChimahonRemoteMangaDetail) -> Unit,
    modifier: Modifier = Modifier,
) {
    var adding by remember(detail.sourceId, detail.url) { mutableStateOf(false) }
    var addError by remember(detail.sourceId, detail.url) { mutableStateOf<String?>(null) }
    var openError by remember(detail.sourceId, detail.url) { mutableStateOf<String?>(null) }
    val hasChapters = detail.chapters.isNotEmpty()
    val scope = rememberCoroutineScope()

    Column(modifier = modifier) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .clip(RoundedCornerShape(8.dp))
                .background(ChimahonPalette.surface)
                .border(1.dp, ChimahonPalette.divider.copy(alpha = 0.56f), RoundedCornerShape(8.dp))
                .padding(horizontal = 2.dp, vertical = 3.dp),
            horizontalArrangement = Arrangement.SpaceEvenly,
        ) {
            MangaActionButton(
                icon = UiIcon.Play,
                title = if (hasChapters) "Start" else "No chapters",
                enabled = hasChapters,
                modifier = Modifier.weight(1f),
                onClick = {
                    addError = null
                    openError = null
                    val startQueue = detail.chapters.remoteStartReadingOrder()
                    startQueue.lastOrNull()?.let { chapter ->
                        onOpenReader(chapter.toReaderRequest(detail, startQueue))
                    }
                },
            )
            MangaActionButton(
                icon = if (existingMangaId != null) UiIcon.Favorite else UiIcon.FavoriteBorder,
                title = when {
                    existingMangaId != null -> "Library"
                    adding -> "Adding"
                    else -> "Add"
                },
                active = existingMangaId != null || adding,
                enabled = existingMangaId != null || !adding,
                modifier = Modifier.weight(1f),
                onClick = {
                    if (existingMangaId != null) {
                        addError = null
                        openError = null
                        onOpenLibraryManga(existingMangaId)
                    } else if (!adding) {
                        scope.launch {
                            adding = true
                            addError = null
                            openError = null
                            runCatching { onAddToLibrary(detail) }
                                .onFailure { addError = it.message ?: "Could not add manga to the library." }
                            adding = false
                        }
                    }
                },
            )
            MangaActionButton(
                icon = UiIcon.Web,
                title = "Source",
                modifier = Modifier.weight(1f),
                onClick = {
                    addError = null
                    openError = null
                    if (!onOpenRemoteMangaUrl(detail)) {
                        openError = "Could not open this manga in the source website."
                    }
                },
            )
        }
        (addError ?: openError)?.let { message ->
            Label(
                text = message,
                color = ChimahonPalette.error,
                size = 11,
                lineHeight = 16,
                maxLines = 3,
                modifier = Modifier.padding(top = 8.dp, start = 4.dp, end = 4.dp),
            )
        }
    }
}

@Composable
private fun RemoteMangaDescriptionPanel(
    detail: ChimahonRemoteMangaDetail,
    modifier: Modifier = Modifier,
) {
    var expanded by remember(detail.sourceId, detail.url) { mutableStateOf(false) }
    Column(
        modifier = modifier
            .fillMaxWidth()
            .padding(horizontal = 4.dp, vertical = 8.dp),
    ) {
        SectionHeader("About")
        Label(
            text = detail.description?.takeIf { it.isNotBlank() } ?: "No description available.",
            color = ChimahonPalette.onSurface,
            size = 13,
            lineHeight = 19,
            maxLines = if (expanded) Int.MAX_VALUE else 7,
            modifier = Modifier.padding(top = 4.dp),
        )
        if (!detail.description.isNullOrBlank()) {
            Label(
                if (expanded) "Show less" else "Show more",
                ChimahonPalette.primary,
                11,
                weight = FontWeight.SemiBold,
                maxLines = 1,
                modifier = Modifier
                    .clickable { expanded = !expanded }
                    .padding(vertical = 7.dp),
            )
        }
        if (detail.genres.isNotEmpty()) {
            FilterChips(
                chips = detail.genres,
                selected = "",
                modifier = Modifier.padding(top = 12.dp),
            )
        }
    }
}

@Composable
private fun RemoteChapterHeader(
    chapters: List<ChimahonRemoteChapterEntry>,
    allChapterCount: Int,
    selectedCount: Int = 0,
    selectedFilter: RemoteChapterFilter,
    filtersVisible: Boolean,
    selectedSort: ChapterSort,
    descending: Boolean,
    query: String,
    onToggleFilters: () -> Unit,
    onSortDirectionChange: (Boolean) -> Unit,
    modifier: Modifier = Modifier,
) {
    Column(
        modifier = modifier
            .fillMaxWidth()
            .background(ChimahonPalette.surface)
            .border(1.dp, ChimahonPalette.divider.copy(alpha = 0.45f))
            .padding(top = 8.dp, bottom = 7.dp),
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 16.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Column(modifier = Modifier.weight(1f)) {
                Label(
                    if (selectedCount > 0) "$selectedCount selected" else "Chapters",
                    ChimahonPalette.onSurface,
                    15,
                    weight = FontWeight.SemiBold,
                    maxLines = 1,
                )
                Label(
                    if (chapters.size == allChapterCount) {
                        "$allChapterCount source chapters"
                    } else {
                        "${chapters.size} of $allChapterCount source chapters"
                    },
                    if (selectedCount > 0) ChimahonPalette.primary else ChimahonPalette.secondaryText,
                    11,
                    maxLines = 1,
                    modifier = Modifier.padding(top = 2.dp),
                )
            }
            Row(horizontalArrangement = Arrangement.spacedBy(2.dp)) {
                ChapterHeaderAction(
                    icon = UiIcon.Swap,
                    contentDescription = chapterSortDirectionTitle(selectedSort, !descending),
                    active = selectedSort != ChapterSort.SourceOrder || !descending,
                    onClick = { onSortDirectionChange(!descending) },
                )
                ChapterHeaderAction(
                    icon = UiIcon.Filter,
                    contentDescription = "Chapter filters",
                    active = filtersVisible,
                    onClick = onToggleFilters,
                )
            }
        }
        val summaryItems = listOfNotNull(
            "${chapters.size} visible" to false,
            selectedFilter.takeIf { it != RemoteChapterFilter.All }?.title?.let { it to true },
            selectedSort.title to (selectedSort != ChapterSort.SourceOrder),
            chapterSortDirectionTitle(selectedSort, descending) to (selectedSort != ChapterSort.SourceOrder || !descending),
            query.takeIf { it.isNotBlank() }?.let { "Search" to true },
        )
        LazyRow(
            contentPadding = PaddingValues(start = 16.dp, end = 16.dp, top = 7.dp),
            horizontalArrangement = Arrangement.spacedBy(6.dp),
        ) {
            items(summaryItems.withIndex().toList(), key = { "${it.index}:${it.value.first}" }) { indexed ->
                val item = indexed.value
                ChapterSummaryPill(text = item.first, active = item.second)
            }
        }
    }
}

@Composable
private fun RemoteChapterFilterPanel(
    selectedFilter: RemoteChapterFilter,
    selectedSort: ChapterSort,
    descending: Boolean,
    summary: RemoteChapterListSummary,
    query: String,
    onQueryChange: (String) -> Unit,
    onFilterChange: (RemoteChapterFilter) -> Unit,
    onSortChange: (ChapterSort) -> Unit,
    onSortDirectionChange: (Boolean) -> Unit,
    onClearFilters: () -> Unit,
) {
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .background(ChimahonPalette.surface)
            .padding(start = 12.dp, end = 12.dp, bottom = 12.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Box(
            modifier = Modifier
                .padding(top = 6.dp, bottom = 8.dp)
                .width(38.dp)
                .height(4.dp)
                .clip(CircleShape)
                .background(ChimahonPalette.divider),
        )
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(bottom = 6.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Column(modifier = Modifier.weight(1f)) {
                Label("Chapter filters", ChimahonPalette.onSurface, 14, weight = FontWeight.SemiBold, maxLines = 1)
                Label(
                    "${summary.totalCount} source chapters - ${summary.datedCount} dated - ${summary.scanlatorCount} grouped",
                    ChimahonPalette.secondaryText,
                    11,
                    maxLines = 1,
                )
            }
            if (
                selectedFilter != RemoteChapterFilter.All ||
                selectedSort != ChapterSort.SourceOrder ||
                !descending ||
                query.isNotBlank()
            ) {
                TextButtonLike("Reset", onClick = onClearFilters)
            }
        }
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(42.dp)
                .clip(RoundedCornerShape(8.dp))
                .background(ChimahonPalette.background)
                .border(1.dp, ChimahonPalette.divider, RoundedCornerShape(8.dp))
                .padding(horizontal = 12.dp),
            contentAlignment = Alignment.CenterStart,
        ) {
            IconGlyph(
                icon = UiIcon.Search,
                contentDescription = "Search chapters",
                tint = ChimahonPalette.secondaryText,
                modifier = Modifier.size(17.dp),
            )
            if (query.isBlank()) {
                Label(
                    "Search chapters",
                    ChimahonPalette.secondaryText,
                    12,
                    maxLines = 1,
                    modifier = Modifier.padding(start = 26.dp),
                )
            }
            BasicTextField(
                value = query,
                onValueChange = onQueryChange,
                singleLine = true,
                textStyle = TextStyle(
                    color = ChimahonPalette.onSurface,
                    fontSize = 13.sp,
                    lineHeight = 17.sp,
                ),
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(start = 26.dp),
            )
        }
        FilterPanelLabel(
            "Show  -  ${summary.numberedCount} numbered, ${summary.unknownDateCount} unknown date",
            modifier = Modifier
                .fillMaxWidth()
                .padding(top = 10.dp, bottom = 4.dp),
        )
        ScrollableFilterChips(
            chips = RemoteChapterFilter.entries.map { it.title },
            selected = selectedFilter.title,
            onSelect = { title ->
                RemoteChapterFilter.entries.firstOrNull { it.title == title }?.let(onFilterChange)
            },
            modifier = Modifier.padding(vertical = 2.dp),
        )
        FilterPanelLabel(
            "Sort by",
            modifier = Modifier
                .fillMaxWidth()
                .padding(top = 10.dp, bottom = 4.dp),
        )
        ScrollableFilterChips(
            chips = ChapterSort.entries.map { it.title },
            selected = selectedSort.title,
            onSelect = { title ->
                ChapterSort.entries.firstOrNull { it.title == title }?.let(onSortChange)
            },
            modifier = Modifier.padding(vertical = 2.dp),
        )
        FilterPanelLabel(
            "Direction",
            modifier = Modifier
                .fillMaxWidth()
                .padding(top = 10.dp, bottom = 4.dp),
        )
        SegmentTabs(
            values = listOf(true, false),
            selected = descending,
            label = { chapterSortDirectionTitle(selectedSort, it) },
            onSelect = onSortDirectionChange,
            modifier = Modifier.padding(top = 10.dp),
        )
    }
}

