@Composable
private fun ReaderHome(
    request: ChimahonReaderRequest,
    initialBookmarked: Boolean,
    onLoadReaderChapter: suspend (ChimahonReaderRequest) -> ChimahonReaderChapter,
    onLoadReaderPageImage: suspend (ChimahonReaderPage) -> ByteArray,
    onLoadReaderOcrBlocks: suspend (ChimahonReaderPage, ChimahonDictionarySettings) -> List<ChimahonReaderOcrBlock>,
    settings: ChimahonReaderSettings,
    dictionarySettings: ChimahonDictionarySettings,
    onSettingsChange: (ChimahonReaderSettings) -> Unit,
    onSaveReaderProgress: suspend (ChimahonReaderRequest, Int, Boolean) -> Unit,
    onSetChapterRead: suspend (Long, Boolean) -> Unit,
    onSetChapterBookmark: suspend (Long, Boolean) -> Unit,
    onEnqueueDownload: suspend (Long) -> ChimahonDownloadQueueData,
    onOpenExternalUrl: (String) -> Boolean,
    onOpenReader: (ChimahonReaderRequest) -> Unit,
    onCloseReader: () -> Unit,
    desktopCommandRequest: ChimahonDesktopCommandRequest? = null,
    onDesktopCommandHandled: (Long) -> Unit = {},
) {
    var refreshKey by remember(request) { mutableIntStateOf(0) }
    var state by remember(request) {
        mutableStateOf<ReaderUiState>(ReaderUiState.Loading)
    }

    LaunchedEffect(request, refreshKey) {
        state = ReaderUiState.Loading
        if (settings.readerStartupDelay) {
            delay(250)
        }
        state = runCatching { onLoadReaderChapter(request) }
            .fold(
                onSuccess = ReaderUiState::Ready,
                onFailure = { ReaderUiState.Failed(it.message ?: "Unable to load chapter pages.") },
            )
    }
    LaunchedEffect(desktopCommandRequest?.id, state) {
        val commandRequest = desktopCommandRequest ?: return@LaunchedEffect
        if (!commandRequest.command.readerScoped) return@LaunchedEffect
        val readyState = state as? ReaderUiState.Ready
        if (readyState == null || readyState.chapter.pages.isEmpty()) {
            onDesktopCommandHandled(commandRequest.id)
        }
    }

    when (val readerState = state) {
        ReaderUiState.Loading -> {
            ReaderStatusScreen(
                request = request,
                marker = "...",
                title = "Loading chapter",
                detail = "Fetching the page list from the source.",
                onBack = onCloseReader,
            )
        }
        is ReaderUiState.Failed -> {
            ReaderStatusScreen(
                request = request,
                marker = "!",
                title = "Chapter failed",
                detail = readerState.message,
                action = "Retry",
                onAction = { refreshKey++ },
                onBack = onCloseReader,
            )
        }
        is ReaderUiState.Ready -> {
            if (readerState.chapter.pages.isEmpty()) {
                ReaderStatusScreen(
                    request = request,
                    marker = "0",
                    title = "No pages found",
                    detail = "The source returned an empty page list for this chapter.",
                    onBack = onCloseReader,
                )
            } else {
                ReaderContent(
                    chapter = readerState.chapter,
                    initialBookmarked = initialBookmarked,
                    onLoadReaderPageImage = onLoadReaderPageImage,
                    onLoadReaderOcrBlocks = onLoadReaderOcrBlocks,
                    settings = settings,
                    dictionarySettings = dictionarySettings,
                    onSettingsChange = onSettingsChange,
                    onSaveReaderProgress = onSaveReaderProgress,
                    onSetChapterRead = onSetChapterRead,
                    onSetChapterBookmark = onSetChapterBookmark,
                    onEnqueueDownload = onEnqueueDownload,
                    onOpenExternalUrl = onOpenExternalUrl,
                    onOpenReader = onOpenReader,
                    onCloseReader = onCloseReader,
                    desktopCommandRequest = desktopCommandRequest,
                    onDesktopCommandHandled = onDesktopCommandHandled,
                )
            }
        }
    }
}

@Composable
private fun ReaderStatusScreen(
    request: ChimahonReaderRequest,
    marker: String,
    title: String,
    detail: String,
    onBack: () -> Unit,
    action: String? = null,
    onAction: () -> Unit = {},
) {
    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(ReaderPalette.background),
    ) {
        ReaderTopBar(
            request = request,
            currentPage = 0,
            pageCount = 0,
            bookmarked = false,
            bookmarkBusy = false,
            onBack = onBack,
            onToggleBookmark = null,
        )
        Box(modifier = Modifier.weight(1f)) {
            ReaderMessage(
                marker = marker,
                title = title,
                detail = detail,
                action = action,
                onAction = onAction,
            )
        }
    }
}

@Composable
private fun ReaderContent(
    chapter: ChimahonReaderChapter,
    initialBookmarked: Boolean,
    onLoadReaderPageImage: suspend (ChimahonReaderPage) -> ByteArray,
    onLoadReaderOcrBlocks: suspend (ChimahonReaderPage, ChimahonDictionarySettings) -> List<ChimahonReaderOcrBlock>,
    settings: ChimahonReaderSettings,
    dictionarySettings: ChimahonDictionarySettings,
    onSettingsChange: (ChimahonReaderSettings) -> Unit,
    onSaveReaderProgress: suspend (ChimahonReaderRequest, Int, Boolean) -> Unit,
    onSetChapterRead: suspend (Long, Boolean) -> Unit,
    onSetChapterBookmark: suspend (Long, Boolean) -> Unit,
    onEnqueueDownload: suspend (Long) -> ChimahonDownloadQueueData,
    onOpenExternalUrl: (String) -> Boolean,
    onOpenReader: (ChimahonReaderRequest) -> Unit,
    onCloseReader: () -> Unit,
    desktopCommandRequest: ChimahonDesktopCommandRequest? = null,
    onDesktopCommandHandled: (Long) -> Unit = {},
) {
    var readerPreferences by remember(chapter.request) { mutableStateOf(settings) }
    var mode by remember(chapter.request) { mutableStateOf(settings.initialReaderMode(chapter)) }
    var scale by remember(chapter.request.mangaId) { mutableStateOf(settings.scale.toUiReaderScale()) }
    var canvas by remember(chapter.request.mangaId) { mutableStateOf(settings.canvas.toUiReaderCanvas()) }
    var controlsVisible by remember(chapter.request) {
        mutableStateOf(settings.keepControlsVisible || settings.showNavigationOverlayOnStart)
    }
    var settingsVisible by remember(chapter.request) { mutableStateOf(false) }
    var chaptersVisible by remember(chapter.request) { mutableStateOf(false) }
    var statsVisible by remember(chapter.request) { mutableStateOf(false) }
    var showPageStrip by remember(chapter.request.mangaId) { mutableStateOf(settings.showPageStrip) }
    var showControlsOnStart by remember(chapter.request.mangaId) {
        mutableStateOf(settings.keepControlsVisible)
    }
    var bookmarked by remember(chapter.request.chapterId) { mutableStateOf(initialBookmarked) }
    var bookmarkBusy by remember(chapter.request.chapterId) { mutableStateOf(false) }
    var readBusy by remember(chapter.request.chapterId) { mutableStateOf(false) }
    var downloadBusy by remember(chapter.request.chapterId) { mutableStateOf(false) }
    var ocrLookupToggleSignal by remember(chapter.request) { mutableIntStateOf(0) }
    var retainedPage by remember(chapter.request) {
        mutableIntStateOf(
            if (settings.preserveReadingPosition) {
                chapter.request.initialPage.coerceIn(chapter.pages.indices)
            } else {
                0
            },
        )
    }
    val readerStartedAt = remember(chapter.request) { TimeSource.Monotonic.markNow() }
    var inputLocked by remember(chapter.request) { mutableStateOf(readerPreferences.readerStartupDelay) }
    val pageStates = remember(chapter.request) {
        mutableStateMapOf<Int, ReaderPageUiState>()
    }
    LaunchedEffect(chapter.request, readerPreferences.readerStartupDelay) {
        if (readerPreferences.readerStartupDelay) {
            inputLocked = true
            delay(650)
        }
        inputLocked = false
    }
    val previousChapter = chapter.request.chapterQueue.readerAdjacentChapter(
        currentIndex = chapter.request.chapterIndex,
        step = 1,
        settings = readerPreferences,
    )
    val nextChapter = chapter.request.chapterQueue.readerAdjacentChapter(
        currentIndex = chapter.request.chapterIndex,
        step = -1,
        settings = readerPreferences,
    )
    val scope = rememberCoroutineScope()
    val preloadWindow = if (readerPreferences.aggressivePageLoading) {
        readerPreferences.preloadSize.coerceIn(4, 20)
    } else {
        min(readerPreferences.preloadSize, 6).coerceIn(1, 12)
    }
    val preloadReaderPage: suspend (Int) -> Unit = { pageIndex ->
        if (pageIndex in chapter.pages.indices && pageStates[pageIndex] == null) {
            pageStates[pageIndex] = ReaderPageUiState.Loading
            pageStates[pageIndex] = runCatching {
                onLoadReaderPageImage(chapter.pages[pageIndex]).decodeToImageBitmap()
            }.fold(
                onSuccess = ReaderPageUiState::Ready,
                onFailure = { ReaderPageUiState.Failed(it.message ?: "Unable to decode page image.") },
            )
        }
    }
    val saveReaderPreferences: (ChimahonReaderSettings) -> Unit = { updated ->
        readerPreferences = updated
        onSettingsChange(updated)
    }
    val updateScalePreference: (ReaderScale) -> Unit = { updatedScale ->
        scale = updatedScale
        saveReaderPreferences(
            readerPreferences.copy(
                mode = mode.toSettingsReaderMode(),
                scale = updatedScale.toSettingsReaderScale(),
                canvas = canvas.toSettingsReaderCanvas(),
                showPageStrip = showPageStrip,
                keepControlsVisible = showControlsOnStart,
            ),
        )
    }
    val openAdjacentChapter: (ChimahonReaderChapterRef) -> Unit = { adjacent ->
        onOpenReader(adjacent.toReaderRequest(chapter.request))
    }
    val bookmarkChapterRef: (ChimahonReaderChapterRef) -> Unit = { ref ->
        ref.chapterId?.let { chapterId ->
            scope.launch {
                runCatching { onSetChapterBookmark(chapterId, !ref.bookmarked) }
            }
        }
    }
    val downloadChapterRef: (ChimahonReaderChapterRef) -> Unit = { ref ->
        ref.chapterId?.let { chapterId ->
            scope.launch {
                runCatching { onEnqueueDownload(chapterId) }
            }
        }
    }
    val markChapterRefRead: (ChimahonReaderChapterRef) -> Unit = { ref ->
        ref.chapterId?.let { chapterId ->
            scope.launch {
                runCatching { onSetChapterRead(chapterId, !ref.read) }
            }
        }
    }
    val markChapterRead = chapter.request.chapterId?.let { chapterId ->
        {
            if (!readBusy) {
                scope.launch {
                    readBusy = true
                    runCatching {
                        onSetChapterRead(chapterId, true)
                        onSaveReaderProgress(chapter.request, chapter.pages.lastIndex, true)
                    }
                    readBusy = false
                }
            }
        }
    }
    val downloadChapter = chapter.request.chapterId?.let { chapterId ->
        {
            if (!downloadBusy) {
                scope.launch {
                    downloadBusy = true
                    runCatching { onEnqueueDownload(chapterId) }
                    downloadBusy = false
                }
            }
        }
    }
    val openChapterUrl: (() -> Unit)? = chapter.request.chapterUrl
        .takeIf { it.isNotBlank() }
        ?.let { url -> { onOpenExternalUrl(url) } }
    val shareChapterUrl: (() -> Unit)? = chapter.request.chapterUrl
        .takeIf { it.isNotBlank() }
        ?.let { url ->
            {
                ChimahonPlatformIntegration.shareText(
                    text = url,
                    title = chapter.request.mangaTitle.ifBlank { APP_NAME },
                )
            }
        }
    val toggleControls = {
        controlsVisible = !controlsVisible
        if (!controlsVisible) {
            settingsVisible = false
            chaptersVisible = false
            statsVisible = false
        }
    }
    val toggleReaderOcrLookup = {
        ocrLookupToggleSignal += 1
        settingsVisible = false
        chaptersVisible = false
        statsVisible = false
    }

    key(mode, readerPreferences.dualPageMode) {
        if (mode.paged) {
            val dualPage = readerPreferences.dualPageMode != ChimahonDualPageMode.Off
            val spreadGroups = remember(chapter.pages, dualPage) {
                if (dualPage) {
                    chapter.pages.indices.chunked(2)
                } else {
                    chapter.pages.indices.map { listOf(it) }
                }
            }
            val retainedGroupIndex = spreadGroups
                .indexOfFirst { retainedPage in it }
                .takeIf { it >= 0 }
                ?: 0
            val initialPagerPage = if (mode.rightToLeft) {
                spreadGroups.lastIndex - retainedGroupIndex
            } else {
                retainedGroupIndex
            }.coerceIn(spreadGroups.indices)
            val pagerState = rememberPagerState(
                initialPage = initialPagerPage,
                pageCount = { spreadGroups.size },
            )
            val actualGroupIndex = if (mode.rightToLeft) {
                spreadGroups.lastIndex - pagerState.currentPage
            } else {
                pagerState.currentPage
            }.coerceIn(spreadGroups.indices)
            val actualPage = spreadGroups.getOrNull(actualGroupIndex)?.firstOrNull() ?: 0
            LaunchedEffect(chapter.request, pagerState, mode, spreadGroups) {
                snapshotFlow { pagerState.currentPage }
                    .distinctUntilChanged()
                    .collect { pagerPage ->
                        val groupIndex = if (mode.rightToLeft) {
                            spreadGroups.lastIndex - pagerPage
                        } else {
                            pagerPage
                        }.coerceIn(spreadGroups.indices)
                        val pageIndex = spreadGroups.getOrNull(groupIndex)?.firstOrNull() ?: 0
                        retainedPage = pageIndex
                        onSaveReaderProgress(
                            chapter.request,
                            pageIndex,
                            pageIndex == chapter.pages.lastIndex,
                        )
                    }
            }
            LaunchedEffect(chapter.request, actualGroupIndex, spreadGroups) {
                val preloadGroups = (preloadWindow / if (dualPage) 2 else 1).coerceAtLeast(1)
                ((actualGroupIndex - preloadGroups)..(actualGroupIndex + preloadGroups))
                    .filter { it in spreadGroups.indices }
                    .flatMap { spreadGroups[it] }
                    .distinct()
                    .preloadReaderPages(
                        maxConcurrency = readerPreferences.readerThreads,
                        preloadReaderPage = preloadReaderPage,
                    )
            }
            val previousPagerTarget = if (mode.rightToLeft) {
                pagerState.currentPage + 1
            } else {
                pagerState.currentPage - 1
            }
            val nextPagerTarget = if (mode.rightToLeft) {
                pagerState.currentPage - 1
            } else {
                pagerState.currentPage + 1
            }
            val canPreviousPage = previousPagerTarget in spreadGroups.indices || previousChapter != null
            val canNextPage = nextPagerTarget in spreadGroups.indices || nextChapter != null
            val previousPageContentDescription = when {
                previousPagerTarget in spreadGroups.indices -> "Previous page"
                previousChapter != null -> previousChapter.readerChapterActionDescription("Previous")
                else -> "No previous page or chapter"
            }
            val nextPageContentDescription = when {
                nextPagerTarget in spreadGroups.indices -> "Next page"
                nextChapter != null -> nextChapter.readerChapterActionDescription("Next")
                else -> "No next page or chapter"
            }
            ReaderScaffold(
                request = chapter.request,
                mode = mode,
                scale = scale,
                canvas = canvas,
                currentPage = actualPage + 1,
                pageCount = chapter.pages.size,
                canPreviousPage = canPreviousPage,
                canNextPage = canNextPage,
                previousPageContentDescription = previousPageContentDescription,
                nextPageContentDescription = nextPageContentDescription,
                bookmarked = bookmarked,
                bookmarkBusy = bookmarkBusy,
                readBusy = readBusy,
                downloadBusy = downloadBusy,
                controlsVisible = controlsVisible,
                settingsVisible = settingsVisible,
                chaptersVisible = chaptersVisible,
                statsVisible = statsVisible,
                inputLocked = inputLocked,
                elapsedSeconds = readerStartedAt.elapsedNow().inWholeSeconds.coerceAtLeast(1),
                showPageStrip = showPageStrip,
                showControlsOnStart = showControlsOnStart,
                readerSettings = readerPreferences.copy(
                    mode = mode.toSettingsReaderMode(),
                    scale = scale.toSettingsReaderScale(),
                    canvas = canvas.toSettingsReaderCanvas(),
                    showPageStrip = showPageStrip,
                    keepControlsVisible = showControlsOnStart,
                ),
                onReaderSettingsChange = saveReaderPreferences,
                previousChapter = previousChapter,
                nextChapter = nextChapter,
                onModeChange = {
                    retainedPage = actualPage
                    mode = it
                    saveReaderPreferences(
                        readerPreferences.copy(
                            mode = it.toSettingsReaderMode(),
                            scale = scale.toSettingsReaderScale(),
                            canvas = canvas.toSettingsReaderCanvas(),
                            showPageStrip = showPageStrip,
                            keepControlsVisible = showControlsOnStart,
                        ),
                    )
                },
                onScaleChange = updateScalePreference,
                onCanvasChange = {
                    canvas = it
                    saveReaderPreferences(
                        readerPreferences.copy(
                            mode = mode.toSettingsReaderMode(),
                            scale = scale.toSettingsReaderScale(),
                            canvas = it.toSettingsReaderCanvas(),
                            showPageStrip = showPageStrip,
                            keepControlsVisible = showControlsOnStart,
                        ),
                    )
                },
                onShowPageStripChange = {
                    showPageStrip = it
                    saveReaderPreferences(
                        readerPreferences.copy(
                            mode = mode.toSettingsReaderMode(),
                            scale = scale.toSettingsReaderScale(),
                            canvas = canvas.toSettingsReaderCanvas(),
                            showPageStrip = it,
                            keepControlsVisible = showControlsOnStart,
                        ),
                    )
                },
                onShowControlsOnStartChange = {
                    showControlsOnStart = it
                    saveReaderPreferences(
                        readerPreferences.copy(
                            mode = mode.toSettingsReaderMode(),
                            scale = scale.toSettingsReaderScale(),
                            canvas = canvas.toSettingsReaderCanvas(),
                            showPageStrip = showPageStrip,
                            keepControlsVisible = it,
                        ),
                    )
                },
                onToggleControls = toggleControls,
                onDismissPanels = {
                    settingsVisible = false
                    chaptersVisible = false
                    statsVisible = false
                },
                onToggleSettings = {
                    controlsVisible = true
                    settingsVisible = !settingsVisible
                    if (settingsVisible) chaptersVisible = false
                    if (settingsVisible) statsVisible = false
                },
                onToggleChapters = {
                    controlsVisible = true
                    chaptersVisible = !chaptersVisible
                    if (chaptersVisible) settingsVisible = false
                    if (chaptersVisible) statsVisible = false
                },
                onToggleStats = {
                    controlsVisible = true
                    statsVisible = !statsVisible
                    if (statsVisible) {
                        settingsVisible = false
                        chaptersVisible = false
                    }
                },
                onToggleCrop = {
                    val updated = readerPreferences.copy(cropBorders = !readerPreferences.cropBorders)
                    readerPreferences = updated
                    saveReaderPreferences(updated)
                },
                onToggleOcrLookup = toggleReaderOcrLookup,
                onMarkChapterRead = markChapterRead,
                onDownloadChapter = downloadChapter,
                onOpenChapterUrl = openChapterUrl,
                onShareChapter = shareChapterUrl,
                onBookmarkChapterRef = bookmarkChapterRef,
                onDownloadChapterRef = downloadChapterRef,
                onMarkChapterRefRead = markChapterRefRead,
                onToggleBookmark = chapter.request.chapterId?.let { chapterId ->
                    {
                        if (!bookmarkBusy) {
                            scope.launch {
                                bookmarkBusy = true
                                val newValue = !bookmarked
                                runCatching { onSetChapterBookmark(chapterId, newValue) }
                                    .onSuccess { bookmarked = newValue }
                                bookmarkBusy = false
                            }
                        }
                    }
                },
                onOpenChapter = openAdjacentChapter,
                onPreviousChapter = previousChapter?.let { { openAdjacentChapter(it) } },
                onNextChapter = nextChapter?.let { { openAdjacentChapter(it) } },
                onPreviousPage = {
                    val target = if (mode.rightToLeft) {
                        pagerState.currentPage + 1
                    } else {
                        pagerState.currentPage - 1
                    }
                    if (target in spreadGroups.indices) {
                        scope.launch {
                            if (readerPreferences.pageTransitions) {
                                pagerState.animateScrollToPage(target)
                            } else {
                                pagerState.scrollToPage(target)
                            }
                        }
                    } else {
                        previousChapter?.let(openAdjacentChapter)
                    }
                },
                onNextPage = {
                    val target = if (mode.rightToLeft) {
                        pagerState.currentPage - 1
                    } else {
                        pagerState.currentPage + 1
                    }
                    if (target in spreadGroups.indices) {
                        scope.launch {
                            if (readerPreferences.pageTransitions) {
                                pagerState.animateScrollToPage(target)
                            } else {
                                pagerState.scrollToPage(target)
                            }
                        }
                    } else {
                        nextChapter?.let(openAdjacentChapter)
                    }
                },
                onPageSelected = { pageIndex ->
                    val groupIndex = spreadGroups
                        .indexOfFirst { pageIndex in it }
                        .takeIf { it >= 0 }
                        ?: 0
                    val target = if (mode.rightToLeft) {
                        spreadGroups.lastIndex - groupIndex
                    } else {
                        groupIndex
                    }
                    scope.launch {
                        if (readerPreferences.pageTransitions) {
                            pagerState.animateScrollToPage(target)
                        } else {
                            pagerState.scrollToPage(target)
                        }
                    }
                },
                onBack = onCloseReader,
                desktopCommandRequest = desktopCommandRequest,
                onDesktopCommandHandled = onDesktopCommandHandled,
            ) {
                HorizontalPager(
                    state = pagerState,
                    userScrollEnabled = readerPreferences.swipeNavigationEnabled,
                    modifier = Modifier
                        .fillMaxSize()
                        .background(canvas.readerBackground(readerPreferences.pureBlackBackground)),
                    key = { pagerPage ->
                        val groupIndex = if (mode.rightToLeft) {
                            spreadGroups.lastIndex - pagerPage
                        } else {
                            pagerPage
                        }.coerceIn(spreadGroups.indices)
                        spreadGroups[groupIndex].joinToString("|") { pageIndex ->
                            val page = chapter.pages[pageIndex]
                            "${page.index}:${page.url}"
                        }
                    },
                ) { pagerPage ->
                    val groupIndex = if (mode.rightToLeft) {
                        spreadGroups.lastIndex - pagerPage
                    } else {
                        pagerPage
                    }.coerceIn(spreadGroups.indices)
                    val spread = spreadGroups[groupIndex]
                    if (spread.size == 1) {
                        val pageIndex = spread.first()
                        ReaderPageImage(
                            request = chapter.request,
                            page = chapter.pages[pageIndex],
                            paged = true,
                            scale = scale,
                            canvas = canvas,
                            readerSettings = readerPreferences,
                            dictionarySettings = dictionarySettings,
                            showPageActionControls = controlsVisible && readerPreferences.desktopReaderMenu,
                            ocrToggleSignal = ocrLookupToggleSignal,
                            cachedState = pageStates[pageIndex],
                            onStateChange = { pageStates[pageIndex] = it },
                            onScaleChange = updateScalePreference,
                            onOpenExternalUrl = onOpenExternalUrl,
                            onLoadReaderOcrBlocks = onLoadReaderOcrBlocks,
                            onLoadReaderPageImage = onLoadReaderPageImage,
                        )
                    } else {
                        Row(
                            modifier = Modifier.fillMaxSize(),
                            horizontalArrangement = Arrangement.spacedBy(
                                readerPreferences.centerMarginDp.coerceIn(0, 64).dp,
                                Alignment.CenterHorizontally,
                            ),
                            verticalAlignment = Alignment.CenterVertically,
                        ) {
                            val visibleSpread = if (mode.rightToLeft xor readerPreferences.invertDoublePages) {
                                spread.reversed()
                            } else {
                                spread
                            }
                            visibleSpread.forEach { pageIndex ->
                                Box(
                                    modifier = Modifier
                                        .weight(1f)
                                        .fillMaxHeight(),
                                    contentAlignment = Alignment.Center,
                                ) {
                                    ReaderPageImage(
                                        request = chapter.request,
                                        page = chapter.pages[pageIndex],
                                        paged = true,
                                        scale = scale,
                                        canvas = canvas,
                                        readerSettings = readerPreferences,
                                        dictionarySettings = dictionarySettings,
                                        showPageActionControls = controlsVisible && readerPreferences.desktopReaderMenu,
                                        ocrToggleSignal = ocrLookupToggleSignal,
                                        cachedState = pageStates[pageIndex],
                                        onStateChange = { pageStates[pageIndex] = it },
                                        onScaleChange = updateScalePreference,
                                        onOpenExternalUrl = onOpenExternalUrl,
                                        onLoadReaderOcrBlocks = onLoadReaderOcrBlocks,
                                        onLoadReaderPageImage = onLoadReaderPageImage,
                                    )
                                }
                            }
                        }
                    }
                }
            }
        } else {
            val listState = rememberLazyListState(initialFirstVisibleItemIndex = retainedPage)
            val visibleListPage = listState.firstVisibleItemIndex
            val canPreviousPage = visibleListPage > 0 || previousChapter != null
            val canNextPage = visibleListPage < chapter.pages.lastIndex || nextChapter != null
            val previousPageContentDescription = when {
                visibleListPage > 0 -> "Previous page"
                previousChapter != null -> previousChapter.readerChapterActionDescription("Previous")
                else -> "No previous page or chapter"
            }
            val nextPageContentDescription = when {
                visibleListPage < chapter.pages.lastIndex -> "Next page"
                nextChapter != null -> nextChapter.readerChapterActionDescription("Next")
                else -> "No next page or chapter"
            }
            LaunchedEffect(chapter.request, listState, mode) {
                snapshotFlow { listState.firstVisibleItemIndex }
                    .distinctUntilChanged()
                    .collect { pageIndex ->
                        retainedPage = pageIndex
                        onSaveReaderProgress(
                            chapter.request,
                            pageIndex,
                            pageIndex == chapter.pages.lastIndex,
                        )
                    }
            }
            LaunchedEffect(chapter.request, visibleListPage) {
                val preloadBehind = if (readerPreferences.aggressivePageLoading) preloadWindow / 2 else 0
                val first = (visibleListPage - preloadBehind).coerceAtLeast(0)
                val last = (visibleListPage + preloadWindow).coerceAtMost(chapter.pages.lastIndex)
                (first..last)
                    .preloadReaderPages(
                        maxConcurrency = readerPreferences.readerThreads,
                        preloadReaderPage = preloadReaderPage,
                    )
            }
            ReaderScaffold(
                request = chapter.request,
                mode = mode,
                scale = scale,
                canvas = canvas,
                currentPage = visibleListPage + 1,
                pageCount = chapter.pages.size,
                canPreviousPage = canPreviousPage,
                canNextPage = canNextPage,
                previousPageContentDescription = previousPageContentDescription,
                nextPageContentDescription = nextPageContentDescription,
                bookmarked = bookmarked,
                bookmarkBusy = bookmarkBusy,
                readBusy = readBusy,
                downloadBusy = downloadBusy,
                controlsVisible = controlsVisible,
                settingsVisible = settingsVisible,
                chaptersVisible = chaptersVisible,
                statsVisible = statsVisible,
                inputLocked = inputLocked,
                elapsedSeconds = readerStartedAt.elapsedNow().inWholeSeconds.coerceAtLeast(1),
                showPageStrip = showPageStrip,
                showControlsOnStart = showControlsOnStart,
                readerSettings = readerPreferences.copy(
                    mode = mode.toSettingsReaderMode(),
                    scale = scale.toSettingsReaderScale(),
                    canvas = canvas.toSettingsReaderCanvas(),
                    showPageStrip = showPageStrip,
                    keepControlsVisible = showControlsOnStart,
                ),
                onReaderSettingsChange = saveReaderPreferences,
                previousChapter = previousChapter,
                nextChapter = nextChapter,
                onModeChange = {
                    retainedPage = listState.firstVisibleItemIndex
                    mode = it
                    saveReaderPreferences(
                        readerPreferences.copy(
                            mode = it.toSettingsReaderMode(),
                            scale = scale.toSettingsReaderScale(),
                            canvas = canvas.toSettingsReaderCanvas(),
                            showPageStrip = showPageStrip,
                            keepControlsVisible = showControlsOnStart,
                        ),
                    )
                },
                onScaleChange = updateScalePreference,
                onCanvasChange = {
                    canvas = it
                    saveReaderPreferences(
                        readerPreferences.copy(
                            mode = mode.toSettingsReaderMode(),
                            scale = scale.toSettingsReaderScale(),
                            canvas = it.toSettingsReaderCanvas(),
                            showPageStrip = showPageStrip,
                            keepControlsVisible = showControlsOnStart,
                        ),
                    )
                },
                onShowPageStripChange = {
                    showPageStrip = it
                    saveReaderPreferences(
                        readerPreferences.copy(
                            mode = mode.toSettingsReaderMode(),
                            scale = scale.toSettingsReaderScale(),
                            canvas = canvas.toSettingsReaderCanvas(),
                            showPageStrip = it,
                            keepControlsVisible = showControlsOnStart,
                        ),
                    )
                },
                onShowControlsOnStartChange = {
                    showControlsOnStart = it
                    saveReaderPreferences(
                        readerPreferences.copy(
                            mode = mode.toSettingsReaderMode(),
                            scale = scale.toSettingsReaderScale(),
                            canvas = canvas.toSettingsReaderCanvas(),
                            showPageStrip = showPageStrip,
                            keepControlsVisible = it,
                        ),
                    )
                },
                onToggleControls = toggleControls,
                onDismissPanels = {
                    settingsVisible = false
                    chaptersVisible = false
                    statsVisible = false
                },
                onToggleSettings = {
                    controlsVisible = true
                    settingsVisible = !settingsVisible
                    if (settingsVisible) chaptersVisible = false
                    if (settingsVisible) statsVisible = false
                },
                onToggleChapters = {
                    controlsVisible = true
                    chaptersVisible = !chaptersVisible
                    if (chaptersVisible) settingsVisible = false
                    if (chaptersVisible) statsVisible = false
                },
                onToggleStats = {
                    controlsVisible = true
                    statsVisible = !statsVisible
                    if (statsVisible) {
                        settingsVisible = false
                        chaptersVisible = false
                    }
                },
                onToggleCrop = {
                    val updated = readerPreferences.copy(cropBorders = !readerPreferences.cropBorders)
                    readerPreferences = updated
                    saveReaderPreferences(updated)
                },
                onToggleOcrLookup = toggleReaderOcrLookup,
                onMarkChapterRead = markChapterRead,
                onDownloadChapter = downloadChapter,
                onOpenChapterUrl = openChapterUrl,
                onShareChapter = shareChapterUrl,
                onBookmarkChapterRef = bookmarkChapterRef,
                onDownloadChapterRef = downloadChapterRef,
                onMarkChapterRefRead = markChapterRefRead,
                onToggleBookmark = chapter.request.chapterId?.let { chapterId ->
                    {
                        if (!bookmarkBusy) {
                            scope.launch {
                                bookmarkBusy = true
                                val newValue = !bookmarked
                                runCatching { onSetChapterBookmark(chapterId, newValue) }
                                    .onSuccess { bookmarked = newValue }
                                bookmarkBusy = false
                            }
                        }
                    }
                },
                onOpenChapter = openAdjacentChapter,
                onPreviousChapter = previousChapter?.let { { openAdjacentChapter(it) } },
                onNextChapter = nextChapter?.let { { openAdjacentChapter(it) } },
                onPreviousPage = {
                    if (listState.firstVisibleItemIndex > 0) {
                        scope.launch {
                            val target = listState.firstVisibleItemIndex - 1
                            if (readerPreferences.pageTransitions) {
                                listState.animateScrollToItem(target)
                            } else {
                                listState.scrollToItem(target)
                            }
                        }
                    } else {
                        previousChapter?.let(openAdjacentChapter)
                    }
                },
                onNextPage = {
                    if (listState.firstVisibleItemIndex < chapter.pages.lastIndex) {
                        scope.launch {
                            val target = listState.firstVisibleItemIndex + 1
                            if (readerPreferences.pageTransitions) {
                                listState.animateScrollToItem(target)
                            } else {
                                listState.scrollToItem(target)
                            }
                        }
                    } else {
                        nextChapter?.let(openAdjacentChapter)
                    }
                },
                onPageSelected = { pageIndex ->
                    scope.launch {
                        if (readerPreferences.pageTransitions) {
                            listState.animateScrollToItem(pageIndex)
                        } else {
                            listState.scrollToItem(pageIndex)
                        }
                    }
                },
                onBack = onCloseReader,
                desktopCommandRequest = desktopCommandRequest,
                onDesktopCommandHandled = onDesktopCommandHandled,
            ) {
                LazyColumn(
                    state = listState,
                    modifier = Modifier
                        .fillMaxSize()
                        .background(canvas.readerBackground(readerPreferences.pureBlackBackground)),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = if (mode == ReaderMode.Vertical && !readerPreferences.continuousMode) {
                        Arrangement.spacedBy(12.dp)
                    } else {
                        Arrangement.Top
                    },
                    contentPadding = if (mode == ReaderMode.Vertical && !readerPreferences.continuousMode) {
                        PaddingValues(vertical = 12.dp)
                    } else {
                        PaddingValues()
                    },
                ) {
                    items(chapter.pages, key = { "${it.index}:${it.url}" }) { page ->
                        ReaderPageImage(
                            request = chapter.request,
                            page = page,
                            paged = false,
                            scale = scale,
                            canvas = canvas,
                            readerSettings = readerPreferences,
                            dictionarySettings = dictionarySettings,
                            showPageActionControls = controlsVisible &&
                                readerPreferences.desktopReaderMenu &&
                                page.index == visibleListPage,
                            ocrToggleSignal = if (page.index == visibleListPage) ocrLookupToggleSignal else 0,
                            cachedState = pageStates[page.index],
                            onStateChange = { pageStates[page.index] = it },
                            onScaleChange = updateScalePreference,
                            onOpenExternalUrl = onOpenExternalUrl,
                            onLoadReaderOcrBlocks = onLoadReaderOcrBlocks,
                            onLoadReaderPageImage = onLoadReaderPageImage,
                        )
                    }
                }
            }
        }
    }
}

@OptIn(ExperimentalComposeUiApi::class)
@Composable
private fun ReaderScaffold(
    request: ChimahonReaderRequest,
    mode: ReaderMode,
    scale: ReaderScale,
    canvas: ReaderCanvas,
    currentPage: Int,
    pageCount: Int,
    canPreviousPage: Boolean,
    canNextPage: Boolean,
    previousPageContentDescription: String,
    nextPageContentDescription: String,
    bookmarked: Boolean,
    bookmarkBusy: Boolean,
    readBusy: Boolean,
    downloadBusy: Boolean,
    controlsVisible: Boolean,
    settingsVisible: Boolean,
    chaptersVisible: Boolean,
    statsVisible: Boolean,
    inputLocked: Boolean,
    elapsedSeconds: Long,
    showPageStrip: Boolean,
    showControlsOnStart: Boolean,
    readerSettings: ChimahonReaderSettings,
    onReaderSettingsChange: (ChimahonReaderSettings) -> Unit,
    previousChapter: ChimahonReaderChapterRef?,
    nextChapter: ChimahonReaderChapterRef?,
    onModeChange: (ReaderMode) -> Unit,
    onScaleChange: (ReaderScale) -> Unit,
    onCanvasChange: (ReaderCanvas) -> Unit,
    onShowPageStripChange: (Boolean) -> Unit,
    onShowControlsOnStartChange: (Boolean) -> Unit,
    onToggleControls: () -> Unit,
    onDismissPanels: () -> Unit,
    onToggleSettings: () -> Unit,
    onToggleChapters: () -> Unit,
    onToggleStats: () -> Unit,
    onToggleCrop: () -> Unit,
    onToggleOcrLookup: () -> Unit,
    onMarkChapterRead: (() -> Unit)?,
    onDownloadChapter: (() -> Unit)?,
    onOpenChapterUrl: (() -> Unit)?,
    onShareChapter: (() -> Unit)?,
    onBookmarkChapterRef: (ChimahonReaderChapterRef) -> Unit,
    onDownloadChapterRef: (ChimahonReaderChapterRef) -> Unit,
    onMarkChapterRefRead: (ChimahonReaderChapterRef) -> Unit,
    onToggleBookmark: (() -> Unit)?,
    onOpenChapter: (ChimahonReaderChapterRef) -> Unit,
    onPreviousChapter: (() -> Unit)?,
    onNextChapter: (() -> Unit)?,
    onPreviousPage: () -> Unit,
    onNextPage: () -> Unit,
    onPageSelected: (Int) -> Unit,
    onBack: () -> Unit,
    desktopCommandRequest: ChimahonDesktopCommandRequest? = null,
    onDesktopCommandHandled: (Long) -> Unit = {},
    content: @Composable () -> Unit,
) {
    val focusRequester = remember { FocusRequester() }
    val effectiveNavigationMode = when (readerSettings.navigationMode) {
        ChimahonReaderNavigationMode.Automatic -> when {
            mode.rightToLeft -> ChimahonReaderNavigationMode.RightToLeft
            mode == ReaderMode.Webtoon || mode == ReaderMode.Vertical -> ChimahonReaderNavigationMode.Vertical
            else -> ChimahonReaderNavigationMode.LeftToRight
        }
        else -> readerSettings.navigationMode
    }
    val tapNavigationEnabled = readerSettings.tapZonesEnabled &&
        readerSettings.desktopTapNavigation &&
        readerSettings.tapNavigationLayout != ChimahonReaderTapNavigationLayout.Disabled
    val wheelNavigationEnabled = readerSettings.swipeNavigationEnabled &&
        readerSettings.mouseWheelAction != ChimahonReaderMouseWheelAction.Disabled
    val keyboardScheme = readerSettings.keyboardScheme
    val keyboardShortcutsEnabled = readerSettings.keyboardShortcutsEnabled &&
        keyboardScheme != ChimahonReaderKeyboardScheme.Disabled
    val wheelThreshold = (48f * 100f / readerSettings.mouseWheelSensitivityPercent.coerceIn(25, 400))
        .coerceIn(12f, 160f)
    var wheelAccumulator by remember(request, mode) { mutableStateOf(0f) }
    var flashVisible by remember(request) { mutableStateOf(false) }
    var flashPulse by remember(request) { mutableIntStateOf(0) }
    var lastFlashPage by remember(request) { mutableIntStateOf(currentPage) }
    val cycleOrientation = {
        onReaderSettingsChange(
            readerSettings.copy(orientation = readerSettings.orientation.nextReaderOrientation()),
        )
    }
    val cyclePageLayout = {
        if (mode.paged) {
            onReaderSettingsChange(
                readerSettings.copy(dualPageMode = readerSettings.dualPageMode.nextDualPageMode()),
            )
        }
    }
    val shiftDoublePages = {
        if (mode.paged && readerSettings.dualPageMode != ChimahonDualPageMode.Off) {
            onReaderSettingsChange(
                readerSettings.copy(invertDoublePages = !readerSettings.invertDoublePages),
            )
        }
    }
    val zoomByWheel: (Boolean) -> Unit = { zoomIn ->
        val nextScale = when {
            zoomIn && scale == ReaderScale.FitScreen -> ReaderScale.FitWidth
            zoomIn && scale == ReaderScale.FitWidth -> ReaderScale.FitHeight
            zoomIn -> ReaderScale.FitHeight
            scale == ReaderScale.FitHeight -> ReaderScale.FitWidth
            scale == ReaderScale.FitWidth -> ReaderScale.FitScreen
            else -> ReaderScale.FitScreen
        }
        if (nextScale != scale) {
            onScaleChange(nextScale)
        }
    }

    LaunchedEffect(request) {
        focusRequester.requestFocus()
    }
    LaunchedEffect(desktopCommandRequest?.id) {
        val commandRequest = desktopCommandRequest ?: return@LaunchedEffect
        if (!commandRequest.command.readerScoped) return@LaunchedEffect
        when (commandRequest.command) {
            ChimahonDesktopCommand.ReaderPreviousPage -> if (canPreviousPage) onPreviousPage()
            ChimahonDesktopCommand.ReaderNextPage -> if (canNextPage) onNextPage()
            ChimahonDesktopCommand.ReaderFirstPage -> if (pageCount > 0 && currentPage > 1) onPageSelected(0)
            ChimahonDesktopCommand.ReaderLastPage -> if (pageCount > 0 && currentPage < pageCount) {
                onPageSelected(pageCount - 1)
            }
            ChimahonDesktopCommand.ReaderPreviousChapter -> onPreviousChapter?.invoke()
            ChimahonDesktopCommand.ReaderNextChapter -> onNextChapter?.invoke()
            ChimahonDesktopCommand.ReaderToggleControls -> onToggleControls()
            ChimahonDesktopCommand.ReaderCycleMode -> {
                val nextIndex = (ReaderMode.entries.indexOf(mode) + 1) % ReaderMode.entries.size
                onModeChange(ReaderMode.entries[nextIndex])
            }
            ChimahonDesktopCommand.ReaderOpenSettings -> onToggleSettings()
            ChimahonDesktopCommand.ReaderFitScreen -> onScaleChange(ReaderScale.FitScreen)
            ChimahonDesktopCommand.ReaderFitWidth -> onScaleChange(ReaderScale.FitWidth)
            ChimahonDesktopCommand.ReaderFitHeight -> onScaleChange(ReaderScale.FitHeight)
            ChimahonDesktopCommand.ReaderZoomIn -> zoomByWheel(true)
            ChimahonDesktopCommand.ReaderZoomOut -> zoomByWheel(false)
            ChimahonDesktopCommand.ReaderResetZoom -> {
                onScaleChange(if (mode.paged) ReaderScale.FitScreen else ReaderScale.FitWidth)
            }
            ChimahonDesktopCommand.ReaderToggleFitWidthOrScreen -> {
                onScaleChange(if (scale == ReaderScale.FitWidth) ReaderScale.FitScreen else ReaderScale.FitWidth)
            }
            ChimahonDesktopCommand.ReaderOpenChapters -> onToggleChapters()
            ChimahonDesktopCommand.ReaderToggleStats -> onToggleStats()
            ChimahonDesktopCommand.ReaderToggleCrop -> onToggleCrop()
            ChimahonDesktopCommand.ReaderToggleOcrLookup -> onToggleOcrLookup()
            ChimahonDesktopCommand.ReaderCycleOrientation -> cycleOrientation()
            ChimahonDesktopCommand.ReaderCyclePageLayout -> cyclePageLayout()
            ChimahonDesktopCommand.ReaderShiftDoublePages -> shiftDoublePages()
            ChimahonDesktopCommand.ReaderBookmarkChapter -> onToggleBookmark?.invoke()
            ChimahonDesktopCommand.ReaderDownloadChapter -> onDownloadChapter?.invoke()
            ChimahonDesktopCommand.ReaderMarkChapterRead -> onMarkChapterRead?.invoke()
            ChimahonDesktopCommand.ReaderOpenChapterUrl -> onOpenChapterUrl?.invoke()
            ChimahonDesktopCommand.ReaderShareChapter -> onShareChapter?.invoke()
            else -> Unit
        }
        onDesktopCommandHandled(commandRequest.id)
    }
    LaunchedEffect(
        currentPage,
        pageCount,
        readerSettings.flashOnPageChange,
        readerSettings.flashDurationMillis,
        readerSettings.flashPageInterval,
    ) {
        val durationMillis = readerSettings.flashDurationMillis.coerceIn(100, 1_500)
        val interval = readerSettings.flashPageInterval.coerceIn(1, 10)
        if (!readerSettings.flashOnPageChange || pageCount <= 0) {
            flashVisible = false
            lastFlashPage = currentPage
            return@LaunchedEffect
        }
        if (currentPage != lastFlashPage && abs(currentPage - lastFlashPage) >= interval) {
            lastFlashPage = currentPage
            flashPulse += 1
            flashVisible = true
            delay(durationMillis.toLong())
            flashVisible = false
        } else {
            flashVisible = false
        }
    }
    LaunchedEffect(controlsVisible, settingsVisible, chaptersVisible, statsVisible, readerSettings.keepControlsVisible) {
        if (
            controlsVisible &&
            !readerSettings.keepControlsVisible &&
            !settingsVisible &&
            !chaptersVisible &&
            !statsVisible
        ) {
            delay(3_500)
            onToggleControls()
        }
    }

    BoxWithConstraints(
        modifier = Modifier
            .fillMaxSize()
            .background(canvas.readerBackground(readerSettings.pureBlackBackground))
            .focusRequester(focusRequester)
            .focusable()
            .onPreviewKeyEvent { event ->
                if (event.type != KeyEventType.KeyDown) return@onPreviewKeyEvent false
                if (!keyboardShortcutsEnabled && event.key != Key.Escape) return@onPreviewKeyEvent false
                if (inputLocked && event.key != Key.Escape) return@onPreviewKeyEvent true
                val chapterShortcut = event.isShiftPressed || event.isCtrlPressed || event.isMetaPressed
                when (event.key) {
                    Key.H -> {
                        if (keyboardScheme == ChimahonReaderKeyboardScheme.Vim) {
                            when {
                                chapterShortcut && onPreviousChapter != null -> {
                                    onPreviousChapter()
                                    true
                                }
                                canPreviousPage -> {
                                    onPreviousPage()
                                    true
                                }
                                else -> false
                            }
                        } else {
                            false
                        }
                    }
                    Key.J -> {
                        if (keyboardScheme == ChimahonReaderKeyboardScheme.Vim) {
                            if (canNextPage) {
                                onNextPage()
                                true
                            } else {
                                false
                            }
                        } else {
                            false
                        }
                    }
                    Key.K -> {
                        if (keyboardScheme == ChimahonReaderKeyboardScheme.Vim) {
                            if (canPreviousPage) {
                                onPreviousPage()
                                true
                            } else {
                                false
                            }
                        } else {
                            false
                        }
                    }
                    Key.N -> {
                        if (keyboardScheme == ChimahonReaderKeyboardScheme.Vim && onNextChapter != null) {
                            onNextChapter()
                            true
                        } else {
                            false
                        }
                    }
                    Key.VolumeUp -> {
                        if (!readerSettings.volumeKeysEnabled) {
                            false
                        } else {
                            if (readerSettings.volumeKeysInverted) onNextPage() else onPreviousPage()
                            true
                        }
                    }
                    Key.VolumeDown -> {
                        if (!readerSettings.volumeKeysEnabled) {
                            false
                        } else {
                            if (readerSettings.volumeKeysInverted) onPreviousPage() else onNextPage()
                            true
                        }
                    }
                    Key.DirectionLeft,
                    Key.PageUp,
                    Key.DirectionUp,
                    -> {
                        when {
                            chapterShortcut && onPreviousChapter != null -> {
                                onPreviousChapter()
                                true
                            }
                            chapterShortcut -> false
                            canPreviousPage -> {
                                onPreviousPage()
                                true
                            }
                            else -> false
                        }
                    }
                    Key.DirectionRight,
                    Key.PageDown,
                    Key.DirectionDown,
                    -> {
                        when {
                            chapterShortcut && onNextChapter != null -> {
                                onNextChapter()
                                true
                            }
                            chapterShortcut -> false
                            canNextPage -> {
                                onNextPage()
                                true
                            }
                            else -> false
                        }
                    }
                    Key.Spacebar -> {
                        if (event.isShiftPressed) {
                            if (canPreviousPage) {
                                onPreviousPage()
                                true
                            } else {
                                false
                            }
                        } else if (canNextPage) {
                            onNextPage()
                            true
                        } else {
                            false
                        }
                    }
                    Key.Enter -> {
                        onToggleControls()
                        true
                    }
                    Key.M -> {
                        if (settingsVisible || chaptersVisible || statsVisible) {
                            false
                        } else {
                            val nextIndex = (ReaderMode.entries.indexOf(mode) + 1) % ReaderMode.entries.size
                            onModeChange(ReaderMode.entries[nextIndex])
                            true
                        }
                    }
                    Key.S -> {
                        if ((event.isCtrlPressed || event.isMetaPressed) && onShareChapter != null) {
                            onShareChapter()
                            true
                        } else if (chaptersVisible) {
                            false
                        } else {
                            onToggleSettings()
                            true
                        }
                    }
                    Key.C -> {
                        if (settingsVisible || chaptersVisible) {
                            false
                        } else {
                            onToggleChapters()
                            true
                        }
                    }
                    Key.I -> {
                        if (settingsVisible || chaptersVisible) {
                            false
                        } else {
                            onToggleStats()
                            true
                        }
                    }
                    Key.F -> {
                        if (settingsVisible || chaptersVisible || statsVisible) {
                            false
                        } else {
                            onToggleCrop()
                            true
                        }
                    }
                    Key.T -> {
                        if (settingsVisible || chaptersVisible || statsVisible) {
                            false
                        } else {
                            cycleOrientation()
                            true
                        }
                    }
                    Key.G -> {
                        if (settingsVisible || chaptersVisible || statsVisible) {
                            false
                        } else {
                            onToggleOcrLookup()
                            true
                        }
                    }
                    Key.L -> {
                        if (keyboardScheme == ChimahonReaderKeyboardScheme.Vim) {
                            when {
                                chapterShortcut && onNextChapter != null -> {
                                    onNextChapter()
                                    true
                                }
                                canNextPage -> {
                                    onNextPage()
                                    true
                                }
                                else -> false
                            }
                        } else if (settingsVisible || chaptersVisible || statsVisible || !mode.paged) {
                            false
                        } else {
                            cyclePageLayout()
                            true
                        }
                    }
                    Key.P -> {
                        if (
                            settingsVisible ||
                            chaptersVisible ||
                            statsVisible ||
                            !mode.paged ||
                            readerSettings.dualPageMode == ChimahonDualPageMode.Off
                        ) {
                            false
                        } else {
                            shiftDoublePages()
                            true
                        }
                    }
                    Key.B -> {
                        if (settingsVisible || chaptersVisible || statsVisible || onToggleBookmark == null) {
                            false
                        } else {
                            onToggleBookmark()
                            true
                        }
                    }
                    Key.D -> {
                        if (settingsVisible || chaptersVisible || statsVisible || onDownloadChapter == null) {
                            false
                        } else {
                            onDownloadChapter()
                            true
                        }
                    }
                    Key.R -> {
                        if (settingsVisible || chaptersVisible || statsVisible || onMarkChapterRead == null) {
                            false
                        } else {
                            onMarkChapterRead()
                            true
                        }
                    }
                    Key.O -> {
                        if (settingsVisible || chaptersVisible || statsVisible || onOpenChapterUrl == null) {
                            false
                        } else {
                            onOpenChapterUrl()
                            true
                        }
                    }
                    Key.MoveHome -> {
                        if (pageCount > 0) {
                            onPageSelected(0)
                            true
                        } else {
                            false
                        }
                    }
                    Key.MoveEnd -> {
                        if (pageCount > 0) {
                            onPageSelected(pageCount - 1)
                            true
                        } else {
                            false
                        }
                    }
                    Key.Escape -> {
                        when {
                            settingsVisible || chaptersVisible || statsVisible -> onDismissPanels()
                            controlsVisible -> onToggleControls()
                            else -> onBack()
                        }
                        true
                    }
                    else -> false
                }
            }
            .onPointerEvent(PointerEventType.Scroll) { event ->
                if (
                    mode.paged &&
                    !inputLocked &&
                    wheelNavigationEnabled &&
                    !(
                        readerSettings.mouseWheelAction != ChimahonReaderMouseWheelAction.Zoom &&
                            readerSettings.navigateToPan &&
                            scale != ReaderScale.FitScreen
                    ) &&
                    !settingsVisible &&
                    !chaptersVisible &&
                    !statsVisible
                ) {
                    val verticalDelta = event.changes.sumOf { it.scrollDelta.y.toDouble() }.toFloat()
                    val horizontalDelta = event.changes.sumOf { it.scrollDelta.x.toDouble() }.toFloat()
                    val delta = if (abs(horizontalDelta) > abs(verticalDelta)) {
                        horizontalDelta
                    } else {
                        verticalDelta
                    }
                    if (abs(delta) < 0.5f) return@onPointerEvent
                    val adjustedDelta = if (readerSettings.invertMouseWheel) -delta else delta
                    wheelAccumulator += adjustedDelta
                    if (abs(wheelAccumulator) >= wheelThreshold) {
                        if (readerSettings.mouseWheelAction == ChimahonReaderMouseWheelAction.Zoom) {
                            zoomByWheel(wheelAccumulator < 0f)
                        } else {
                            when {
                                wheelAccumulator > 0f && canNextPage -> onNextPage()
                                wheelAccumulator < 0f && canPreviousPage -> onPreviousPage()
                            }
                        }
                        wheelAccumulator = 0f
                    }
                }
            },
    ) {
        val readerWidth = maxWidth
        val readerHeight = maxHeight
        val useVerticalPageStrip = showPageStrip &&
            !readerSettings.forceHorizontalSeekbar &&
            readerSettings.landscapeVerticalSeekbar &&
            readerWidth > readerHeight &&
            pageCount > 1

        Box(
            modifier = Modifier
                .fillMaxSize()
                .semantics {
                    contentDescription = if (pageCount > 0) {
                        "Reader page $currentPage of $pageCount"
                    } else {
                        "Reader"
                    }
                    stateDescription = if (controlsVisible) "Controls visible" else "Controls hidden"
                    role = Role.Button
                    onClick(
                        label = if (controlsVisible) "Hide reader controls" else "Show reader controls",
                    ) {
                        onToggleControls()
                        true
                    }
                }
                .pointerInput(
                    currentPage,
                    pageCount,
                    controlsVisible,
                    readerSettings,
                    inputLocked,
                    onMarkChapterRead,
                ) {
                    detectTapGestures(
                        onLongPress = {
                            if (!inputLocked && readerSettings.longTapEnabled) {
                                if (readerSettings.readWithLongTap && onMarkChapterRead != null) {
                                    onMarkChapterRead()
                                } else {
                                    onToggleControls()
                                }
                            }
                        },
                        onDoubleTap = {
                            if (!inputLocked && readerSettings.doubleTapToZoom) {
                                onScaleChange(
                                    if (scale == ReaderScale.FitWidth) {
                                        ReaderScale.FitScreen
                                    } else {
                                        ReaderScale.FitWidth
                                    },
                                )
                            }
                        },
                        onTap = { offset ->
                            if (inputLocked) return@detectTapGestures
                            if (!tapNavigationEnabled || size.width <= 0 || size.height <= 0) {
                                onToggleControls()
                                return@detectTapGestures
                            }
                            when (
                                readerTapActionAt(
                                    offset = offset,
                                    width = size.width,
                                    height = size.height,
                                    smallerZones = readerSettings.smallerTapZones,
                                    tapZonePercent = readerSettings.tapZonePercent,
                                    inversion = readerSettings.invertTapZones,
                                    navigationMode = effectiveNavigationMode,
                                )
                            ) {
                                ReaderTapAction.Previous -> onPreviousPage()
                                ReaderTapAction.Menu -> onToggleControls()
                                ReaderTapAction.Next -> onNextPage()
                            }
                        },
                    )
                }
                .pointerInput(
                    currentPage,
                    pageCount,
                    mode,
                    scale,
                    inputLocked,
                    readerSettings.navigateToPan,
                    readerSettings.chapterSwipeDistance,
                    onPreviousChapter,
                    onNextChapter,
                ) {
                    val imagePanOwnsDrag = mode.paged && readerSettings.navigateToPan && scale != ReaderScale.FitScreen
                    if (!inputLocked && !imagePanOwnsDrag) {
                        val threshold = readerSettings.chapterSwipeDistance.coerceAtLeast(32).toFloat()
                        var totalDrag = 0f
                        detectHorizontalDragGestures(
                            onDragStart = { totalDrag = 0f },
                            onHorizontalDrag = { _, dragAmount ->
                                totalDrag += dragAmount
                            },
                            onDragEnd = {
                                if (abs(totalDrag) >= threshold) {
                                    val swipedRight = totalDrag > 0f
                                    when {
                                        currentPage <= 1 && swipedRight -> {
                                            if (mode.rightToLeft) onNextChapter?.invoke() else onPreviousChapter?.invoke()
                                        }
                                        currentPage >= pageCount && !swipedRight -> {
                                            if (mode.rightToLeft) onPreviousChapter?.invoke() else onNextChapter?.invoke()
                                        }
                                    }
                                }
                            },
                        )
                    }
                },
        ) {
            content()
        }

        AnimatedVisibility(
            visible = flashVisible,
            enter = fadeIn(),
            exit = fadeOut(),
            modifier = Modifier.fillMaxSize(),
        ) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(
                        readerFlashOverlayColor(readerSettings.flashColor, flashPulse)
                            .copy(alpha = readerFlashOverlayAlpha(readerSettings.flashColor)),
                    ),
            )
        }

        if (controlsVisible && tapNavigationEnabled && readerSettings.showNavigationOverlayOnStart) {
            ReaderTapZoneOverlay(
                navigationMode = effectiveNavigationMode,
                smallerZones = readerSettings.smallerTapZones,
                tapZonePercent = readerSettings.tapZonePercent,
                canvas = canvas,
                modifier = Modifier.fillMaxSize(),
            )
        }

        if (!controlsVisible && pageCount > 0 && readerSettings.showPageNumber) {
            ReaderPageIndicator(
                currentPage = currentPage,
                pageCount = pageCount,
                modifier = Modifier
                    .align(if (readerSettings.showProgressTop) Alignment.TopEnd else Alignment.BottomEnd)
                    .padding(16.dp),
            )
        }

        if (!controlsVisible && readerSettings.showReadingMode) {
            ReaderModeIndicator(
                mode = mode,
                scale = scale,
                canvas = canvas,
                modifier = Modifier
                    .align(Alignment.TopStart)
                    .padding(16.dp),
            )
        }

        if (!controlsVisible && readerSettings.desktopPageButtons && readerWidth >= 840.dp && pageCount > 0) {
            val leftAction = if (mode.rightToLeft) onNextPage else onPreviousPage
            val rightAction = if (mode.rightToLeft) onPreviousPage else onNextPage
            ReaderDesktopEdgePageButton(
                icon = if (mode.rightToLeft) UiIcon.Forward else UiIcon.Back,
                contentDescription = if (mode.rightToLeft) "Next page" else "Previous page",
                canvas = canvas,
                enabled = canPreviousPage,
                onClick = leftAction,
                modifier = Modifier
                    .align(Alignment.CenterStart)
                    .padding(start = 18.dp),
            )
            ReaderDesktopEdgePageButton(
                icon = if (mode.rightToLeft) UiIcon.Back else UiIcon.Forward,
                contentDescription = if (mode.rightToLeft) "Previous page" else "Next page",
                canvas = canvas,
                enabled = canNextPage,
                onClick = rightAction,
                modifier = Modifier
                    .align(Alignment.CenterEnd)
                    .padding(end = 18.dp),
            )
        }

        if ((!controlsVisible || readerSettings.alwaysShowChapterTransition) && pageCount > 0) {
            ReaderChapterEdgeHint(
                request = request,
                currentPage = currentPage,
                pageCount = pageCount,
                canvas = canvas,
                previousChapter = previousChapter,
                nextChapter = nextChapter,
                onPreviousChapter = onPreviousChapter,
                onNextChapter = onNextChapter,
                modifier = Modifier
                    .align(Alignment.BottomCenter)
                    .padding(bottom = if (controlsVisible) 96.dp else 18.dp),
            )
        }

        AnimatedVisibility(
            visible = controlsVisible && useVerticalPageStrip,
            enter = fadeIn(),
            exit = fadeOut(),
            modifier = Modifier
                .align(if (readerSettings.leftVerticalSeekbar) Alignment.CenterStart else Alignment.CenterEnd)
                .fillMaxHeight()
                .padding(
                    start = if (readerSettings.leftVerticalSeekbar) 8.dp else 0.dp,
                    top = 86.dp,
                    end = if (readerSettings.leftVerticalSeekbar) 0.dp else 8.dp,
                    bottom = 86.dp,
                ),
        ) {
            ReaderPageStrip(
                currentPage = currentPage,
                pageCount = pageCount,
                canvas = canvas,
                onPageSelected = onPageSelected,
                onPreviousChapter = onPreviousChapter,
                onNextChapter = onNextChapter,
                isRtl = mode.rightToLeft,
                vertical = true,
                modifier = Modifier.fillMaxHeight(),
            )
        }

        AnimatedVisibility(
            visible = controlsVisible,
            enter = slideInVertically(initialOffsetY = { -it }) + fadeIn(),
            exit = slideOutVertically(targetOffsetY = { -it }) + fadeOut(),
            modifier = Modifier
                .align(Alignment.TopCenter)
                .fillMaxWidth(),
        ) {
            Column(
                modifier = Modifier.fillMaxWidth(),
                horizontalAlignment = Alignment.CenterHorizontally,
            ) {
                ReaderTopBar(
                    request = request,
                    currentPage = currentPage,
                    pageCount = pageCount,
                    canvas = canvas,
                    showTitle = readerSettings.showTitle,
                    bookmarked = bookmarked,
                    bookmarkBusy = bookmarkBusy,
                    onBack = onBack,
                    onToggleHud = onToggleControls,
                    onToggleBookmark = onToggleBookmark,
                    downloadBusy = downloadBusy,
                    onDownloadChapter = onDownloadChapter,
                    readBusy = readBusy,
                    onMarkChapterRead = onMarkChapterRead,
                    onToggleOcrLookup = onToggleOcrLookup,
                    onOpenChapterUrl = onOpenChapterUrl,
                    onShareChapter = onShareChapter,
                )
                if (readerSettings.keepScreenOn) {
                    Label(
                        text = "Screen stays awake while reading",
                        color = Color.White,
                        size = 10,
                        weight = FontWeight.SemiBold,
                        maxLines = 1,
                        modifier = Modifier
                            .padding(top = 8.dp)
                            .clip(RoundedCornerShape(12.dp))
                            .background(ReaderPalette.selectedControl.copy(alpha = 0.9f))
                            .padding(horizontal = 10.dp, vertical = 5.dp),
                    )
                }
                if (readerWidth >= 720.dp && readerSettings.desktopReaderMenu) {
                    ReaderDesktopActionStrip(
                        mode = mode,
                        scale = scale,
                        canvas = canvas,
                        settingsVisible = settingsVisible,
                        chaptersVisible = chaptersVisible,
                        statsVisible = statsVisible,
                        cropActive = readerSettings.cropBorders,
                        onCycleMode = {
                            val nextIndex = (ReaderMode.entries.indexOf(mode) + 1) % ReaderMode.entries.size
                            onModeChange(ReaderMode.entries[nextIndex])
                        },
                        onToggleSettings = onToggleSettings,
                        onToggleChapters = onToggleChapters,
                        onToggleStats = onToggleStats,
                        onToggleCrop = onToggleCrop,
                        onToggleOcrLookup = onToggleOcrLookup,
                        onToggleBookmark = onToggleBookmark,
                        onDownloadChapter = onDownloadChapter,
                        onMarkChapterRead = onMarkChapterRead,
                        onOpenChapterUrl = onOpenChapterUrl,
                        onShareChapter = onShareChapter,
                        modifier = Modifier
                            .fillMaxWidth(0.96f)
                            .widthIn(max = 760.dp)
                            .padding(top = 6.dp),
                    )
                }
            }
        }

        AnimatedVisibility(
            visible = controlsVisible,
            enter = slideInVertically(initialOffsetY = { it }) + fadeIn(),
            exit = slideOutVertically(targetOffsetY = { it }) + fadeOut(),
            modifier = Modifier
                .align(Alignment.BottomCenter)
                .fillMaxWidth(),
        ) {
            Column(
                modifier = Modifier.fillMaxWidth(),
                horizontalAlignment = Alignment.CenterHorizontally,
            ) {
                if (statsVisible) {
                    ReaderStatisticsPanel(
                        request = request,
                        mode = mode,
                        scale = scale,
                        currentPage = currentPage,
                        pageCount = pageCount,
                        settings = readerSettings,
                        elapsedSeconds = elapsedSeconds,
                        previousChapter = previousChapter,
                        nextChapter = nextChapter,
                        modifier = Modifier
                            .fillMaxWidth(0.98f)
                            .widthIn(max = 720.dp)
                            .padding(bottom = 6.dp),
                    )
                }
                if (chaptersVisible) {
                    ReaderChapterQueuePanel(
                        request = request,
                        previousChapter = previousChapter,
                        nextChapter = nextChapter,
                        onOpenChapter = onOpenChapter,
                        onBookmarkChapter = onBookmarkChapterRef,
                        onDownloadChapter = onDownloadChapterRef,
                        onMarkChapterRead = onMarkChapterRefRead,
                        modifier = Modifier
                            .fillMaxWidth(0.98f)
                            .widthIn(max = 800.dp)
                            .padding(bottom = 6.dp),
                    )
                }
                if (settingsVisible) {
                    ReaderSettingsPanel(
                        mode = mode,
                        scale = scale,
                        canvas = canvas,
                        settings = readerSettings,
                        onModeChange = onModeChange,
                        onScaleChange = onScaleChange,
                        onCanvasChange = onCanvasChange,
                        onSettingsChange = { updated ->
                            if (updated.showPageStrip != showPageStrip) {
                                onShowPageStripChange(updated.showPageStrip)
                            } else if (updated.keepControlsVisible != showControlsOnStart) {
                                onShowControlsOnStartChange(updated.keepControlsVisible)
                            } else {
                                onReaderSettingsChange(updated)
                            }
                        },
                        modifier = Modifier
                            .fillMaxWidth(0.98f)
                            .widthIn(max = 720.dp)
                            .padding(bottom = 6.dp),
                    )
                }
                ReaderChapterNavigator(
                    request = request,
                    previousChapter = previousChapter,
                    nextChapter = nextChapter,
                    canvas = canvas,
                    onPreviousChapter = onPreviousChapter,
                    onNextChapter = onNextChapter,
                    onOpenChapters = onToggleChapters,
                    modifier = Modifier
                        .fillMaxWidth(0.98f)
                        .widthIn(max = 720.dp)
                        .padding(bottom = 6.dp),
                )
                if (showPageStrip && !useVerticalPageStrip) {
                    ReaderPageStrip(
                        currentPage = currentPage,
                        pageCount = pageCount,
                        canvas = canvas,
                        onPageSelected = onPageSelected,
                        onPreviousChapter = onPreviousChapter,
                        onNextChapter = onNextChapter,
                        isRtl = mode.rightToLeft,
                    )
                }
                ReaderControlBar(
                    mode = mode,
                    canvas = canvas,
                    currentPage = currentPage,
                    pageCount = pageCount,
                    canPreviousPage = canPreviousPage,
                    canNextPage = canNextPage,
                    previousPageContentDescription = previousPageContentDescription,
                    nextPageContentDescription = nextPageContentDescription,
                    settingsVisible = settingsVisible,
                    chaptersVisible = chaptersVisible,
                    statsVisible = statsVisible,
                    showPageStrip = showPageStrip,
                    wideLayout = readerWidth >= 720.dp,
                    bottomButtons = readerSettings.bottomButtons,
                    cropActive = readerSettings.cropBorders,
                    orientation = readerSettings.orientation,
                    dualPageMode = readerSettings.dualPageMode,
                    invertDoublePages = readerSettings.invertDoublePages,
                    showPercentage = readerSettings.showPercentage,
                    onOpenChapterUrl = onOpenChapterUrl,
                    onShareChapter = onShareChapter,
                    onCycleMode = {
                        val nextIndex = (ReaderMode.entries.indexOf(mode) + 1) % ReaderMode.entries.size
                        onModeChange(ReaderMode.entries[nextIndex])
                    },
                    onCycleOrientation = cycleOrientation,
                    onCyclePageLayout = cyclePageLayout,
                    onShiftDoublePages = shiftDoublePages,
                    onToggleSettings = onToggleSettings,
                    onToggleChapters = onToggleChapters,
                    onToggleStats = onToggleStats,
                    onToggleCrop = onToggleCrop,
                    onToggleOcrLookup = onToggleOcrLookup,
                    onPreviousPage = onPreviousPage,
                    onNextPage = onNextPage,
                    onPageSelected = onPageSelected,
                )
            }
        }
    }
}

private enum class ReaderTapAction {
    Previous,
    Menu,
    Next,
}

@Composable
private fun ReaderTapZoneOverlay(
    navigationMode: ChimahonReaderNavigationMode,
    smallerZones: Boolean,
    tapZonePercent: Int,
    canvas: ReaderCanvas,
    modifier: Modifier = Modifier,
) {
    val edgeWeight = ((if (smallerZones) min(tapZonePercent, 22) else tapZonePercent).coerceIn(12, 40)) / 100f
    val centerWeight = (1f - edgeWeight * 2f).coerceAtLeast(0.25f)
    val paneTint = readerHudContent(canvas)
    val paneBackground = ReaderPalette.selectedControl.copy(alpha = 0.10f)
    if (navigationMode == ChimahonReaderNavigationMode.Vertical) {
        Column(
            modifier = modifier.padding(horizontal = 28.dp, vertical = 92.dp),
            verticalArrangement = Arrangement.spacedBy(8.dp),
        ) {
            ReaderTapZonePane(
                icon = UiIcon.Back,
                label = "Previous",
                tint = paneTint,
                background = paneBackground,
                modifier = Modifier
                    .weight(edgeWeight)
                    .fillMaxWidth(),
            )
            ReaderTapZonePane(
                icon = UiIcon.More,
                label = "HUD",
                tint = paneTint,
                background = paneBackground.copy(alpha = 0.07f),
                modifier = Modifier
                    .weight(centerWeight)
                    .fillMaxWidth(),
            )
            ReaderTapZonePane(
                icon = UiIcon.Forward,
                label = "Next",
                tint = paneTint,
                background = paneBackground,
                modifier = Modifier
                    .weight(edgeWeight)
                    .fillMaxWidth(),
            )
        }
    } else {
        val rtl = navigationMode == ChimahonReaderNavigationMode.RightToLeft
        Row(
            modifier = modifier.padding(horizontal = 28.dp, vertical = 92.dp),
            horizontalArrangement = Arrangement.spacedBy(8.dp),
        ) {
            ReaderTapZonePane(
                icon = if (rtl) UiIcon.Forward else UiIcon.Back,
                label = if (rtl) "Next" else "Previous",
                tint = paneTint,
                background = paneBackground,
                modifier = Modifier
                    .weight(edgeWeight)
                    .fillMaxHeight(),
            )
            ReaderTapZonePane(
                icon = UiIcon.More,
                label = "HUD",
                tint = paneTint,
                background = paneBackground.copy(alpha = 0.07f),
                modifier = Modifier
                    .weight(centerWeight)
                    .fillMaxHeight(),
            )
            ReaderTapZonePane(
                icon = if (rtl) UiIcon.Back else UiIcon.Forward,
                label = if (rtl) "Previous" else "Next",
                tint = paneTint,
                background = paneBackground,
                modifier = Modifier
                    .weight(edgeWeight)
                    .fillMaxHeight(),
            )
        }
    }
}

@Composable
private fun ReaderTapZonePane(
    icon: UiIcon,
    label: String,
    tint: Color,
    background: Color,
    modifier: Modifier = Modifier,
) {
    Box(
        modifier = modifier
            .clip(RoundedCornerShape(18.dp))
            .background(background)
            .border(1.dp, tint.copy(alpha = 0.10f), RoundedCornerShape(18.dp)),
        contentAlignment = Alignment.Center,
    ) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(5.dp),
        ) {
            IconGlyph(
                icon = icon,
                contentDescription = label,
                tint = tint.copy(alpha = 0.42f),
                modifier = Modifier.size(24.dp),
            )
            Label(
                text = label,
                color = tint.copy(alpha = 0.46f),
                size = 10,
                weight = FontWeight.SemiBold,
                maxLines = 1,
            )
        }
    }
}

private fun readerTapActionAt(
    offset: Offset,
    width: Int,
    height: Int,
    smallerZones: Boolean,
    tapZonePercent: Int,
    inversion: ChimahonTapZoneInvert,
    navigationMode: ChimahonReaderNavigationMode,
): ReaderTapAction {
    var x = (offset.x / width.toFloat()).coerceIn(0f, 1f)
    var y = (offset.y / height.toFloat()).coerceIn(0f, 1f)
    if (inversion == ChimahonTapZoneInvert.Horizontal || inversion == ChimahonTapZoneInvert.Both) {
        x = 1f - x
    }
    if (inversion == ChimahonTapZoneInvert.Vertical || inversion == ChimahonTapZoneInvert.Both) {
        y = 1f - y
    }
    if (navigationMode == ChimahonReaderNavigationMode.RightToLeft) {
        x = 1f - x
    }
    val configuredEdge = tapZonePercent.coerceIn(0, 40) / 100f
    val edge = if (smallerZones) min(configuredEdge, 0.22f) else configuredEdge
    if (navigationMode == ChimahonReaderNavigationMode.Vertical) {
        return when {
            y < edge -> ReaderTapAction.Previous
            y > 1f - edge -> ReaderTapAction.Next
            else -> ReaderTapAction.Menu
        }
    }
    return when {
        x < edge || (x < 1f - edge && y < edge) -> ReaderTapAction.Previous
        x > 1f - edge || (x > edge && y > 1f - edge) -> ReaderTapAction.Next
        else -> ReaderTapAction.Menu
    }
}

@Composable
private fun ReaderChapterEdgeHint(
    request: ChimahonReaderRequest,
    currentPage: Int,
    pageCount: Int,
    canvas: ReaderCanvas,
    previousChapter: ChimahonReaderChapterRef?,
    nextChapter: ChimahonReaderChapterRef?,
    onPreviousChapter: (() -> Unit)?,
    onNextChapter: (() -> Unit)?,
    modifier: Modifier = Modifier,
) {
    val atStart = currentPage <= 1
    val atEnd = currentPage >= pageCount
    if (!atStart && !atEnd) return
    val destination = when {
        atStart -> previousChapter
        atEnd -> nextChapter
        else -> null
    }
    val onClick = when {
        atStart -> onPreviousChapter
        atEnd -> onNextChapter
        else -> null
    }
    val currentChapter = ChimahonReaderChapterRef(
        chapterId = null,
        chapterName = request.chapterName,
        chapterUrl = request.chapterUrl,
        chapterNumber = request.chapterNumber,
        scanlator = request.scanlator,
        dateUpload = 0L,
    )
    val gap = when {
        destination == null -> 0
        atStart -> readerChapterGap(currentChapter.chapterNumber, destination.chapterNumber)
        else -> readerChapterGap(destination.chapterNumber, currentChapter.chapterNumber)
    }
    val clickModifier = if (onClick != null) {
        Modifier.clickable(role = Role.Button, onClick = onClick)
    } else {
        Modifier
    }
    val transitionDescription = when {
        destination == null -> if (atStart) "No previous chapter" else "No next chapter"
        atStart -> destination.readerChapterActionDescription("Previous")
        else -> destination.readerChapterActionDescription("Next")
    }
    Column(
        modifier = modifier
            .widthIn(max = 520.dp)
            .fillMaxWidth(0.92f)
            .clip(RoundedCornerShape(18.dp))
            .background(readerHudBackground(canvas).copy(alpha = 0.92f))
            .semantics(mergeDescendants = true) {
                contentDescription = transitionDescription
                stateDescription = if (destination == null) "Unavailable" else "Available"
            }
            .then(clickModifier)
            .border(1.dp, readerHudContent(canvas).copy(alpha = 0.10f), RoundedCornerShape(18.dp))
            .padding(horizontal = 14.dp, vertical = 12.dp),
        verticalArrangement = Arrangement.spacedBy(10.dp),
    ) {
        if (atStart) {
            ReaderTransitionChapterText(
                header = "Previous chapter",
                chapter = destination,
                fallback = "No previous chapter",
                canvas = canvas,
            )
            if (gap > 0) {
                ReaderTransitionNotice(
                    icon = UiIcon.Info,
                    text = "$gap missing chapter(s)",
                    canvas = canvas,
                    error = true,
                )
            }
            ReaderTransitionChapterText(
                header = "Current chapter",
                chapter = currentChapter,
                canvas = canvas,
            )
        } else {
            ReaderTransitionChapterText(
                header = "Finished",
                chapter = currentChapter,
                canvas = canvas,
            )
            if (gap > 0) {
                ReaderTransitionNotice(
                    icon = UiIcon.Info,
                    text = "$gap missing chapter(s)",
                    canvas = canvas,
                    error = true,
                )
            }
            ReaderTransitionChapterText(
                header = "Next chapter",
                chapter = destination,
                fallback = "No next chapter",
                canvas = canvas,
            )
        }
        ReaderTransitionNotice(
            icon = when {
                destination == null -> UiIcon.Info
                atStart -> UiIcon.SkipPrevious
                else -> UiIcon.SkipNext
            },
            text = when {
                destination == null -> "No adjacent chapter available"
                atStart -> "Previous chapter available"
                else -> "Next chapter available"
            },
            canvas = canvas,
            error = false,
        )
    }
}

@Composable
private fun ReaderTransitionChapterText(
    header: String,
    chapter: ChimahonReaderChapterRef?,
    canvas: ReaderCanvas,
    modifier: Modifier = Modifier,
    fallback: String = "",
) {
    Column(modifier = modifier.fillMaxWidth()) {
        Label(
            text = header,
            color = readerHudContent(canvas).copy(alpha = 0.72f),
            size = 11,
            weight = FontWeight.SemiBold,
            maxLines = 1,
        )
        if (chapter == null) {
            ReaderTransitionNotice(
                icon = UiIcon.Info,
                text = fallback,
                canvas = canvas,
                modifier = Modifier.padding(top = 6.dp),
            )
        } else {
            Row(
                modifier = Modifier
                    .padding(top = 4.dp)
                    .fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                verticalAlignment = Alignment.Top,
            ) {
                if (chapter.read) {
                    IconGlyph(
                        icon = UiIcon.CheckCircle,
                        contentDescription = "Read",
                        tint = ReaderPalette.selectedControl,
                        modifier = Modifier
                            .padding(top = 3.dp)
                            .size(18.dp),
                    )
                }
                Column(modifier = Modifier.weight(1f)) {
                    Label(
                        text = chapter.chapterName,
                        color = readerHudContent(canvas),
                        size = 17,
                        weight = FontWeight.SemiBold,
                        maxLines = 3,
                    )
                    chapter.scanlator?.takeIf { it.isNotBlank() }?.let { scanlator ->
                        Label(
                            text = scanlator,
                            color = readerHudContent(canvas).copy(alpha = 0.62f),
                            size = 11,
                            weight = FontWeight.Normal,
                            maxLines = 2,
                            modifier = Modifier.padding(top = 3.dp),
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun ReaderTransitionNotice(
    icon: UiIcon,
    text: String,
    canvas: ReaderCanvas,
    modifier: Modifier = Modifier,
    error: Boolean = false,
) {
    Row(
        modifier = modifier
            .clip(RoundedCornerShape(50))
            .background(
                if (error) {
                    ChimahonPalette.errorContainer.copy(alpha = 0.22f)
                } else {
                    readerHudContent(canvas).copy(alpha = 0.08f)
                },
            )
            .border(
                1.dp,
                if (error) ChimahonPalette.error.copy(alpha = 0.32f) else readerHudContent(canvas).copy(alpha = 0.08f),
                RoundedCornerShape(50),
            )
            .padding(horizontal = 11.dp, vertical = 7.dp),
        horizontalArrangement = Arrangement.spacedBy(8.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        IconGlyph(
            icon = icon,
            contentDescription = text,
            tint = if (error) ChimahonPalette.error else ReaderPalette.selectedControl,
            modifier = Modifier.size(18.dp),
        )
        Label(
            text = text,
            color = readerHudContent(canvas),
            size = 12,
            weight = FontWeight.SemiBold,
            maxLines = 2,
        )
    }
}

private fun readerChapterGap(
    goingTo: Double,
    current: Double,
): Int {
    if (goingTo <= 0.0 || current <= 0.0) return 0
    return (abs(goingTo - current).roundToInt() - 1).coerceAtLeast(0)
}

@Composable
private fun ReaderModeIndicator(
