@Composable
private fun ReaderPageStrip(
    currentPage: Int,
    pageCount: Int,
    canvas: ReaderCanvas,
    onPageSelected: (Int) -> Unit,
    onPreviousChapter: (() -> Unit)?,
    onNextChapter: (() -> Unit)?,
    previousChapterContentDescription: String = if (onPreviousChapter == null) "No previous chapter" else "Previous chapter",
    nextChapterContentDescription: String = if (onNextChapter == null) "No next chapter" else "Next chapter",
    isRtl: Boolean = false,
    vertical: Boolean = false,
    modifier: Modifier = Modifier,
) {
    var scrubPage by remember(pageCount) {
        mutableIntStateOf((currentPage - 1).coerceIn(0, (pageCount - 1).coerceAtLeast(0)))
    }
    LaunchedEffect(currentPage, pageCount) {
        scrubPage = (currentPage - 1).coerceIn(0, (pageCount - 1).coerceAtLeast(0))
    }
    val selectPage: (Int) -> Unit = { pageIndex ->
        if (pageIndex != scrubPage) {
            scrubPage = pageIndex
            onPageSelected(pageIndex)
        }
    }
    val progress = if (pageCount <= 1) {
        0f
    } else {
        (currentPage - 1).toFloat() / (pageCount - 1).toFloat()
    }

    if (vertical) {
        Column(
            modifier = modifier
                .width(64.dp)
                .padding(horizontal = 5.dp, vertical = 6.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(6.dp),
        ) {
            ReaderNavigatorChapterAction(
                icon = UiIcon.SkipPrevious,
                contentDescription = previousChapterContentDescription,
                canvas = canvas,
                onClick = onPreviousChapter,
            )
            Column(
                modifier = Modifier
                    .weight(1f)
                    .width(54.dp)
                    .clip(RoundedCornerShape(14.dp))
                    .background(readerHudBackground(canvas).copy(alpha = 0.96f))
                    .border(1.dp, readerHudContent(canvas).copy(alpha = 0.08f), RoundedCornerShape(14.dp))
                    .padding(horizontal = 8.dp, vertical = 10.dp),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                Label(
                    text = currentPage.toString(),
                    color = readerHudContent(canvas),
                    size = 10,
                    weight = FontWeight.SemiBold,
                    maxLines = 1,
                )
                Canvas(
                    modifier = Modifier
                        .weight(1f)
                        .fillMaxWidth()
                        .semantics {
                            contentDescription = "Page $currentPage of $pageCount"
                        }
                        .pointerInput(pageCount) {
                            detectTapGestures { offset ->
                                selectPage(
                                    readerVerticalPageIndexAt(
                                        y = offset.y,
                                        height = size.height,
                                        pageCount = pageCount,
                                    ),
                                )
                            }
                        }
                        .pointerInput(pageCount) {
                            detectDragGestures { change, _ ->
                                selectPage(
                                    readerVerticalPageIndexAt(
                                        y = change.position.y,
                                        height = size.height,
                                        pageCount = pageCount,
                                    ),
                                )
                                change.consume()
                            }
                        },
                ) {
                    val x = size.width / 2f
                    val thumbY = size.height * progress
                    drawLine(
                        color = readerHudContent(canvas).copy(alpha = 0.20f),
                        start = Offset(x, 0f),
                        end = Offset(x, size.height),
                        strokeWidth = 4f,
                        cap = StrokeCap.Round,
                    )
                    drawLine(
                        color = ReaderPalette.selectedControl,
                        start = Offset(x, 0f),
                        end = Offset(x, thumbY),
                        strokeWidth = 4f,
                        cap = StrokeCap.Round,
                    )
                    drawCircle(
                        color = readerHudContent(canvas),
                        radius = 6f,
                        center = Offset(x, thumbY),
                    )
                }
                Label(
                    text = pageCount.toString(),
                    color = readerHudContent(canvas).copy(alpha = 0.62f),
                    size = 10,
                    weight = FontWeight.SemiBold,
                    maxLines = 1,
                )
            }
            ReaderNavigatorChapterAction(
                icon = UiIcon.SkipNext,
                contentDescription = nextChapterContentDescription,
                canvas = canvas,
                onClick = onNextChapter,
            )
        }
        return
    }

    Row(
        modifier = modifier
            .fillMaxWidth()
            .padding(horizontal = 10.dp, vertical = 6.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(6.dp),
    ) {
        ReaderNavigatorChapterAction(
            icon = UiIcon.SkipPrevious,
            contentDescription = previousChapterContentDescription,
            canvas = canvas,
            onClick = onPreviousChapter,
        )
        Column(
            modifier = Modifier
                .weight(1f)
                .height(48.dp)
                .clip(RoundedCornerShape(14.dp))
                .background(readerHudBackground(canvas).copy(alpha = 0.96f))
                .border(1.dp, readerHudContent(canvas).copy(alpha = 0.08f), RoundedCornerShape(14.dp))
                .padding(horizontal = 12.dp, vertical = 6.dp),
            verticalArrangement = Arrangement.spacedBy(5.dp),
        ) {
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.SpaceBetween,
            ) {
                Label(
                    text = currentPage.toString(),
                    color = readerHudContent(canvas),
                    size = 10,
                    weight = FontWeight.SemiBold,
                    maxLines = 1,
                )
                Label(
                    text = readerProgressText(currentPage, pageCount),
                    color = readerHudContent(canvas).copy(alpha = 0.58f),
                    size = 9,
                    weight = FontWeight.SemiBold,
                    maxLines = 1,
                )
                Label(
                    text = pageCount.toString(),
                    color = readerHudContent(canvas).copy(alpha = 0.62f),
                    size = 10,
                    weight = FontWeight.SemiBold,
                    maxLines = 1,
                )
            }
            Canvas(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(18.dp)
                    .semantics {
                        contentDescription = "Page $currentPage of $pageCount"
                    }
                    .pointerInput(pageCount, isRtl) {
                        detectTapGestures { offset ->
                            selectPage(
                                readerPageIndexAt(
                                    x = offset.x,
                                    width = size.width,
                                    pageCount = pageCount,
                                    isRtl = isRtl,
                                ),
                            )
                        }
                    }
                    .pointerInput(pageCount, isRtl) {
                        detectHorizontalDragGestures { change, _ ->
                            selectPage(
                                readerPageIndexAt(
                                    x = change.position.x,
                                    width = size.width,
                                    pageCount = pageCount,
                                    isRtl = isRtl,
                                ),
                            )
                        }
                    },
            ) {
                val y = size.height / 2f
                val visualProgress = if (isRtl) 1f - progress else progress
                val thumbX = size.width * visualProgress
                drawLine(
                    color = readerHudContent(canvas).copy(alpha = 0.20f),
                    start = Offset(0f, y),
                    end = Offset(size.width, y),
                    strokeWidth = 4f,
                    cap = StrokeCap.Round,
                )
                drawLine(
                    color = ReaderPalette.selectedControl,
                    start = if (isRtl) Offset(size.width, y) else Offset(0f, y),
                    end = Offset(thumbX, y),
                    strokeWidth = 4f,
                    cap = StrokeCap.Round,
                )
                drawCircle(
                    color = readerHudContent(canvas),
                    radius = 6f,
                    center = Offset(thumbX, y),
                )
            }
        }
        ReaderNavigatorChapterAction(
            icon = UiIcon.SkipNext,
            contentDescription = nextChapterContentDescription,
            canvas = canvas,
            onClick = onNextChapter,
        )
    }
}

private fun readerPageIndexAt(
    x: Float,
    width: Int,
    pageCount: Int,
    isRtl: Boolean,
): Int {
    if (width <= 0 || pageCount <= 1) return 0
    val visualFraction = (x / width.toFloat()).coerceIn(0f, 1f)
    val logicalFraction = if (isRtl) 1f - visualFraction else visualFraction
    return (logicalFraction * (pageCount - 1).toFloat() + 0.5f)
        .toInt()
        .coerceIn(0, pageCount - 1)
}

private fun readerVerticalPageIndexAt(
    y: Float,
    height: Int,
    pageCount: Int,
): Int {
    if (height <= 0 || pageCount <= 1) return 0
    val fraction = (y / height.toFloat()).coerceIn(0f, 1f)
    return (fraction * (pageCount - 1).toFloat() + 0.5f)
        .toInt()
        .coerceIn(0, pageCount - 1)
}

@Composable
private fun ReaderNavigatorChapterAction(
    icon: UiIcon,
    contentDescription: String,
    canvas: ReaderCanvas,
    onClick: (() -> Unit)?,
) {
    Box(
        modifier = Modifier
            .size(42.dp)
            .clip(CircleShape)
            .background(readerHudBackground(canvas).copy(alpha = if (onClick != null) 0.94f else 0.54f))
            .border(1.dp, readerHudContent(canvas).copy(alpha = 0.08f), CircleShape)
            .semantics {
                stateDescription = if (onClick != null) "Available" else "Unavailable"
            }
            .clickable(enabled = onClick != null, role = Role.Button) { onClick?.invoke() }
            .padding(10.dp),
        contentAlignment = Alignment.Center,
    ) {
        IconGlyph(
            icon = icon,
            contentDescription = contentDescription,
            tint = if (onClick != null) readerHudContent(canvas) else readerHudContent(canvas).copy(alpha = 0.28f),
            modifier = Modifier.size(20.dp),
        )
    }
}

private enum class ReaderSettingsTab(val title: String) {
    ReadingMode("Reading mode"),
    General("General"),
    ColorFilter("Color filter"),
}

@Composable
private fun ReaderSettingsPanel(
    mode: ReaderMode,
    scale: ReaderScale,
    canvas: ReaderCanvas,
    settings: ChimahonReaderSettings,
    onModeChange: (ReaderMode) -> Unit,
    onScaleChange: (ReaderScale) -> Unit,
    onCanvasChange: (ReaderCanvas) -> Unit,
    onSettingsChange: (ChimahonReaderSettings) -> Unit,
    modifier: Modifier = Modifier,
) {
    var selectedTab by remember { mutableStateOf(ReaderSettingsTab.ReadingMode) }
    Column(
        modifier = modifier
            .heightIn(max = 600.dp)
            .clip(RoundedCornerShape(18.dp))
            .background(ReaderPalette.chrome.copy(alpha = 0.98f))
            .border(1.dp, ReaderPalette.divider.copy(alpha = 0.82f), RoundedCornerShape(18.dp))
            .verticalScroll(rememberScrollState())
            .padding(horizontal = 14.dp, vertical = 10.dp),
        verticalArrangement = Arrangement.spacedBy(10.dp),
    ) {
        ReaderSheetDragHandle()
        ReaderSheetHeader(
            title = "Reader settings",
            subtitle = "${mode.title} - ${scale.title} - ${canvas.title}",
            icon = UiIcon.Settings,
        )
        ReaderSettingsTabRow(
            selected = selectedTab,
            onSelect = { selectedTab = it },
        )
        when (selectedTab) {
            ReaderSettingsTab.ReadingMode -> ReaderReadingModeSettingsPage(
                mode = mode,
                scale = scale,
                settings = settings,
                onModeChange = onModeChange,
                onScaleChange = onScaleChange,
                onSettingsChange = onSettingsChange,
            )
            ReaderSettingsTab.General -> ReaderGeneralSettingsPage(
                canvas = canvas,
                settings = settings,
                onCanvasChange = onCanvasChange,
                onSettingsChange = onSettingsChange,
            )
            ReaderSettingsTab.ColorFilter -> ReaderColorFilterSettingsPage(
                settings = settings,
                onSettingsChange = onSettingsChange,
            )
        }
    }
}

@Composable
private fun ReaderReadingModeSettingsPage(
    mode: ReaderMode,
    scale: ReaderScale,
    settings: ChimahonReaderSettings,
    onModeChange: (ReaderMode) -> Unit,
    onScaleChange: (ReaderScale) -> Unit,
    onSettingsChange: (ChimahonReaderSettings) -> Unit,
) {
    ReaderSheetSectionTitle("For this series")
    ReaderOptionRow(
        label = "Reading mode",
        options = ReaderMode.entries.map { it.title },
        selected = mode.title,
        onSelect = { title ->
            ReaderMode.entries.firstOrNull { it.title == title }?.let(onModeChange)
        },
    )
    ReaderOptionRow(
        label = "Orientation",
        options = ChimahonReaderOrientation.entries.map { it.readerTitle() },
        selected = settings.orientation.readerTitle(),
        onSelect = { title ->
            ChimahonReaderOrientation.entries
                .firstOrNull { it.readerTitle() == title }
                ?.let { onSettingsChange(settings.copy(orientation = it)) }
        },
    )

    if (mode.paged) {
        ReaderSheetSectionTitle("Pager viewer")
        ReaderOptionRow(
            label = "Navigation",
            options = ChimahonReaderNavigationMode.entries.map { it.readerTitle() },
            selected = settings.navigationMode.readerTitle(),
            onSelect = { title ->
                ChimahonReaderNavigationMode.entries
                    .firstOrNull { it.readerTitle() == title }
                    ?.let { onSettingsChange(settings.copy(navigationMode = it)) }
            },
        )
        ReaderOptionRow(
            label = "Invert taps",
            options = ChimahonTapZoneInvert.entries.map { it.readerTitle() },
            selected = settings.invertTapZones.readerTitle(),
            onSelect = { title ->
                ChimahonTapZoneInvert.entries
                    .firstOrNull { it.readerTitle() == title }
                    ?.let { onSettingsChange(settings.copy(invertTapZones = it)) }
            },
        )
        ReaderOptionRow(
            label = "Image scale",
            options = ReaderScale.entries.map { it.title },
            selected = scale.title,
            onSelect = { title ->
                ReaderScale.entries.firstOrNull { it.title == title }?.let(onScaleChange)
            },
        )
        ReaderOptionRow(
            label = "Zoom start",
            options = ChimahonReaderZoomStart.entries.map { it.title },
            selected = settings.pagedZoomStart.title,
            onSelect = { title ->
                ChimahonReaderZoomStart.entries
                    .firstOrNull { it.title == title }
                    ?.let { onSettingsChange(settings.copy(pagedZoomStart = it)) }
            },
        )
        ReaderOptionRow(
            label = "Page layout",
            options = ChimahonDualPageMode.entries.map { it.readerTitle() },
            selected = settings.dualPageMode.readerTitle(),
            onSelect = { title ->
                ChimahonDualPageMode.entries
                    .firstOrNull { it.readerTitle() == title }
                    ?.let { onSettingsChange(settings.copy(dualPageMode = it)) }
            },
        )
        ReaderToggleRow(
            label = "Smaller tap zones",
            checked = settings.smallerTapZones,
            onCheckedChange = { onSettingsChange(settings.copy(smallerTapZones = it)) },
        )
        ReaderToggleRow(
            label = "Crop borders",
            checked = settings.cropBorders,
            onCheckedChange = { onSettingsChange(settings.copy(cropBorders = it)) },
        )
        ReaderToggleRow(
            label = "Landscape zoom",
            checked = settings.landscapeZoom,
            onCheckedChange = { onSettingsChange(settings.copy(landscapeZoom = it)) },
        )
        if (settings.landscapeZoom) {
            ReaderOptionRow(
                label = "Wide zoom",
                options = ChimahonReaderLandscapeZoomType.entries.map { it.title },
                selected = settings.landscapeZoomType.title,
                onSelect = { title ->
                    ChimahonReaderLandscapeZoomType.entries
                        .firstOrNull { it.title == title }
                        ?.let { onSettingsChange(settings.copy(landscapeZoomType = it)) }
                },
            )
        }
        ReaderToggleRow(
            label = "Navigate to pan",
            checked = settings.navigateToPan,
            onCheckedChange = { onSettingsChange(settings.copy(navigateToPan = it)) },
        )
        ReaderToggleRow(
            label = "Dual page split",
            checked = settings.splitWidePages,
            onCheckedChange = { onSettingsChange(settings.copy(splitWidePages = it)) },
        )
