@Composable
private fun ReaderSettingsTabRow(
    selected: ReaderSettingsTab,
    onSelect: (ReaderSettingsTab) -> Unit,
) {
    LazyRow(
        modifier = Modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(18.dp))
            .background(ReaderPalette.control.copy(alpha = 0.68f))
            .padding(3.dp),
        horizontalArrangement = Arrangement.spacedBy(3.dp),
    ) {
        items(ReaderSettingsTab.entries.toList(), key = { it.name }) { tab ->
            val active = tab == selected
            Box(
                modifier = Modifier
                    .height(34.dp)
                    .clip(RoundedCornerShape(16.dp))
                    .background(if (active) ReaderPalette.selectedControl else Color.Transparent)
                    .clickable { onSelect(tab) }
                    .padding(horizontal = 14.dp),
                contentAlignment = Alignment.Center,
            ) {
                Label(
                    text = tab.title,
                    color = if (active) Color.White else ReaderPalette.secondaryText,
                    size = 11,
                    weight = if (active) FontWeight.SemiBold else FontWeight.Normal,
                    maxLines = 1,
                )
            }
        }
    }
}

@Composable
private fun ReaderColorPreview(settings: ChimahonReaderSettings) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .heightIn(min = 48.dp)
            .clip(RoundedCornerShape(6.dp))
            .background(ReaderPalette.control.copy(alpha = 0.36f))
            .padding(horizontal = 12.dp, vertical = 8.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(10.dp),
    ) {
        Box(
            modifier = Modifier
                .size(32.dp)
                .clip(RoundedCornerShape(6.dp))
                .background(Color(settings.colorFilterValue)),
        )
        Column(modifier = Modifier.weight(1f)) {
            Label(
                text = settings.colorFilterMode.title,
                color = Color.White.copy(alpha = 0.88f),
                size = 12,
                weight = FontWeight.SemiBold,
                maxLines = 1,
            )
            Label(
                text = "R ${settings.colorFilterValue.colorComponent(16)}  " +
                    "G ${settings.colorFilterValue.colorComponent(8)}  " +
                    "B ${settings.colorFilterValue.colorComponent(0)}  " +
                    "A ${settings.colorFilterValue.colorComponent(24)}",
                color = ReaderPalette.secondaryText,
                size = 10,
                maxLines = 1,
                modifier = Modifier.padding(top = 2.dp),
            )
        }
    }
}

private fun Int.colorComponent(shift: Int): Int = (this ushr shift) and 0xFF

private fun Int.withColorComponent(shift: Int, delta: Int): Int {
    val next = (colorComponent(shift) + delta).coerceIn(0, 255)
    return withColorComponentValue(shift, next)
}

private fun Int.withColorComponentValue(shift: Int, value: Int): Int {
    val next = value.coerceIn(0, 255)
    val mask = 0xFF shl shift
    return (this and mask.inv()) or (next shl shift)
}

private fun readerColorChannelOptions(): List<String> {
    return listOf("0", "32", "64", "96", "128", "160", "192", "224", "255")
}

private fun Double.toReaderNumberTitle(suffix: String = ""): String {
    val roundedInt = roundToInt()
    val scaledTenths = (this * 10.0).roundToInt()
    val scaledHundredths = (this * 100.0).roundToInt()
    val number = when {
        abs(this - roundedInt.toDouble()) < 0.001 -> roundedInt.toString()
        abs(this - scaledTenths / 10.0) < 0.001 -> (scaledTenths / 10.0).toString()
        else -> (scaledHundredths / 100.0).toString()
    }
    return "$number$suffix"
}

private fun String.toReaderDouble(defaultValue: Double): Double {
    return trim()
        .removeSuffix(" px")
        .removeSuffix(" em")
        .removeSuffix("%")
        .toDoubleOrNull()
        ?: defaultValue
}

