@Composable
private fun ReaderChapterQueuePanel(
    request: ChimahonReaderRequest,
    previousChapter: ChimahonReaderChapterRef?,
    nextChapter: ChimahonReaderChapterRef?,
    onOpenChapter: (ChimahonReaderChapterRef) -> Unit,
    onBookmarkChapter: (ChimahonReaderChapterRef) -> Unit,
    onDownloadChapter: (ChimahonReaderChapterRef) -> Unit,
    onMarkChapterRead: (ChimahonReaderChapterRef) -> Unit,
    modifier: Modifier = Modifier,
) {
    var query by remember(request.chapterQueue) { mutableStateOf("") }
    val visibleChapters = request.chapterQueue.filter { chapter ->
        query.isBlank() ||
            chapter.chapterName.contains(query, ignoreCase = true) ||
            chapter.scanlator.orEmpty().contains(query, ignoreCase = true)
    }
    val readCount = request.chapterQueue.count { it.read }
    val startedCount = request.chapterQueue.count { !it.read && it.lastPageRead > 0L }
    val bookmarkedCount = request.chapterQueue.count { it.bookmarked }
    val chapterListState = rememberLazyListState()
    val selectedIndex = visibleChapters.indexOfFirst { chapter ->
        chapter.chapterUrl == request.chapterUrl && chapter.chapterId == request.chapterId
    }
    LaunchedEffect(request.chapterUrl, request.chapterId, query, visibleChapters.size) {
        if (selectedIndex >= 0) {
            chapterListState.scrollToItem(selectedIndex.coerceAtLeast(0))
        }
    }
    Column(
        modifier = modifier
            .clip(RoundedCornerShape(18.dp))
            .background(ReaderPalette.chrome.copy(alpha = 0.98f))
            .border(1.dp, ReaderPalette.divider.copy(alpha = 0.82f), RoundedCornerShape(18.dp))
            .padding(horizontal = 12.dp, vertical = 10.dp),
    ) {
        ReaderSheetDragHandle()
        ReaderSheetHeader(
            title = "Chapters",
            subtitle = if (request.chapterQueue.isEmpty()) {
                "No chapter queue from source"
            } else {
                "${(request.chapterIndex + 1).coerceAtLeast(1)} of ${request.chapterQueue.size} - ${request.readerChapterMarker()}"
            },
            icon = UiIcon.Chapters,
        )
        ReaderChapterJumpTargets(
            previousChapter = previousChapter,
            nextChapter = nextChapter,
            onOpenChapter = onOpenChapter,
            modifier = Modifier
                .fillMaxWidth()
                .padding(vertical = 8.dp),
        )
        if (request.chapterQueue.isNotEmpty()) {
            ReaderChapterQueueStateRow(
                totalCount = request.chapterQueue.size,
                visibleCount = visibleChapters.size,
                queryActive = query.isNotBlank(),
                readCount = readCount,
                startedCount = startedCount,
                bookmarkedCount = bookmarkedCount,
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(bottom = 6.dp),
            )
        }
        if (request.chapterQueue.size > 8) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(42.dp)
                    .padding(vertical = 4.dp)
                    .clip(RoundedCornerShape(21.dp))
                    .background(ReaderPalette.control.copy(alpha = 0.72f))
                    .padding(horizontal = 12.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                IconGlyph(
                    icon = UiIcon.Search,
                    contentDescription = "Search chapters",
                    tint = ReaderPalette.secondaryText,
                    modifier = Modifier.size(17.dp),
                )
                Box(modifier = Modifier.weight(1f)) {
                    if (query.isBlank()) {
                        Label(
                            "Search chapters",
                            ReaderPalette.secondaryText,
                            11,
                            maxLines = 1,
                            modifier = Modifier.align(Alignment.CenterStart),
                        )
                    }
                    BasicTextField(
                        value = query,
                        onValueChange = { query = it },
                        singleLine = true,
                        textStyle = TextStyle(
                            color = Color.White,
                            fontSize = 12.sp,
                            lineHeight = 16.sp,
                        ),
                        modifier = Modifier
                            .fillMaxWidth()
                            .semantics {
                                contentDescription = "Search chapter queue"
                            },
                    )
                }
            }
        }
        if (request.chapterQueue.isEmpty()) {
            Label(
                "This source did not provide a chapter queue.",
                ReaderPalette.secondaryText,
                11,
                modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp),
            )
        } else {
            LazyColumn(
                state = chapterListState,
                modifier = Modifier
                    .fillMaxWidth()
                    .heightIn(max = 330.dp)
                    .padding(top = 8.dp),
                contentPadding = PaddingValues(vertical = 2.dp),
                verticalArrangement = Arrangement.spacedBy(3.dp),
            ) {
                items(
                    visibleChapters.withIndex().toList(),
                    key = { indexed -> readerChapterRefLazyKey(indexed.index, indexed.value) },
                ) { indexed ->
                    val chapter = indexed.value
                    val selected = chapter.chapterUrl == request.chapterUrl &&
                        chapter.chapterId == request.chapterId
                    val queueIndex = request.chapterQueue.indexOf(chapter).takeIf { it >= 0 }
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(RoundedCornerShape(6.dp))
                            .background(
                                when {
                                    selected -> ReaderPalette.selectedControl.copy(alpha = 0.88f)
                                    chapter.read -> ReaderPalette.control.copy(alpha = 0.46f)
                                    else -> Color.Transparent
                                },
                            )
                            .semantics {
                                contentDescription = chapter.readerQueueContentDescription(
                                    selected = selected,
                                    position = queueIndex?.plus(1),
                                    total = request.chapterQueue.size,
                                )
                                this.selected = selected
                                stateDescription = chapter.readerQueueStateDescription(selected)
                            }
                            .clickable(role = Role.Button) { onOpenChapter(chapter) }
                            .padding(horizontal = 8.dp, vertical = 8.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Box(
                            modifier = Modifier
                                .width(3.dp)
                                .height(38.dp)
                                .clip(RoundedCornerShape(2.dp))
                                .background(
                                    when {
                                        selected -> Color.White.copy(alpha = 0.90f)
                                        !chapter.read -> ReaderPalette.selectedControl
                                        else -> Color.Transparent
                                    },
                                ),
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        ReaderChapterMarkerChip(
                            text = chapter.readerChapterMarker(),
                            selected = selected,
                            read = chapter.read,
                        )
                        Column(
                            modifier = Modifier
                                .weight(1f)
                                .padding(start = 10.dp),
                        ) {
                            Row(
                                horizontalArrangement = Arrangement.spacedBy(6.dp),
                                verticalAlignment = Alignment.CenterVertically,
                            ) {
                                if (chapter.bookmarked) {
                                    IconGlyph(
                                        icon = UiIcon.Bookmark,
                                        contentDescription = "Bookmarked",
                                        tint = if (selected) Color.White else ReaderPalette.secondaryText,
                                        modifier = Modifier.size(14.dp),
                                    )
                                }
                                if (!chapter.read && chapter.lastPageRead <= 0L) {
                                    Box(
                                        modifier = Modifier
                                            .size(7.dp)
                                            .clip(CircleShape)
                                            .background(if (selected) Color.White else ReaderPalette.selectedControl),
                                    )
                                }
                                Label(
                                    chapter.chapterName,
                                    if (selected) Color.White else ReaderPalette.secondaryText,
                                    11,
                                    weight = if (selected) FontWeight.SemiBold else FontWeight.Normal,
                                    maxLines = 1,
                                    modifier = Modifier.weight(1f),
                                )
                            }
                            Label(
                                listOfNotNull(
                                    chapter.readerQueueStateLabel(),
                                    chapter.scanlator?.takeIf { it.isNotBlank() },
                                ).joinToString(" - "),
                                ReaderPalette.secondaryText,
                                9,
                                maxLines = 1,
                                modifier = Modifier.padding(top = 3.dp),
                            )
                        }
                        if (selected) {
                            Label(
                                "Current",
                                Color.White,
                                9,
                                weight = FontWeight.SemiBold,
                                maxLines = 1,
                                modifier = Modifier
                                    .clip(RoundedCornerShape(50))
                                    .background(Color.White.copy(alpha = 0.16f))
                                    .padding(horizontal = 8.dp, vertical = 4.dp),
                            )
                        }
                        if (chapter.chapterId != null) {
                            ReaderChapterRowAction(
                                icon = if (chapter.read) UiIcon.Circle else UiIcon.DoneAll,
                                contentDescription = if (chapter.read) "Mark unread" else "Mark read",
                                active = chapter.read,
                                onClick = { onMarkChapterRead(chapter) },
                            )
                            ReaderChapterRowAction(
                                icon = if (chapter.bookmarked) UiIcon.Bookmark else UiIcon.BookmarkBorder,
                                contentDescription = if (chapter.bookmarked) {
                                    "Unbookmark chapter"
                                } else {
                                    "Bookmark chapter"
                                },
                                active = chapter.bookmarked,
                                onClick = { onBookmarkChapter(chapter) },
                            )
                            ReaderChapterRowAction(
                                icon = UiIcon.Download,
                                contentDescription = "Download chapter",
                                onClick = { onDownloadChapter(chapter) },
                            )
                        }
                    }
                }
            }
            if (visibleChapters.isEmpty()) {
                ReaderInlineEmpty(
                    icon = UiIcon.Search,
                    title = "No matching chapters",
                    detail = "Try a different chapter title or scanlator.",
                    modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp),
                )
            }
        }
    }
}

@Composable
private fun ReaderChapterQueueStateRow(
    totalCount: Int,
    visibleCount: Int,
    queryActive: Boolean,
    readCount: Int,
    startedCount: Int,
    bookmarkedCount: Int,
    modifier: Modifier = Modifier,
) {
    val unreadCount = (totalCount - readCount).coerceAtLeast(0)
    LazyRow(
        modifier = modifier,
        horizontalArrangement = Arrangement.spacedBy(6.dp),
    ) {
        item("all") {
            ReaderChapterStateChip("All", totalCount)
        }
        if (queryActive) {
            item("visible") {
                ReaderChapterStateChip("Shown", visibleCount)
            }
        }
        item("unread") {
            ReaderChapterStateChip("Unread", unreadCount)
        }
        item("started") {
            ReaderChapterStateChip("Started", startedCount)
        }
        item("read") {
            ReaderChapterStateChip("Read", readCount)
        }
        item("bookmarked") {
            ReaderChapterStateChip("Saved", bookmarkedCount)
        }
    }
}

