        ReaderDesktopActionChip(
            icon = UiIcon.Web,
            contentDescription = if (hasPageUrl) "Open page URL" else "Page URL unavailable",
            canvas = canvas,
            enabled = hasPageUrl && !busy,
            onClick = onOpenPageUrl,
        )
        ReaderDesktopActionChip(
            icon = UiIcon.More,
            contentDescription = "Page actions",
            canvas = canvas,
            enabled = !busy,
            onClick = onOpenActions,
        )
    }
}

@Composable
private fun ReaderSplitWidePageImage(
    bitmap: ImageBitmap,
    contentDescription: String,
    rtl: Boolean,
    colorFilter: ColorFilter?,
    modifier: Modifier = Modifier,
) {
    Canvas(
        modifier = modifier.semantics {
            this.contentDescription = contentDescription
        },
    ) {
        val halfWidth = (bitmap.width / 2).coerceAtLeast(1)
        val leftHalf = 0 to halfWidth
        val rightHalf = halfWidth to (bitmap.width - halfWidth).coerceAtLeast(1)
        val halves = if (rtl) listOf(rightHalf, leftHalf) else listOf(leftHalf, rightHalf)
        val gutter = min(size.width * 0.018f, 16f)
        val panelWidth = ((size.width - gutter) / 2f).coerceAtLeast(1f)

        halves.forEachIndexed { index, (srcX, srcWidth) ->
            val fitScale = min(
                panelWidth / srcWidth.toFloat(),
                size.height / bitmap.height.coerceAtLeast(1).toFloat(),
            )
            val dstWidth = (srcWidth * fitScale).coerceAtLeast(1f)
            val dstHeight = (bitmap.height * fitScale).coerceAtLeast(1f)
            val panelStart = index * (panelWidth + gutter)
            val dstX = panelStart + ((panelWidth - dstWidth) / 2f)
            val dstY = (size.height - dstHeight) / 2f
            drawImage(
                image = bitmap,
                srcOffset = IntOffset(srcX, 0),
                srcSize = IntSize(srcWidth, bitmap.height),
                dstOffset = IntOffset(dstX.roundToInt(), dstY.roundToInt()),
                dstSize = IntSize(dstWidth.roundToInt(), dstHeight.roundToInt()),
                colorFilter = colorFilter,
            )
        }
        drawRect(
            color = Color.Black.copy(alpha = 0.20f),
            topLeft = Offset((size.width - gutter) / 2f, 0f),
            size = Size(gutter, size.height),
        )
    }
}

@Composable
private fun ReaderRotatedWidePageImage(
    bitmap: ImageBitmap,
    contentDescription: String,
    clockwise: Boolean,
    colorFilter: ColorFilter?,
    modifier: Modifier = Modifier,
) {
    Canvas(
        modifier = modifier.semantics {
            this.contentDescription = contentDescription
        },
    ) {
        val fitScale = min(
            size.width / bitmap.height.coerceAtLeast(1).toFloat(),
            size.height / bitmap.width.coerceAtLeast(1).toFloat(),
        )
        val dstWidth = (bitmap.width * fitScale).coerceAtLeast(1f)
        val dstHeight = (bitmap.height * fitScale).coerceAtLeast(1f)
        val dstX = (size.width - dstWidth) / 2f
        val dstY = (size.height - dstHeight) / 2f

        rotate(
            degrees = if (clockwise) 90f else -90f,
            pivot = Offset(size.width / 2f, size.height / 2f),
        ) {
            drawImage(
                image = bitmap,
                dstOffset = IntOffset(dstX.roundToInt(), dstY.roundToInt()),
                dstSize = IntSize(dstWidth.roundToInt(), dstHeight.roundToInt()),
                colorFilter = colorFilter,
            )
        }
    }
}

private fun ChimahonReaderSettings.readerColorFilter(): ColorFilter? {
    return when {
        invertColors -> ColorFilter.colorMatrix(
            ColorMatrix(
                floatArrayOf(
                    -1f, 0f, 0f, 0f, 255f,
                    0f, -1f, 0f, 0f, 255f,
                    0f, 0f, -1f, 0f, 255f,
                    0f, 0f, 0f, 1f, 0f,
                ),
            ),
        )
        grayscale -> ColorFilter.colorMatrix(ColorMatrix().apply { setToSaturation(0f) })
        else -> null
    }
}

private fun ChimahonReaderSettings.readerBrightnessOverlay(): Color? {
    val brightnessValue = when {
        customBrightnessEnabled -> customBrightnessValue
        colorFilterEnabled && brightness != 0 -> brightness
        else -> 0
    }
    if (brightnessValue == 0) return null
    val alpha = (kotlin.math.abs(brightnessValue).coerceAtMost(100) / 100f) *
        if (brightnessValue < 0) 0.75f else 0.42f
    return if (brightnessValue > 0) {
        Color.White.copy(alpha = alpha)
    } else {
        Color.Black.copy(alpha = alpha)
    }
}

private fun ChimahonReaderColorFilterMode.toBlendMode(): BlendMode = when (this) {
    ChimahonReaderColorFilterMode.Default -> BlendMode.SrcOver
    ChimahonReaderColorFilterMode.Multiply -> BlendMode.Modulate
    ChimahonReaderColorFilterMode.Screen -> BlendMode.Screen
    ChimahonReaderColorFilterMode.Overlay -> BlendMode.Overlay
    ChimahonReaderColorFilterMode.Lighten -> BlendMode.Lighten
    ChimahonReaderColorFilterMode.Darken -> BlendMode.Darken
}

