@Composable
private fun ChapterFilterPanel(
    selectedFilter: ChapterFilter,
    selectedSort: ChapterSort,
    selectedDisplayMode: ChapterDisplayMode,
    descending: Boolean,
    summary: ChapterListSummary,
    query: String,
    onQueryChange: (String) -> Unit,
    onFilterChange: (ChapterFilter) -> Unit,
    onSortChange: (ChapterSort) -> Unit,
    onDisplayModeChange: (ChapterDisplayMode) -> Unit,
    onSortDirectionChange: (Boolean) -> Unit,
    onClearFilters: () -> Unit,
) {
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .background(ChimahonPalette.surface)
            .border(1.dp, ChimahonPalette.divider.copy(alpha = 0.45f))
            .padding(start = 12.dp, end = 12.dp, bottom = 10.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        Box(
            modifier = Modifier
                .padding(top = 6.dp, bottom = 8.dp)
                .width(38.dp)
                .height(4.dp)
                .clip(CircleShape)
                .background(ChimahonPalette.divider),
        )
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(bottom = 6.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Column(modifier = Modifier.weight(1f)) {
                Label("Chapter filters", ChimahonPalette.onSurface, 14, weight = FontWeight.SemiBold, maxLines = 1)
                Label(
                    "${summary.readCount} read - ${summary.unreadCount} unread - ${summary.downloadedCount} downloaded",
                    ChimahonPalette.secondaryText,
                    11,
                    maxLines = 1,
                )
            }
            if (selectedFilter != ChapterFilter.All || selectedSort != ChapterSort.SourceOrder || descending || query.isNotBlank()) {
                TextButtonLike("Reset", onClick = onClearFilters)
            }
        }
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(42.dp)
                .clip(RoundedCornerShape(8.dp))
                .background(ChimahonPalette.background)
                .border(1.dp, ChimahonPalette.divider, RoundedCornerShape(8.dp))
                .padding(horizontal = 12.dp),
            contentAlignment = Alignment.CenterStart,
        ) {
            IconGlyph(
                icon = UiIcon.Search,
                contentDescription = "Search chapters",
                tint = ChimahonPalette.secondaryText,
                modifier = Modifier.size(17.dp),
            )
            if (query.isBlank()) {
                Label(
                    "Search chapters",
                    ChimahonPalette.secondaryText,
                    12,
                    maxLines = 1,
                    modifier = Modifier.padding(start = 26.dp),
                )
            }
            BasicTextField(
                value = query,
                onValueChange = onQueryChange,
                singleLine = true,
                textStyle = TextStyle(
                    color = ChimahonPalette.onSurface,
                    fontSize = 13.sp,
                    lineHeight = 17.sp,
                ),
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(start = 26.dp),
            )
        }
        FilterPanelLabel(
            "Show  -  ${summary.startedCount} started, ${summary.bookmarkedCount} bookmarked",
            modifier = Modifier
                .fillMaxWidth()
                .padding(top = 10.dp, bottom = 4.dp),
        )
        ScrollableFilterChips(
            chips = ChapterFilter.entries.map { it.title },
            selected = selectedFilter.title,
            onSelect = { title ->
                ChapterFilter.entries.firstOrNull { it.title == title }?.let(onFilterChange)
            },
            modifier = Modifier.padding(vertical = 2.dp),
        )
        FilterPanelLabel(
            "Sort by  -  ${summary.scanlatorCount} scanlator group(s)",
            modifier = Modifier
                .fillMaxWidth()
                .padding(top = 10.dp, bottom = 4.dp),
        )
        ScrollableFilterChips(
            chips = ChapterSort.entries.map { it.title },
            selected = selectedSort.title,
            onSelect = { title ->
                ChapterSort.entries.firstOrNull { it.title == title }?.let(onSortChange)
            },
            modifier = Modifier.padding(vertical = 2.dp),
        )
        FilterPanelLabel(
            "Display",
            modifier = Modifier
                .fillMaxWidth()
                .padding(top = 10.dp, bottom = 4.dp),
        )
        SegmentTabs(
            values = ChapterDisplayMode.entries.toList(),
            selected = selectedDisplayMode,
            label = { it.title },
            onSelect = onDisplayModeChange,
        )
        FilterPanelLabel(
            "Direction",
            modifier = Modifier
                .fillMaxWidth()
                .padding(top = 10.dp, bottom = 4.dp),
        )
        SegmentTabs(
            values = listOf(true, false),
            selected = descending,
            label = { if (it) "Descending" else "Ascending" },
            onSelect = onSortDirectionChange,
        )
    }
}

@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun MangaChapterListItem(
    chapter: ChimahonChapterEntry,
    displayMode: ChapterDisplayMode,
    selected: Boolean,
    selectionActive: Boolean,
    onToggleSelected: () -> Unit,
    onClick: () -> Unit,
    onSetRead: suspend (Boolean) -> Unit,
    onSetBookmark: suspend (Boolean) -> Unit,
    onEnqueueDownload: suspend () -> ChimahonDownloadQueueData,
    downloadStatus: ChimahonChapterDownloadStatus? = null,
) {
    var busyAction by remember(chapter.id) { mutableStateOf<String?>(null) }
    var actionsVisible by remember(chapter.id) { mutableStateOf(false) }
    val scope = rememberCoroutineScope()
    val downloadState = downloadStatus?.status
    val isDownloaded = downloadState == ChimahonDownloadState.Downloaded
    val titleColor = when {
        selected -> ChimahonPalette.onPrimaryContainer
        chapter.read -> ChimahonPalette.secondaryText
        else -> ChimahonPalette.onSurface
    }
    val title = chapter.chapterDisplayTitle(displayMode)
    val metadata = chapter.chapterDetailMetadata(
        downloadStatus = downloadStatus,
        showChapterNumber = displayMode == ChapterDisplayMode.SourceTitle,
        sourceTitle = chapter.name.takeIf {
            displayMode == ChapterDisplayMode.ChapterNumber && it.isNotBlank() && it != title
        },
    )
    val statePills = listOfNotNull(
        "Read".takeIf { chapter.read },
        "Unread".takeIf { !chapter.read && chapter.lastPageRead <= 0L },
        "Page ${chapter.lastPageRead + 1}".takeIf { chapter.lastPageRead > 0L && !chapter.read },
        downloadStatus?.chapterListBadgeLabel(),
        "Bookmarked".takeIf { chapter.bookmarked },
    ).distinct()
    val markerActive = !chapter.read || chapter.lastPageRead > 0L || chapter.bookmarked || downloadStatus != null
    val stripeColor = when {
        selected -> ChimahonPalette.primary
        chapter.bookmarked -> ChimahonPalette.primary
        chapter.lastPageRead > 0L && !chapter.read -> ChimahonPalette.primary.copy(alpha = 0.82f)
        isDownloaded -> ChimahonPalette.primary.copy(alpha = 0.64f)
        !chapter.read -> ChimahonPalette.primary.copy(alpha = 0.44f)
        else -> Color.Transparent
    }
    val startAction: () -> Unit = {
        actionsVisible = false
        onClick()
    }
    val toggleRead: () -> Unit = {
        if (busyAction == null) {
            scope.launch {
                busyAction = "read"
                runCatching { onSetRead(!chapter.read) }
                busyAction = null
                actionsVisible = false
            }
        }
    }
    val toggleBookmark: () -> Unit = {
        if (busyAction == null) {
            scope.launch {
                busyAction = "bookmark"
                runCatching { onSetBookmark(!chapter.bookmarked) }
                busyAction = null
                actionsVisible = false
            }
        }
    }
    val enqueueDownload: () -> Unit = {
        if (busyAction == null && !isDownloaded) {
            scope.launch {
                busyAction = "download"
                runCatching { onEnqueueDownload() }
                busyAction = null
                actionsVisible = false
            }
        }
    }
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .background(if (selected) ChimahonPalette.primaryContainer.copy(alpha = 0.68f) else ChimahonPalette.surface)
            .combinedClickable(
                onClick = onClick,
                onLongClick = onToggleSelected,
            )
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .heightIn(min = 56.dp)
                .padding(start = 0.dp, top = 6.dp, end = 6.dp, bottom = 6.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Box(
                modifier = Modifier
                    .width(3.dp)
                    .height(42.dp)
                    .clip(RoundedCornerShape(topEnd = 4.dp, bottomEnd = 4.dp))
                    .background(stripeColor),
            )
            if (selectionActive || selected) {
                Box(
                    modifier = Modifier
                        .padding(start = 11.dp)
                        .size(32.dp)
                        .clip(CircleShape)
                        .background(if (selected) ChimahonPalette.primary else ChimahonPalette.surfaceVariant),
                    contentAlignment = Alignment.Center,
                ) {
                    IconGlyph(
                        icon = if (selected) UiIcon.CheckCircle else UiIcon.Circle,
                        contentDescription = if (selected) "Selected" else "Not selected",
                        tint = if (selected) Color.White else ChimahonPalette.secondaryText,
                        modifier = Modifier.size(19.dp),
                    )
                }
            } else {
                ChapterMarkerBadge(
                    text = chapter.chapterMarker(),
                    active = markerActive,
                    modifier = Modifier.padding(start = 11.dp),
                )
            }
            Column(
                modifier = Modifier
                    .weight(1f)
                    .padding(start = 11.dp),
                verticalArrangement = Arrangement.spacedBy(4.dp),
            ) {
                Row(
                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Label(
                        title,
                        titleColor,
                        13,
                        weight = if (chapter.read) FontWeight.Normal else FontWeight.SemiBold,
                        maxLines = 1,
                        modifier = Modifier.weight(1f),
                    )
                    if (chapter.bookmarked) {
                        IconGlyph(
                            icon = UiIcon.Bookmark,
                            contentDescription = "Bookmarked",
                            tint = ChimahonPalette.primary,
                            modifier = Modifier.size(15.dp),
                        )
                    }
                }
                Row(
                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Label(
                        text = metadata,
                        color = if (selected) {
                            ChimahonPalette.onPrimaryContainer
                        } else {
                            ChimahonPalette.secondaryText.copy(alpha = if (chapter.read) 0.62f else 1f)
                        },
                        size = 11,
                        maxLines = 1,
                        modifier = Modifier.weight(1f),
                    )
                }
                if (statePills.isNotEmpty()) {
                    Row(
                        horizontalArrangement = Arrangement.spacedBy(5.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        statePills.take(3).forEach { pill ->
                            MangaChapterStatePill(pill, selected = selected)
                        }
                    }
                }
            }
            ChapterQuickAction(
                icon = downloadState?.statusIcon() ?: UiIcon.Download,
                contentDescription = downloadState?.queueTitle() ?: "Download chapter",
                active = busyAction == "download" || downloadState != null,
                onClick = enqueueDownload,
            )
            ChapterQuickAction(
                icon = UiIcon.More,
                contentDescription = "Chapter actions",
                active = actionsVisible || busyAction != null,
                onClick = { actionsVisible = true },
            )
        }
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(1.dp)
                .padding(start = if (selectionActive || selected) 58.dp else 61.dp)
                .background(ChimahonPalette.divider.copy(alpha = if (selected) 0.38f else 0.68f)),
        )
    }
    if (actionsVisible) {
        MangaChapterActionsDialog(
            chapter = chapter,
            downloadStatus = downloadStatus,
            busyAction = busyAction,
            selected = selected,
            onDismiss = { actionsVisible = false },
            onOpen = startAction,
            onToggleSelected = {
                onToggleSelected()
                actionsVisible = false
            },
            onToggleRead = toggleRead,
            onToggleBookmark = toggleBookmark,
            onDownload = enqueueDownload,
        )
    }
}

@Composable
private fun ChapterMarkerBadge(
    text: String,
    active: Boolean,
    modifier: Modifier = Modifier,
) {
    Box(
        modifier = modifier
            .size(36.dp)
            .clip(RoundedCornerShape(10.dp))
            .background(if (active) ChimahonPalette.primaryContainer.copy(alpha = 0.86f) else ChimahonPalette.surfaceVariant),
        contentAlignment = Alignment.Center,
    ) {
        Label(
            text,
            if (active) ChimahonPalette.primary else ChimahonPalette.secondaryText,
            11,
            weight = FontWeight.Bold,
            maxLines = 1,
        )
    }
}

@Composable
private fun MangaChapterStatePill(text: String, selected: Boolean) {
    val active = text != "Read"
    Box(
        modifier = Modifier
            .clip(RoundedCornerShape(10.dp))
            .background(
                when {
                    selected -> ChimahonPalette.surface.copy(alpha = 0.72f)
                    active -> ChimahonPalette.primaryContainer.copy(alpha = 0.84f)
                    else -> ChimahonPalette.surfaceVariant
                },
            )
            .border(
                1.dp,
                if (active) ChimahonPalette.primary.copy(alpha = 0.18f) else ChimahonPalette.divider.copy(alpha = 0.32f),
                RoundedCornerShape(10.dp),
            )
            .padding(horizontal = 7.dp, vertical = 2.dp),
    ) {
        Label(
            text,
            if (active || selected) ChimahonPalette.primary else ChimahonPalette.secondaryText,
            9,
            weight = FontWeight.SemiBold,
            maxLines = 1,
        )
    }
}

@Composable
private fun MangaChapterActionsDialog(
    chapter: ChimahonChapterEntry,
    downloadStatus: ChimahonChapterDownloadStatus?,
    busyAction: String?,
    selected: Boolean,
    onDismiss: () -> Unit,
    onOpen: () -> Unit,
    onToggleSelected: () -> Unit,
    onToggleRead: () -> Unit,
    onToggleBookmark: () -> Unit,
    onDownload: () -> Unit,
) {
    Dialog(onDismissRequest = onDismiss) {
        val sheetShape = RoundedCornerShape(
            topStart = 24.dp,
            topEnd = 24.dp,
            bottomStart = 0.dp,
            bottomEnd = 0.dp,
        )
        Box(
            modifier = Modifier
                .fillMaxSize()
                .padding(top = 48.dp),
            contentAlignment = Alignment.BottomCenter,
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .widthIn(max = 520.dp)
                    .clip(sheetShape)
                    .background(ChimahonPalette.surface)
                    .border(1.dp, ChimahonPalette.divider, sheetShape),
                horizontalAlignment = Alignment.CenterHorizontally,
            ) {
                Box(
                    modifier = Modifier
                        .padding(top = 8.dp)
                        .width(38.dp)
                        .height(4.dp)
                        .clip(CircleShape)
                        .background(ChimahonPalette.divider),
                )
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(start = 18.dp, top = 16.dp, end = 10.dp, bottom = 14.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(12.dp),
                ) {
                    Box(
                        modifier = Modifier
                            .size(40.dp)
                            .clip(RoundedCornerShape(10.dp))
                            .background(ChimahonPalette.primaryContainer),
                        contentAlignment = Alignment.Center,
                    ) {
                        Label(chapter.chapterMarker(), ChimahonPalette.primary, 12, weight = FontWeight.Bold)
                    }
                    Column(modifier = Modifier.weight(1f)) {
                        Label("Chapter actions", ChimahonPalette.secondaryText, 10, weight = FontWeight.Bold, maxLines = 1)
                        Label(chapter.name, ChimahonPalette.onSurface, 14, weight = FontWeight.SemiBold, maxLines = 2)
                        Label(
                            chapter.chapterDetailMetadata(downloadStatus),
                            ChimahonPalette.secondaryText,
                            11,
                            maxLines = 2,
                            modifier = Modifier.padding(top = 3.dp),
                        )
                    }
                    Box(
                        modifier = Modifier
                            .size(38.dp)
                            .clip(CircleShape)
                            .clickable(onClick = onDismiss),
                        contentAlignment = Alignment.Center,
                    ) {
                        IconGlyph(
                            icon = UiIcon.Close,
                            contentDescription = "Close chapter actions",
                            tint = ChimahonPalette.secondaryText,
                            modifier = Modifier.size(19.dp),
                        )
                    }
                }
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(1.dp)
                        .background(ChimahonPalette.divider),
                )
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(12.dp),
                    verticalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    MangaChapterDialogAction(
                        title = if (chapter.lastPageRead > 0L && !chapter.read) "Resume chapter" else "Open chapter",
                        icon = UiIcon.Play,
                        enabled = busyAction == null,
                        onClick = onOpen,
                    )
                    MangaChapterDialogAction(
                        title = if (chapter.read) "Mark unread" else "Mark read",
                        icon = if (chapter.read) UiIcon.Circle else UiIcon.DoneAll,
                        active = busyAction == "read",
                        enabled = busyAction == null,
                        onClick = onToggleRead,
                    )
                    MangaChapterDialogAction(
                        title = if (chapter.bookmarked) "Remove bookmark" else "Bookmark",
                        icon = if (chapter.bookmarked) UiIcon.Bookmark else UiIcon.BookmarkBorder,
                        active = chapter.bookmarked || busyAction == "bookmark",
                        enabled = busyAction == null,
                        onClick = onToggleBookmark,
                    )
                    MangaChapterDialogAction(
                        title = downloadStatus?.chapterDownloadStatusLabel() ?: "Download chapter",
                        icon = downloadStatus?.status?.statusIcon() ?: UiIcon.Download,
                        active = busyAction == "download" || downloadStatus?.status == ChimahonDownloadState.Downloaded,
                        enabled = busyAction == null && downloadStatus?.status != ChimahonDownloadState.Downloaded,
                        onClick = onDownload,
                    )
                    MangaChapterDialogAction(
                        title = if (selected) "Deselect chapter" else "Select chapter",
                        icon = if (selected) UiIcon.CheckCircle else UiIcon.Circle,
                        active = selected,
                        enabled = busyAction == null,
                        onClick = onToggleSelected,
                    )
                }
            }
        }
    }
}

@Composable
private fun MangaChapterDialogAction(
    title: String,
    icon: UiIcon,
    enabled: Boolean,
    active: Boolean = false,
    onClick: () -> Unit,
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .height(48.dp)
            .clip(RoundedCornerShape(8.dp))
            .background(if (active) ChimahonPalette.primaryContainer else Color.Transparent)
            .clickable(enabled = enabled, onClick = onClick)
            .padding(horizontal = 12.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(10.dp),
    ) {
        IconGlyph(
            icon = icon,
            contentDescription = title,
            tint = when {
                active -> ChimahonPalette.primary
                enabled -> ChimahonPalette.onSurface
                else -> ChimahonPalette.secondaryText.copy(alpha = 0.45f)
            },
            modifier = Modifier.size(19.dp),
        )
        Label(
            title,
            when {
                active -> ChimahonPalette.primary
                enabled -> ChimahonPalette.onSurface
                else -> ChimahonPalette.secondaryText.copy(alpha = 0.45f)
            },
            12,
            weight = FontWeight.SemiBold,
            maxLines = 1,
            modifier = Modifier.weight(1f),
        )
    }
}

@Composable
private fun ChapterQuickAction(
    icon: UiIcon,
    contentDescription: String,
    active: Boolean,
    onClick: () -> Unit,
) {
    Box(
        modifier = Modifier
            .size(38.dp)
            .clip(CircleShape)
            .clickable(onClick = onClick),
        contentAlignment = Alignment.Center,
    ) {
        IconGlyph(
            icon = icon,
            contentDescription = contentDescription,
            tint = if (active) ChimahonPalette.primary else ChimahonPalette.secondaryText,
            modifier = Modifier.size(21.dp),
        )
    }
}

@Composable
private fun MoreHome(
    snapshot: ChimahonSnapshot,
    onSelectTab: (HomeTab) -> Unit,
    onCreateCategory: suspend (String) -> Long,
    onDeleteCategory: suspend (Long) -> Unit,
    onRenameCategory: suspend (Long, String) -> Unit,
    onSetCategoryHidden: suspend (Long, Boolean) -> Unit,
    onMoveCategory: suspend (Long, Int) -> Unit,
    onCategoriesChanged: () -> Unit,
    onLoadDataMaintenance: suspend () -> ChimahonDataMaintenanceSnapshot,
    onClearThumbnailCache: suspend () -> ChimahonCacheClearResult,
    onClearCacheData: suspend () -> ChimahonCacheClearResult,
    onRunDatabaseMaintenance: suspend () -> ChimahonDatabaseMaintenanceResult,
    onLoadDownloadQueue: suspend () -> ChimahonDownloadQueueData,
    onPauseDownloadQueue: suspend () -> ChimahonDownloadQueueData,
    onResumeDownloadQueue: suspend () -> ChimahonDownloadQueueData,
    onProcessNextDownload: suspend () -> ChimahonDownloadQueueData,
    onPauseDownload: suspend (Long) -> ChimahonDownloadQueueData,
    onResumeDownload: suspend (Long) -> ChimahonDownloadQueueData,
    onRetryDownload: suspend (Long) -> ChimahonDownloadQueueData,
    onRemoveDownload: suspend (Long) -> ChimahonDownloadQueueData,
    onClearCompletedDownloads: suspend () -> ChimahonDownloadQueueData,
    onMoveDownloadToTop: suspend (Long) -> ChimahonDownloadQueueData,
    onMoveDownloadToBottom: suspend (Long) -> ChimahonDownloadQueueData,
    downloadedOnlyMode: Boolean,
    incognitoMode: Boolean,
    settings: ChimahonSettings,
    onAppearanceSettingsChange: (ChimahonAppearanceSettings) -> Unit,
    onLibrarySettingsChange: (ChimahonLibrarySettings) -> Unit,
    onAnimeLibrarySettingsChange: (ChimahonAnimeLibrarySettings) -> Unit,
    onReaderSettingsChange: (ChimahonReaderSettings) -> Unit,
    onDownloadPreferencesChange: (ChimahonDownloadPreferences) -> Unit,
    onBrowseSettingsChange: (ChimahonBrowseSettings) -> Unit,
    onNavigationSettingsChange: (ChimahonNavigationSettings) -> Unit,
    onPlayerSettingsChange: (ChimahonPlayerSettings) -> Unit,
    onTrackingSettingsChange: (ChimahonTrackingSettings) -> Unit,
    onConnectionSettingsChange: (ChimahonConnectionSettings) -> Unit,
    onDictionarySettingsChange: (ChimahonDictionarySettings) -> Unit,
    onSecuritySettingsChange: (ChimahonSecuritySettings) -> Unit,
    onOpenExternalUrl: (String) -> Boolean,
    onDownloadedOnlyModeChange: (Boolean) -> Unit,
    onIncognitoModeChange: (Boolean) -> Unit,
    requestedPage: MorePage?,
    onRequestedPageConsumed: () -> Unit,
    backRequestId: Long?,
    onOpenBrowseSection: (BrowseSection) -> Unit,
) {
    var pageStack by remember { mutableStateOf(listOf(MorePage.Main)) }
    val selectedPage = pageStack.last()
    var moreDownloadQueue by remember { mutableStateOf<ChimahonDownloadQueueData?>(null) }
    val openPage: (MorePage) -> Unit = { page ->
        if (page != selectedPage) pageStack = pageStack + page
    }
    LaunchedEffect(requestedPage) {
        requestedPage?.let { page ->
            pageStack = if (page == MorePage.Main) {
                listOf(MorePage.Main)
            } else {
                listOf(MorePage.Main, page)
            }
            onRequestedPageConsumed()
        }
    }
    LaunchedEffect(backRequestId) {
        backRequestId ?: return@LaunchedEffect
        pageStack = if (pageStack.size > 1) pageStack.dropLast(1) else listOf(MorePage.Main)
    }
    LaunchedEffect(selectedPage) {
        if (selectedPage == MorePage.Main) {
            moreDownloadQueue = runCatching { onLoadDownloadQueue() }.getOrNull()
        }
    }
    if (selectedPage != MorePage.Main) {
        MoreDetailPage(
            page = selectedPage,
            snapshot = snapshot,
            onCreateCategory = onCreateCategory,
            onDeleteCategory = onDeleteCategory,
            onRenameCategory = onRenameCategory,
            onSetCategoryHidden = onSetCategoryHidden,
            onMoveCategory = onMoveCategory,
            onCategoriesChanged = onCategoriesChanged,
            onLoadDataMaintenance = onLoadDataMaintenance,
            onClearThumbnailCache = onClearThumbnailCache,
            onClearCacheData = onClearCacheData,
            onRunDatabaseMaintenance = onRunDatabaseMaintenance,
            onLoadDownloadQueue = onLoadDownloadQueue,
            onPauseDownloadQueue = onPauseDownloadQueue,
            onResumeDownloadQueue = onResumeDownloadQueue,
            onProcessNextDownload = onProcessNextDownload,
            onPauseDownload = onPauseDownload,
            onResumeDownload = onResumeDownload,
            onRetryDownload = onRetryDownload,
            onRemoveDownload = onRemoveDownload,
            onClearCompletedDownloads = onClearCompletedDownloads,
            onMoveDownloadToTop = onMoveDownloadToTop,
            onMoveDownloadToBottom = onMoveDownloadToBottom,
            downloadedOnlyMode = downloadedOnlyMode,
            incognitoMode = incognitoMode,
            settings = settings,
            onAppearanceSettingsChange = onAppearanceSettingsChange,
            onLibrarySettingsChange = onLibrarySettingsChange,
            onAnimeLibrarySettingsChange = onAnimeLibrarySettingsChange,
            onReaderSettingsChange = onReaderSettingsChange,
            onDownloadPreferencesChange = onDownloadPreferencesChange,
            onBrowseSettingsChange = onBrowseSettingsChange,
            onNavigationSettingsChange = onNavigationSettingsChange,
            onPlayerSettingsChange = onPlayerSettingsChange,
            onTrackingSettingsChange = onTrackingSettingsChange,
            onConnectionSettingsChange = onConnectionSettingsChange,
            onDictionarySettingsChange = onDictionarySettingsChange,
            onSecuritySettingsChange = onSecuritySettingsChange,
            onOpenExternalUrl = onOpenExternalUrl,
            onDownloadedOnlyModeChange = onDownloadedOnlyModeChange,
            onIncognitoModeChange = onIncognitoModeChange,
            onOpenBrowseSection = onOpenBrowseSection,
            onOpenPage = openPage,
            onBack = {
                pageStack = if (pageStack.size > 1) pageStack.dropLast(1) else listOf(MorePage.Main)
            },
        )
        return
    }
    LazyColumn(
        modifier = Modifier
            .fillMaxSize()
            .background(ChimahonPalette.background),
        contentPadding = PaddingValues(bottom = 16.dp),
    ) {
        item {
            MoreMainHeader(snapshot, settings.appearance.appIcon)
        }
        item { ListGroupHeader("Mode") }
        item {
            PreferenceSwitchRow(
                title = "Downloaded only",
                subtitle = "Show manga saved for offline reading",
                icon = UiIcon.Download,
                checked = downloadedOnlyMode,
                onCheckedChange = onDownloadedOnlyModeChange,
            )
        }
        item {
            PreferenceSwitchRow(
                title = "Incognito mode",
                subtitle = "Pause reading history",
                icon = UiIcon.Incognito,
                checked = incognitoMode,
                onCheckedChange = onIncognitoModeChange,
            )
        }
        item { PreferenceDivider() }
        item { ListGroupHeader("Library") }
        item {
            PreferenceRow(
                "Download queue",
                moreDownloadQueue?.downloadQueueHomeSummary() ?: "Queue and offline downloads",
                UiIcon.Download,
                onClick = { openPage(MorePage.Downloads) },
            )
        }
        item { PreferenceDivider() }
        item {
            PreferenceRow(
                title = "Anime",
                subtitle = "Library, categories, player, and episode queues",
                icon = UiIcon.PlayCircle,
                onClick = { onSelectTab(HomeTab.Anime) },
            )
        }
        item { PreferenceDivider() }
        item {
            PreferenceRow(
                title = "Anime queue",
                subtitle = "Watch queue, downloads, auto-next, and desktop playback controls",
                icon = UiIcon.PlayCircle,
                onClick = { openPage(MorePage.AnimeQueue) },
            )
        }
        item { PreferenceDivider() }
        item {
            PreferenceRow(
                title = "Light novels",
                subtitle = "${snapshot.toNovelLibraryBooks().size} novel item(s), reader, import, and sync surfaces",
                icon = UiIcon.Library,
                onClick = { onSelectTab(HomeTab.Novels) },
            )
        }
        item { PreferenceDivider() }
        item {
            PreferenceRow(
                title = "Novel operations",
                subtitle = "EPUB import, folder scan, source discovery, sync, and categories",
                icon = UiIcon.Chapters,
                onClick = { openPage(MorePage.NovelOperations) },
            )
        }
        item { PreferenceDivider() }
        item {
            PreferenceRow(
                "Categories",
                "${snapshot.libraryCategories.count { !it.hidden }} visible categories",
                UiIcon.Tag,
                onClick = { openPage(MorePage.Categories) },
            )
        }
        item { PreferenceDivider() }
        item {
            PreferenceRow(
                "Statistics",
                "${snapshot.summary.mangaCount} manga in shared database",
                UiIcon.Statistics,
                onClick = { openPage(MorePage.Statistics) },
            )
        }
        item { PreferenceDivider() }
        item { ListGroupHeader("Data") }
        item {
            PreferenceRow(
                "Data and storage",
                snapshot.runtime.filesDir,
                UiIcon.Storage,
                onClick = { openPage(MorePage.Storage) },
            )
        }
        if (snapshot.updateIssues.isNotEmpty()) {
            item { PreferenceDivider() }
            item {
                PreferenceRow(
                    title = "Library update errors",
                    subtitle = "${snapshot.updateIssues.size} unresolved issue(s)",
                    icon = UiIcon.Updates,
                    onClick = { onSelectTab(HomeTab.Updates) },
                )
            }
        }
        item { PreferenceDivider() }
        item { ListGroupHeader("Browse") }
        item {
            PreferenceRow(
                title = "Sources",
                subtitle = "${snapshot.summary.sourceCount} installed",
                icon = UiIcon.Browse,
                onClick = { onOpenBrowseSection(BrowseSection.Sources) },
            )
        }
        item { PreferenceDivider() }
        item {
            PreferenceRow(
                "Extension repositories",
                "${snapshot.extensionRepos.size} configured",
                UiIcon.Extensions,
                onClick = { onOpenBrowseSection(BrowseSection.Extensions) },
            )
        }
        item { PreferenceDivider() }
        item { ListGroupHeader("Settings") }
        item {
            PreferenceRow(
                "Settings",
                "Reader, downloads, tracking, appearance",
                UiIcon.Settings,
                onClick = { openPage(MorePage.Settings) },
            )
        }
        item { PreferenceDivider() }
        item {
            PreferenceRow(
                "About",
                "Chimahon ${snapshot.runtime.platformName}",
                UiIcon.Info,
                onClick = { openPage(MorePage.About) },
            )
        }
        item { PreferenceDivider() }
        item {
            PreferenceRow(
                "Help",
                "Reader, extension, and desktop controls",
                UiIcon.Help,
                onClick = { openPage(MorePage.Help) },
            )
        }
        item {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = 8.dp, bottom = 16.dp),
                contentAlignment = Alignment.Center,
            ) {
                Row(
                    modifier = Modifier
                        .border(2.dp, ChimahonPalette.primary, RoundedCornerShape(6.dp))
                        .clickable { onOpenExternalUrl(CHIMAHON_PROJECT_URL) }
                        .padding(horizontal = 14.dp, vertical = 8.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    IconGlyph(
                        icon = UiIcon.Star,
                        contentDescription = "Star Chimahon",
                        tint = ChimahonPalette.primary,
                        modifier = Modifier.size(18.dp),
                    )
                    Label(
                        "Star me",
                        ChimahonPalette.primary,
                        12,
                        weight = FontWeight.SemiBold,
                        maxLines = 1,
                        modifier = Modifier.padding(start = 6.dp),
                    )
                }
            }
        }
    }
}

@Composable
private fun MoreDetailPage(
    page: MorePage,
    snapshot: ChimahonSnapshot,
    onCreateCategory: suspend (String) -> Long,
    onDeleteCategory: suspend (Long) -> Unit,
    onRenameCategory: suspend (Long, String) -> Unit,
    onSetCategoryHidden: suspend (Long, Boolean) -> Unit,
    onMoveCategory: suspend (Long, Int) -> Unit,
    onCategoriesChanged: () -> Unit,
    onLoadDataMaintenance: suspend () -> ChimahonDataMaintenanceSnapshot,
    onClearThumbnailCache: suspend () -> ChimahonCacheClearResult,
    onClearCacheData: suspend () -> ChimahonCacheClearResult,
    onRunDatabaseMaintenance: suspend () -> ChimahonDatabaseMaintenanceResult,
    onLoadDownloadQueue: suspend () -> ChimahonDownloadQueueData,
    onPauseDownloadQueue: suspend () -> ChimahonDownloadQueueData,
    onResumeDownloadQueue: suspend () -> ChimahonDownloadQueueData,
    onProcessNextDownload: suspend () -> ChimahonDownloadQueueData,
    onPauseDownload: suspend (Long) -> ChimahonDownloadQueueData,
    onResumeDownload: suspend (Long) -> ChimahonDownloadQueueData,
    onRetryDownload: suspend (Long) -> ChimahonDownloadQueueData,
    onRemoveDownload: suspend (Long) -> ChimahonDownloadQueueData,
    onClearCompletedDownloads: suspend () -> ChimahonDownloadQueueData,
    onMoveDownloadToTop: suspend (Long) -> ChimahonDownloadQueueData,
    onMoveDownloadToBottom: suspend (Long) -> ChimahonDownloadQueueData,
    downloadedOnlyMode: Boolean,
    incognitoMode: Boolean,
    settings: ChimahonSettings,
    onAppearanceSettingsChange: (ChimahonAppearanceSettings) -> Unit,
    onLibrarySettingsChange: (ChimahonLibrarySettings) -> Unit,
    onAnimeLibrarySettingsChange: (ChimahonAnimeLibrarySettings) -> Unit,
    onReaderSettingsChange: (ChimahonReaderSettings) -> Unit,
    onDownloadPreferencesChange: (ChimahonDownloadPreferences) -> Unit,
    onBrowseSettingsChange: (ChimahonBrowseSettings) -> Unit,
    onNavigationSettingsChange: (ChimahonNavigationSettings) -> Unit,
    onPlayerSettingsChange: (ChimahonPlayerSettings) -> Unit,
    onTrackingSettingsChange: (ChimahonTrackingSettings) -> Unit,
    onConnectionSettingsChange: (ChimahonConnectionSettings) -> Unit,
    onDictionarySettingsChange: (ChimahonDictionarySettings) -> Unit,
    onSecuritySettingsChange: (ChimahonSecuritySettings) -> Unit,
    onOpenExternalUrl: (String) -> Boolean,
    onDownloadedOnlyModeChange: (Boolean) -> Unit,
    onIncognitoModeChange: (Boolean) -> Unit,
    onOpenBrowseSection: (BrowseSection) -> Unit,
    onOpenPage: (MorePage) -> Unit,
    onBack: () -> Unit,
) {
    var categoryName by remember { mutableStateOf("") }
    var categoryMessage by remember { mutableStateOf<String?>(null) }
    var categoryBusy by remember { mutableStateOf(false) }
    var editingCategoryId by remember { mutableStateOf<Long?>(null) }
    var editingCategoryName by remember { mutableStateOf("") }
    var downloadQueue by remember { mutableStateOf<ChimahonDownloadQueueData?>(null) }
    var downloadQueueMessage by remember { mutableStateOf<String?>(null) }
    var downloadAutoRun by remember { mutableStateOf(true) }
    var downloadProcessorRunning by remember { mutableStateOf(false) }
    var maintenanceSnapshot by remember { mutableStateOf<ChimahonDataMaintenanceSnapshot?>(null) }
    var maintenanceMessage by remember { mutableStateOf<String?>(null) }
    var maintenanceBusy by remember { mutableStateOf(false) }
    var backupMessage by remember { mutableStateOf<String?>(null) }
    var trackingQuery by remember { mutableStateOf("") }
    var trackingSelectedMediaKind by remember { mutableStateOf<ChimahonTrackingMediaKind?>(null) }
    var selectedAnimeQueueIds by remember { mutableStateOf<Set<String>>(emptySet()) }
    var hiddenAnimeQueueIds by remember { mutableStateOf<Set<String>>(emptySet()) }
    var animeQueuePriorityOverrides by remember { mutableStateOf<Map<String, ChimahonAnimeQueuePriority>>(emptyMap()) }
    var animeQueuePaused by remember { mutableStateOf(false) }
    var animeQueueMessage by remember { mutableStateOf<String?>(null) }
    var novelOpsQuery by remember { mutableStateOf("") }
    var selectedNovelOpsCategoryId by remember { mutableStateOf<String?>(null) }
    var novelOpsMessage by remember { mutableStateOf<String?>(null) }
    var shortcutQuery by remember { mutableStateOf("") }
    var shortcutArea by remember { mutableStateOf<ChimahonDesktopShortcutArea?>(null) }
    var shortcutMessage by remember { mutableStateOf<String?>(null) }
    val scope = rememberCoroutineScope()
    fun openBackupPath(label: String, path: String) {
        backupMessage = if (onOpenExternalUrl(path)) {
            "Opening $label"
        } else {
            "Could not open $label from this platform: $path"
        }
    }
    fun runMaintenanceAction(
        failureMessage: String,
        action: suspend () -> String,
    ) {
        if (maintenanceBusy) return
        maintenanceBusy = true
        scope.launch {
            runCatching { action() }
                .onSuccess { maintenanceMessage = it }
                .onFailure { maintenanceMessage = it.message ?: failureMessage }
            maintenanceSnapshot = runCatching { onLoadDataMaintenance() }
                .getOrNull() ?: maintenanceSnapshot
            maintenanceBusy = false
        }
    }
    LaunchedEffect(page) {
        if (page == MorePage.Downloads) {
            downloadQueue = runCatching { onLoadDownloadQueue() }.getOrNull()
        }
        if (
            page == MorePage.Storage ||
            page == MorePage.BackupSettings ||
            page == MorePage.AdvancedSettings
        ) {
            maintenanceSnapshot = runCatching { onLoadDataMaintenance() }
                .onFailure { maintenanceMessage = it.message ?: "Could not load storage data" }
                .getOrNull()
        }
    }
    val downloadQueueSignature = downloadQueue?.entries
        ?.joinToString("|") { entry -> "${entry.id}:${entry.status}:${entry.progress}" }
    LaunchedEffect(
        page,
        downloadAutoRun,
        downloadQueue?.paused,
        downloadQueue?.pendingCount,
        downloadQueue?.activeCount,
        downloadQueueSignature,
    ) {
        val queue = downloadQueue
        if (
            page == MorePage.Downloads &&
            downloadAutoRun &&
            queue != null &&
            !queue.paused &&
            queue.pendingCount > 0 &&
            queue.activeCount == 0
        ) {
            downloadProcessorRunning = true
            downloadQueueMessage = "Downloading next chapter..."
            val result = runCatching { onProcessNextDownload() }
            downloadQueue = result.getOrElse { error ->
                downloadQueueMessage = error.message ?: "Could not process next download"
                runCatching { onLoadDownloadQueue() }.getOrNull() ?: queue
            }
            result.getOrNull()?.let { updated ->
                downloadQueueMessage = when {
                    updated.pendingCount > 0 -> "Downloaded one chapter. ${updated.pendingCount} waiting."
                    updated.failedCount > 0 -> "Queue finished with ${updated.failedCount} failed item(s)."
                    else -> "Download queue finished."
                }
            }
            downloadProcessorRunning = false
        }
    }
    Column(modifier = Modifier.fillMaxSize()) {
        SettingsTopBar(
            page = page,
            subtitle = page.morePageSubtitle(snapshot),
            onBack = onBack,
        )
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .background(ChimahonPalette.background),
            contentPadding = PaddingValues(bottom = 20.dp),
        ) {
            when (page) {
                MorePage.Downloads -> {
                    val queue = downloadQueue
                    item {
                        MoreDownloadSummary(
                            downloadsDirectory = snapshot.runtime.downloadsDir,
                            downloadedOnlyMode = downloadedOnlyMode,
                            queue = queue,
                            preferences = settings.downloads,
                            onOpenSettings = { onOpenPage(MorePage.DownloadSettings) },
                            onOpenFolder = {
                                downloadQueueMessage = if (onOpenExternalUrl(snapshot.runtime.downloadsDir)) {
                                    "Opening download folder"
                                } else {
                                    "Could not open the download folder from this platform"
                                }
                            },
                        )
                    }
                    item {
                        DownloadQueueToolbar(
                            queue = queue,
                            message = downloadQueueMessage,
                            processing = downloadProcessorRunning,
                            autoRun = downloadAutoRun,
                            onAutoRunChange = { downloadAutoRun = it },
                            onTogglePaused = {
                                scope.launch {
                                    downloadQueue = if (downloadQueue?.paused == true) {
                                        runCatching { onResumeDownloadQueue() }
                                            .onFailure { downloadQueueMessage = it.message ?: "Could not resume queue" }
                                            .getOrNull()
                                    } else {
                                        runCatching { onPauseDownloadQueue() }
                                            .onFailure { downloadQueueMessage = it.message ?: "Could not pause queue" }
                                            .getOrNull()
                                    } ?: downloadQueue
                                }
                            },
                            onProcessNext = {
                                if (!downloadProcessorRunning) {
                                    scope.launch {
                                        val current = downloadQueue
                                        downloadProcessorRunning = true
                                        downloadQueueMessage = "Downloading next chapter..."
                                        val result = runCatching { onProcessNextDownload() }
                                        downloadQueue = result.getOrElse { error ->
                                            downloadQueueMessage = error.message ?: "Could not process next download"
                                            runCatching { onLoadDownloadQueue() }.getOrNull() ?: current
                                        }
                                        result.getOrNull()?.let { updated ->
                                            downloadQueueMessage = when {
                                                updated.pendingCount > 0 -> "Downloaded one chapter. ${updated.pendingCount} waiting."
                                                updated.failedCount > 0 -> "Queue finished with ${updated.failedCount} failed item(s)."
                                                else -> "Download queue finished."
                                            }
                                        }
                                        downloadProcessorRunning = false
                                    }
                                }
                            },
                            onClearCompleted = {
                                scope.launch {
                                    downloadQueue = runCatching { onClearCompletedDownloads() }
                                        .onSuccess { downloadQueueMessage = "Cleared completed downloads" }
                                        .onFailure { downloadQueueMessage = it.message ?: "Could not clear completed downloads" }
                                        .getOrNull() ?: downloadQueue
                                }
                            },
                            onRetryFailed = {
                                val failedEntries = downloadQueue?.entries
                                    .orEmpty()
                                    .filter { it.status == ChimahonDownloadState.Error }
                                if (failedEntries.isNotEmpty()) {
                                    scope.launch {
                                        var updatedQueue = downloadQueue
                                        var retriedCount = 0
                                        failedEntries.forEach { entry ->
                                            updatedQueue = runCatching { onRetryDownload(entry.chapterId) }
                                                .onSuccess { retriedCount++ }
                                                .onFailure { downloadQueueMessage = it.message ?: "Could not retry failed downloads" }
                                                .getOrNull() ?: updatedQueue
                                        }
                                        downloadQueue = updatedQueue
                                        if (retriedCount > 0) {
                                            downloadQueueMessage = "Retried $retriedCount failed download(s)"
                                        }
                                    }
                                }
                            },
                        )
                    }
                    if (queue == null) {
                        item {
                            ExtensionStatusRow(
                                title = "Loading download queue",
                                subtitle = "Reading saved queue state.",
                            )
                        }
                    } else if (queue.entries.isEmpty()) {
                        item {
                            EmptyMobileState(
                                marker = "D",
                                icon = UiIcon.Download,
                                title = "Download queue is empty",
                                detail = "New chapter downloads will appear here with pause, resume, reorder, and cancel controls.",
                            )
                        }
                    } else {
                        queue.toDownloadSourceGroups(snapshot).forEach { group ->
                            item(key = "download-source-${group.sourceId}") {
                                DownloadQueueSourceHeader(group)
                            }
                            items(group.entries, key = { it.id }) { entry ->
                                val position = queue.entries.indexOfFirst { it.id == entry.id }.coerceAtLeast(0) + 1
                                DownloadQueueEntryRow(
                                    entry = entry,
                                    sourceName = group.sourceName,
                                    position = position,
                                    onPrimaryAction = {
                                        scope.launch {
                                            downloadQueue = runCatching {
                                                when (entry.status) {
                                                    ChimahonDownloadState.Paused -> onResumeDownload(entry.chapterId)
                                                    ChimahonDownloadState.Error -> onRetryDownload(entry.chapterId)
                                                    ChimahonDownloadState.Downloaded -> onRemoveDownload(entry.chapterId)
                                                    ChimahonDownloadState.Queued,
                                                    ChimahonDownloadState.Downloading,
                                                    -> onPauseDownload(entry.chapterId)
                                                }
                                            }
                                                .onFailure { downloadQueueMessage = it.message ?: "Could not update download" }
                                                .getOrNull() ?: downloadQueue
                                        }
                                    },
                                    onMoveTop = {
                                        scope.launch {
                                            downloadQueue = runCatching { onMoveDownloadToTop(entry.chapterId) }
                                                .onFailure { downloadQueueMessage = it.message ?: "Could not move download" }
                                                .getOrNull() ?: downloadQueue
                                        }
                                    },
                                    onMoveBottom = {
                                        scope.launch {
                                            downloadQueue = runCatching { onMoveDownloadToBottom(entry.chapterId) }
                                                .onFailure { downloadQueueMessage = it.message ?: "Could not move download" }
                                                .getOrNull() ?: downloadQueue
                                        }
                                    },
                                    onRemove = {
                                        scope.launch {
                                            downloadQueue = runCatching { onRemoveDownload(entry.chapterId) }
                                                .onFailure { downloadQueueMessage = it.message ?: "Could not remove download" }
                                                .getOrNull() ?: downloadQueue
                                        }
                                    },
                                )
                            }
                        }
                    }
                }
                MorePage.AnimeQueue -> {
                    val animeQueueState = snapshot.toAnimeQueueUiState(
                        selectedEpisodeIds = selectedAnimeQueueIds,
                        hiddenEpisodeIds = hiddenAnimeQueueIds,
                        priorityOverrides = animeQueuePriorityOverrides,
                        paused = animeQueuePaused,
                        autoPlayEnabled = settings.player.autoplayEnabled,
                    )
                    val animeQueueActions = ChimahonAnimeQueueRowActions(
                        onOpenRow = { row ->
                            animeQueueMessage = "Ready to open ${row.episodeTitle}"
                        },
                        onSelectionChange = { row, selected ->
                            selectedAnimeQueueIds = if (selected) {
                                selectedAnimeQueueIds + row.id
                            } else {
                                selectedAnimeQueueIds - row.id
                            }
                        },
                        onPlayEpisode = { row ->
                            animeQueueMessage = "Opening ${row.episodeTitle} in the desktop player"
                        },
                        onStreamEpisode = { row ->
                            animeQueueMessage = "Streaming ${row.episodeTitle}"
                        },
                        onDownloadEpisode = { row ->
                            animeQueuePriorityOverrides = animeQueuePriorityOverrides + (row.id to ChimahonAnimeQueuePriority.High)
                            animeQueueMessage = "Queued ${row.episodeTitle} for anime download"
                        },
                        onRetryEpisode = { row ->
                            animeQueueMessage = "Retrying ${row.episodeTitle}"
                        },
                        onPauseEpisode = { row ->
                            animeQueueMessage = "Paused ${row.episodeTitle}"
                        },
                        onCancelEpisode = { row ->
                            hiddenAnimeQueueIds = hiddenAnimeQueueIds + row.id
                            selectedAnimeQueueIds = selectedAnimeQueueIds - row.id
                            animeQueueMessage = "Canceled ${row.episodeTitle}"
                        },
                        onRemoveEpisode = { row ->
                            hiddenAnimeQueueIds = hiddenAnimeQueueIds + row.id
                            selectedAnimeQueueIds = selectedAnimeQueueIds - row.id
                            animeQueueMessage = "Removed ${row.episodeTitle} from the anime queue"
                        },
                        onPriorityChange = { row, priority ->
                            animeQueuePriorityOverrides = animeQueuePriorityOverrides + (row.id to priority)
                            animeQueueMessage = "${row.episodeTitle} priority set to ${priority.label}"
                        },
                        onMoveToTop = { row ->
                            animeQueuePriorityOverrides = animeQueuePriorityOverrides + (row.id to ChimahonAnimeQueuePriority.Next)
                            animeQueueMessage = "${row.episodeTitle} will play next"
                        },
                        onMoveUp = { row ->
                            animeQueueMessage = "Moved ${row.episodeTitle} up"
                        },
                        onMoveDown = { row ->
                            animeQueueMessage = "Moved ${row.episodeTitle} down"
                        },
                        onMoveToBottom = { row ->
                            animeQueuePriorityOverrides = animeQueuePriorityOverrides + (row.id to ChimahonAnimeQueuePriority.Low)
                            animeQueueMessage = "${row.episodeTitle} moved to the end"
                        },
                    )
                    val animeBatchState = animeQueueState.toAnimeBatchActionBarState(
                        onPlaySelected = {
                            animeQueueMessage = "Opening ${animeQueueState.selectedCount} selected episode(s)"
                            selectedAnimeQueueIds = emptySet()
                        },
                        onDownloadSelected = {
                            animeQueuePriorityOverrides = animeQueuePriorityOverrides +
                                selectedAnimeQueueIds.associateWith { ChimahonAnimeQueuePriority.High }
                            animeQueueMessage = "Queued ${animeQueueState.selectedCount} episode(s) for download"
                            selectedAnimeQueueIds = emptySet()
                        },
                        onMarkSeenSelected = {
                            animeQueueMessage = "Marked ${animeQueueState.selectedCount} episode(s) seen locally"
                            selectedAnimeQueueIds = emptySet()
                        },
                        onRemoveSelected = {
                            hiddenAnimeQueueIds = hiddenAnimeQueueIds + selectedAnimeQueueIds
                            animeQueueMessage = "Removed ${animeQueueState.selectedCount} episode(s) from the queue"
                            selectedAnimeQueueIds = emptySet()
                        },
                    )
                    item {
                        ExtensionStatusRow(
                            title = animeQueueState.title,
                            subtitle = animeQueueState.summaryLabel,
                            action = "Anime",
                            onAction = { onOpenPage(MorePage.AnimeLibrarySettings) },
                        )
                    }
                    item {
                        PreferenceSwitchRow(
                            title = "Pause anime queue",
                            subtitle = if (animeQueuePaused) {
                                "Episode queue is paused for desktop playback"
                            } else {
                                "Episode queue advances through ready and queued items"
                            },
                            icon = UiIcon.Pause,
                            checked = animeQueuePaused,
                            onCheckedChange = { animeQueuePaused = it },
                        )
                    }
                    item {
                        PreferenceSwitchRow(
                            title = "Autoplay next episode",
                            subtitle = "Use the shared player autoplay setting for anime auto-next",
                            icon = UiIcon.PlayCircle,
                            checked = settings.player.autoplayEnabled,
                            onCheckedChange = { onPlayerSettingsChange(settings.player.copy(autoplayEnabled = it)) },
                        )
                    }
                    item {
                        ExtensionStatusRow(
                            title = "Desktop playback controls",
                            subtitle = "Menu, keyboard, mouse, and player gestures are mapped for the desktop port.",
                            action = "Player",
                            onAction = { onOpenPage(MorePage.PlayerSettings) },
                        )
                    }
                    animeQueueMessage?.let { message ->
                        item {
                            ExtensionStatusRow(
                                title = "Anime queue",
                                subtitle = message,
                            )
                        }
                    }
                    if (animeQueueState.hasRows) {
                        item { ListGroupHeader("Queue") }
                        item {
                            ExtensionStatusRow(
                                title = "Selection",
                                subtitle = if (animeQueueState.isSelectionMode) {
                                    "${animeQueueState.selectedCount} of ${animeQueueState.rows.size} episode(s) selected"
                                } else {
                                    "Long-select style batch actions are available on desktop with row checkboxes"
                                },
                                action = if (animeQueueState.isSelectionMode) "Clear" else "Select all",
                                onAction = {
                                    selectedAnimeQueueIds = if (animeQueueState.isSelectionMode) {
                                        emptySet()
                                    } else {
                                        animeQueueState.rows.mapTo(mutableSetOf()) { it.id }
                                    }
                                },
                            )
                        }
                        if (animeQueueState.isSelectionMode) {
                            item {
                                ChimahonAnimeEpisodeBottomBatchActionBar(
                                    state = animeBatchState,
                                    modifier = Modifier.padding(horizontal = 12.dp, vertical = 4.dp),
                                )
                            }
                        }
                        items(animeQueueState.rows, key = { "anime-queue-${it.id}" }) { row ->
                            ChimahonAnimeQueueRow(
                                row = row,
                                actions = animeQueueActions,
                                modifier = Modifier.padding(horizontal = 12.dp, vertical = 3.dp),
                                selectionMode = animeQueueState.isSelectionMode,
                                showPriorityControl = true,
                                showReorderControls = true,
                            )
                        }
                    } else {
                        item {
                            ChimahonAnimeQueueStateHost(
                                loading = animeQueueState.loading,
                                errorMessage = animeQueueState.errorMessage,
                                empty = true,
                                surfaceKind = ChimahonAnimeQueueSurfaceKind.WatchQueue,
                                onRetry = { animeQueueMessage = "Anime queue refreshed" },
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(320.dp),
                                emptyActionLabel = "Open settings",
                                onEmptyActionClick = { onOpenPage(MorePage.AnimeLibrarySettings) },
                                content = {},
                            )
                        }
                    }
                    item { ListGroupHeader("Auto-next playlist") }
                    item {
                        ChimahonAnimeAutoNextPlaylistSheet(
                            state = animeQueueState.playlist,
                            actions = ChimahonAnimeAutoNextPlaylistActions(
                                onDismiss = { animeQueueMessage = "Auto-next playlist remains available from the queue" },
                                onRetry = { animeQueueMessage = "Auto-next playlist refreshed" },
                                onToggleAutoPlay = { onPlayerSettingsChange(settings.player.copy(autoplayEnabled = it)) },
                                onPlayNow = { episode ->
                                    animeQueueMessage = "Playing ${episode.episodeTitle}"
                                },
                                onEpisodeClick = { episode ->
                                    animeQueueMessage = "Selected ${episode.episodeTitle}"
                                },
                                onDownloadEpisode = { episode ->
                                    animeQueuePriorityOverrides = animeQueuePriorityOverrides +
                                        (episode.id to ChimahonAnimeQueuePriority.High)
                                    animeQueueMessage = "Queued ${episode.episodeTitle} for download"
                                },
                                onRetryEpisode = { episode ->
                                    animeQueueMessage = "Retrying ${episode.episodeTitle}"
                                },
                                onRemoveEpisode = { episode ->
                                    hiddenAnimeQueueIds = hiddenAnimeQueueIds + episode.id
                                    selectedAnimeQueueIds = selectedAnimeQueueIds - episode.id
                                    animeQueueMessage = "Removed ${episode.episodeTitle} from auto-next"
                                },
                            ),
                            modifier = Modifier
                                .padding(horizontal = 12.dp, vertical = 8.dp)
                                .heightIn(max = 520.dp),
                        )
                    }
                }
                MorePage.NovelOperations -> {
                    val novelBooks = snapshot.toNovelLibraryBooks()
                    val novelOperationsState = snapshot.toNovelOperationsState(
                        novelBooks = novelBooks,
                        query = novelOpsQuery,
                        activeCategoryId = selectedNovelOpsCategoryId,
                    )
                    val novelOperationsActions = NovelOperationsActions(
                        onOperation = { action ->
                            novelOpsMessage = when (action) {
                                NovelOperationAction.PickEpub -> "Opening EPUB import"
                                NovelOperationAction.PickFolder -> "Opening folder import"
                                NovelOperationAction.ConnectDrive -> "TTSU/Drive connection requested"
                                NovelOperationAction.DisconnectDrive -> "Disconnect sync requested"
                                NovelOperationAction.RunSync -> "Manual novel sync requested"
                                NovelOperationAction.StopSync -> "Novel sync stopped"
                                NovelOperationAction.CreateCategory -> "Create novel category"
                                else -> action.name
                            }
                            if (
                                action == NovelOperationAction.PickEpub ||
                                action == NovelOperationAction.PickFolder
                            ) {
                                onOpenPage(MorePage.NovelImport)
                            }
                        },
                        onCandidateAction = { action, candidate ->
                            novelOpsMessage = when (action) {
                                NovelOperationAction.OpenNovel -> "Novel candidate selected: ${candidate.title}"
                                NovelOperationAction.ImportCandidate -> "Import candidate staged: ${candidate.title}"
                                NovelOperationAction.ResolveConflict -> "Resolve import conflict: ${candidate.title}"
                                else -> "${action.name}: ${candidate.title}"
                            }
                            if (action == NovelOperationAction.ImportCandidate) {
                                onOpenPage(MorePage.NovelImport)
                            }
                        },
                        onQueueAction = { action, item ->
                            novelOpsMessage = "${action.name}: ${item.candidate.title}"
                        },
                        onSourceAction = { action, source ->
                            novelOpsMessage = "${action.name}: ${source.title}"
                            if (source.kind == NovelSourceKind.RemoteUrl) {
                                onOpenBrowseSection(BrowseSection.Sources)
                            } else {
                                onOpenPage(MorePage.NovelImport)
                            }
                        },
                        onCategoryAction = { action, category ->
                            selectedNovelOpsCategoryId = category.id
                            novelOpsMessage = "${action.name}: ${category.title}"
                        },
                        onQueryChange = { novelOpsQuery = it },
                        onSyncModeChange = { mode ->
                            novelOpsMessage = "Novel sync mode: ${mode.title}"
                        },
                        onSyncDirectionChange = { direction ->
                            novelOpsMessage = "Novel sync direction: ${direction.title}"
                        },
                        onCategoryNameDraftChange = { draft ->
                            novelOpsMessage = draft.takeIf { it.isNotBlank() }?.let { "Category draft: $it" }
                        },
                    )
                    item {
                        ExtensionStatusRow(
                            title = "Light novel operations",
                            subtitle = "${novelBooks.size} novel item(s), ${novelOperationsState.discover.sources.size} source adapter(s)",
                            action = "Import",
                            onAction = { onOpenPage(MorePage.NovelImport) },
                        )
                    }
                    novelOpsMessage?.let { message ->
                        item {
                            ExtensionStatusRow(
                                title = "Novel status",
                                subtitle = message,
                            )
                        }
                    }
                    item {
                        NovelOperationsScreen(
                            state = novelOperationsState,
                            actions = novelOperationsActions,
                            modifier = Modifier
