                        BackupScopeItem(
                            title = "Tracking",
                            count = trackingAccountRows().size,
                            icon = UiIcon.Statistics,
                            description = settings.tracking.trackingSyncSummary(incognitoMode),
                            status = "Pending",
                            warning = true,
