private fun shortcutRow(
    id: String,
    title: String,
    description: String,
    key: String,
    vararg modifiers: ChimahonDesktopShortcutModifier,
    areas: Set<ChimahonDesktopShortcutArea>,
    alternate: List<ChimahonDesktopShortcutChord> = emptyList(),
): ChimahonDesktopShortcutRowModel {
    return ChimahonDesktopShortcutRowModel(
        id = id,
        title = title,
        description = description,
        shortcut = chord(key, *modifiers),
        alternateShortcuts = alternate,
        areas = areas,
    )
}

private fun chord(
    key: String,
    vararg modifiers: ChimahonDesktopShortcutModifier,
): ChimahonDesktopShortcutChord {
    return chimahonDesktopShortcutChord(key, *modifiers)
}

@Composable
private fun MoreDownloadSummary(
    downloadsDirectory: String,
    downloadedOnlyMode: Boolean,
    queue: ChimahonDownloadQueueData?,
    preferences: ChimahonDownloadPreferences,
    onOpenSettings: () -> Unit,
    onOpenFolder: () -> Unit,
) {
    val queueSummary = queue?.downloadQueueHomeSummary() ?: "Loading queue state"
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .background(ChimahonPalette.surface)
            .padding(horizontal = 16.dp, vertical = 14.dp),
        verticalArrangement = Arrangement.spacedBy(12.dp),
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Box(
                modifier = Modifier
                    .size(46.dp)
                    .clip(RoundedCornerShape(8.dp))
                    .background(ChimahonPalette.primaryContainer),
                contentAlignment = Alignment.Center,
            ) {
                IconGlyph(
                    icon = UiIcon.Download,
                    contentDescription = "",
                    tint = ChimahonPalette.primary,
                    modifier = Modifier.size(24.dp),
                )
            }
            Column(
                modifier = Modifier
                    .weight(1f)
                    .padding(horizontal = 14.dp),
            ) {
                Label(
                    when {
                        downloadedOnlyMode -> "Downloaded-only mode enabled"
                        queue?.activeCount?.let { it > 0 } == true -> "Downloads running"
                        queue?.entries?.isNotEmpty() == true -> "Download queue ready"
                        else -> "Downloads ready"
                    },
                    ChimahonPalette.onSurface,
                    14,
                    weight = FontWeight.SemiBold,
                    maxLines = 1,
                )
                Label(
                    queueSummary,
                    ChimahonPalette.secondaryText,
                    11,
                    maxLines = 1,
                    modifier = Modifier.padding(top = 3.dp),
                )
                Label(
                    preferences.downloadRestrictionSummary(downloadedOnlyMode),
                    ChimahonPalette.secondaryText,
                    10,
                    maxLines = 2,
                    modifier = Modifier.padding(top = 3.dp),
                )
            }
