@Composable
private fun PreferenceSwitchRow(
    title: String,
    subtitle: String,
    icon: UiIcon,
    checked: Boolean? = null,
    enabled: Boolean = true,
    onCheckedChange: (Boolean) -> Unit = {},
) {
    var localEnabled by remember(title) { mutableStateOf(false) }
    val checkedState = checked ?: localEnabled
    val clickModifier = if (enabled) {
        Modifier.clickable {
            val next = !checkedState
            if (checked == null) {
                localEnabled = next
            }
            onCheckedChange(next)
        }
    } else {
        Modifier
    }
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .heightIn(min = 58.dp)
            .background(ChimahonPalette.surface)
            .alpha(if (enabled) 1f else 0.54f)
            .then(clickModifier)
            .padding(start = 20.dp, end = 18.dp, top = 8.dp, bottom = 8.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        PreferenceIconBox(
            icon = icon,
            active = checkedState,
        )
        Column(
            modifier = Modifier
                .weight(1f)
                .padding(start = 16.dp, end = 12.dp),
        ) {
            SettingsRowTitleBlock(title = title, subtitle = subtitle)
        }
        AndroidSwitchVisual(checked = checkedState)
    }
}

@Composable
private fun NotificationPreferenceRow(
    title: String,
    subtitle: String,
    icon: UiIcon,
    checked: Boolean,
    enabledLabel: String,
    disabledLabel: String,
    detail: String? = null,
    enabled: Boolean = true,
    onCheckedChange: (Boolean) -> Unit,
) {
    val clickModifier = if (enabled) Modifier.clickable { onCheckedChange(!checked) } else Modifier
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .heightIn(min = 64.dp)
            .background(ChimahonPalette.surface)
            .alpha(if (enabled) 1f else 0.54f)
            .then(clickModifier)
            .padding(start = 20.dp, end = 18.dp, top = 8.dp, bottom = 8.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        PreferenceIconBox(
            icon = icon,
            active = checked,
        )
        Column(
            modifier = Modifier
                .weight(1f)
                .padding(start = 16.dp, end = 12.dp),
        ) {
            SettingsRowTitleBlock(title = title, subtitle = subtitle)
            Row(
                horizontalArrangement = Arrangement.spacedBy(6.dp),
                verticalAlignment = Alignment.CenterVertically,
                modifier = Modifier.padding(top = 7.dp),
            ) {
                UpdateHistoryStatusChip(
                    text = if (checked) enabledLabel else disabledLabel,
                    active = checked,
                )
                detail?.takeIf { it.isNotBlank() }?.let {
                    UpdateHistoryStatusChip(text = it, active = false)
                }
            }
        }
        AndroidSwitchVisual(checked = checked)
    }
}

