        ChimahonDownloadState.Downloading -> progress
            .takeIf { it in 1..99 }
            ?.let { "Downloading $it%" }
            ?: "Downloading"
        else -> status.queueTitle()
    }
}

private fun Long.toReadableBytes(): String {
    if (this <= 0L) return "0 B"
    val units = listOf("B", "KB", "MB", "GB", "TB")
    var value = this.toDouble()
    var index = 0
    while (value >= 1024.0 && index < units.lastIndex) {
        value /= 1024.0
        index += 1
    }
    return if (index == 0) {
        "${value.toLong()} ${units[index]}"
    } else {
        "${(value * 10.0).toInt() / 10.0} ${units[index]}"
    }
}

private fun ChimahonCacheClearResult.cacheClearSummary(): String {
    val targetTitle = when (target) {
        ChimahonCacheClearTarget.Thumbnails -> "Thumbnail cache"
        ChimahonCacheClearTarget.ApplicationCache -> "Application cache"
    }
    val removedBytes = diskBytesRemoved + memoryBytesRemoved
    val removedEntries = diskFilesRemoved + memoryEntriesRemoved
    val base = "$targetTitle cleared: ${removedBytes.toReadableBytes()}, $removedEntries file/cache item(s)"
    return if (failures.isEmpty()) {
        base
    } else {
        "$base, ${failures.size} path(s) could not be removed"
    }
}

private fun ChimahonDatabaseMaintenanceResult.databaseMaintenanceSummary(): String {
    return "Removed $historyEntriesRemoved history record(s) and $updateIssuesRemoved update issue(s). " +
        "$remainingHistoryEntryCount history record(s) remain."
}

private fun previewDataMaintenanceSnapshot(): ChimahonDataMaintenanceSnapshot {
    val section = ChimahonStorageSection(
        path = "preview",
        exists = false,
        sizeBytes = 0L,
        fileCount = 0,
        directoryCount = 0,
    )
    return ChimahonDataMaintenanceSnapshot(
        storage = ChimahonStorageData(
            files = section,
            cache = section,
            downloads = section,
            totalSizeBytes = 0L,
            downloadedMangaCount = 0,
            downloadedChapterCount = 0,
        ),
        thumbnailCache = ChimahonThumbnailCacheData(entryCount = 0, sizeBytes = 0L),
        database = ChimahonDatabaseMaintenanceData(
            historyEntryCount = 0,
            updateIssues = ChimahonUpdateIssueSummary(
                totalIssueCount = 0,
                affectedMangaCount = 0,
                staleIssueCount = 0,
                groups = emptyList(),
            ),
        ),
    )
}

private fun previewCacheClearResult(target: ChimahonCacheClearTarget): ChimahonCacheClearResult {
    return ChimahonCacheClearResult(
        target = target,
        diskBytesRemoved = 0L,
        diskFilesRemoved = 0,
        diskDirectoriesRemoved = 0,
        memoryBytesRemoved = 0L,
        memoryEntriesRemoved = 0,
    )
}

private fun previewDatabaseMaintenanceResult(): ChimahonDatabaseMaintenanceResult {
    return ChimahonDatabaseMaintenanceResult(
        historyEntriesRemoved = 0,
        updateIssuesRemoved = 0,
        remainingHistoryEntryCount = 0,
        remainingUpdateIssueCount = 0,
    )
}

private fun ChimahonRecentUpdateEntry.updateStateLabel(): String {
    return when {
        read -> "Read"
        lastPageRead > 0L -> "Started"
        bookmarked -> "Bookmarked"
        else -> "New"
    }
}

private fun ChimahonHistoryEntry.historyStateLabel(): String {
    return when {
        read -> "Read"
        lastPageRead > 0L -> "Page ${lastPageRead + 1}"
        readAt != null && readAt > 0L -> "Recent"
        else -> "History"
    }
}

private fun ChimahonRecentUpdateEntry.updateChapterSubtitle(): String {
    return buildString {
        append(chapterName)
        scanlator?.takeIf { it.isNotBlank() }?.let {
            append("  -  ").append(it)
        }
        if (lastPageRead > 0L) {
            append("  -  Page ").append(lastPageRead + 1)
        }
    }
}

private fun ChimahonHistoryEntry.historySubtitle(): String {
    return buildString {
        append("Ch. ").append(chapterNumber.toDisplayChapter())
        readAt?.let { append("  -  ").append(it.toDateBucket("Read")) }
        if (lastPageRead > 0L) {
            append("  -  Page ").append(lastPageRead + 1)
        }
        if (totalCount > 0.0) {
            append("  -  ")
            append(readCount.toLong()).append("/").append(totalCount.toLong())
        }
    }
}

private fun ChimahonSnapshot.detailTitle(mangaId: Long?): String {
    return mangaId?.let { mangaDetails[it]?.title } ?: "Manga details"
}

private fun ChimahonSourceEntry.isLocalSource(): Boolean {
    return id == CHIMAHON_LOCAL_SOURCE_ID ||
        name.equals("Local source", ignoreCase = true) ||
        name.equals("Local", ignoreCase = true)
}

private fun ChimahonMangaEntry.isLocalManga(): Boolean {
    return sourceId == CHIMAHON_LOCAL_SOURCE_ID
}

private fun ChimahonSnapshot.localSourceEntry(): ChimahonSourceEntry? {
    return sources.firstOrNull(ChimahonSourceEntry::isLocalSource)
}

private fun ChimahonSnapshot.localMangaEntries(): List<ChimahonMangaEntry> {
    return library.filter(ChimahonMangaEntry::isLocalManga)
}

private fun ChimahonSnapshot.localChapterCount(): Int {
    return localMangaEntries().sumOf { manga -> chaptersByMangaId[manga.id].orEmpty().size }
}

private fun ChimahonSnapshot.sourceImportRows(): List<BackupScopeItem> {
    if (library.isEmpty()) {
        return listOf(
            BackupScopeItem(
                title = "No library sources",
                count = 0,
                icon = UiIcon.Info,
                description = "Import rows will appear after manga are added to the library",
                status = "Empty",
                warning = true,
            ),
        )
    }
    val sourceRows = library
        .groupBy(ChimahonMangaEntry::sourceId)
        .toList()
        .sortedWith(
            compareBy<Pair<Long, List<ChimahonMangaEntry>>> { if (it.first == CHIMAHON_LOCAL_SOURCE_ID) 0 else 1 }
                .thenBy { sourceName(it.first).lowercase() },
        )
        .map { (sourceId, mangaEntries) ->
            val source = sourceEntry(sourceId)
            val chapterCount = mangaEntries.sumOf { manga -> chaptersByMangaId[manga.id].orEmpty().size }
            val local = sourceId == CHIMAHON_LOCAL_SOURCE_ID || source?.isLocalSource() == true
            BackupScopeItem(
                title = source?.name ?: if (local) "Local source" else sourceName(sourceId),
                count = mangaEntries.size,
                icon = if (local) UiIcon.Storage else UiIcon.Web,
                description = "$chapterCount chapter(s), source ID $sourceId",
                status = when {
                    local && source != null -> "Local"
                    source != null -> source.language.sourceLanguageCode()
                    else -> "Missing"
                },
                selected = source != null,
                warning = source == null,
            )
        }
    val visibleRows = sourceRows.take(8)
    val hiddenRows = sourceRows.drop(8)
    return if (hiddenRows.isEmpty()) {
        visibleRows
    } else {
        visibleRows + BackupScopeItem(
            title = "Other sources",
            count = hiddenRows.sumOf { it.count },
            icon = UiIcon.Browse,
            description = "${hiddenRows.size} additional source import row(s)",
            status = "Grouped",
        )
    }
}

private fun ChimahonSnapshot.categoryImportRows(): List<BackupScopeItem> {
    val categories = libraryCategoryTabs().filterNot { it.id == ALL_LIBRARY_CATEGORY_ID }
    if (categories.isEmpty()) {
        return listOf(
            BackupScopeItem(
                title = "Default",
                count = library.size,
                icon = UiIcon.Tag,
                description = "${localMangaEntries().size} local manga, ${library.size} total",
                status = "System",
                selected = library.isNotEmpty(),
            ),
        )
    }
    val categoryRows = categories.map { category ->
        val mangaEntries = libraryForCategory(category.id)
        val localCount = mangaEntries.count(ChimahonMangaEntry::isLocalManga)
        val chapterCount = mangaEntries.sumOf { manga -> chaptersByMangaId[manga.id].orEmpty().size }
        BackupScopeItem(
            title = category.displayName(),
            count = mangaEntries.size,
            icon = UiIcon.Tag,
            description = "$chapterCount chapter(s), $localCount local manga",
            status = when {
                category.id == DEFAULT_LIBRARY_CATEGORY_ID -> "Default"
                category.hidden -> "Hidden"
                else -> "Visible"
            },
            selected = mangaEntries.isNotEmpty() && !category.hidden,
            warning = category.hidden,
        )
    }
    val visibleRows = categoryRows.take(8)
    val hiddenRows = categoryRows.drop(8)
    return if (hiddenRows.isEmpty()) {
        visibleRows
    } else {
        visibleRows + BackupScopeItem(
            title = "Other categories",
            count = hiddenRows.sumOf { it.count },
            icon = UiIcon.Tag,
            description = "${hiddenRows.size} additional category import row(s)",
            status = "Grouped",
        )
    }
}

private fun ChimahonSnapshot.sourceName(sourceId: Long): String {
    return sources.firstOrNull { it.id == sourceId }?.name ?: "Source $sourceId"
}

private fun ChimahonSnapshot.sourceEntry(sourceId: Long): ChimahonSourceEntry? {
    return sources.firstOrNull { it.id == sourceId }
}

private fun ChimahonSnapshot.groupedUpdateIssues(): List<UpdateIssueGroup> {
    val categoriesById = libraryCategories.associateBy { it.id }
    val categoryOrder = libraryCategories
        .sortedWith(compareBy<ChimahonLibraryCategory> { it.order }.thenBy { it.displayName().lowercase() })
        .mapIndexed { index, category -> category.id to index }
        .toMap()
    val rows = updateIssues.map { issue ->
        val manga = mangaDetails[issue.mangaId]
        val sourceName = manga?.sourceId?.let(::sourceName) ?: "Unknown source"
        val categoryName = libraryCategoryMemberships[issue.mangaId]
            .orEmpty()
            .sortedBy { categoryOrder[it] ?: Int.MAX_VALUE }
            .mapNotNull { categoriesById[it]?.displayName() }
            .firstOrNull()
            ?: if (manga != null) {
                "Default"
            } else {
                "No category"
            }
        UpdateIssueRow(
            issue = issue,
            sourceName = sourceName,
            categoryName = categoryName,
        )
    }
    return rows
        .groupBy { UpdateIssueGroupKey(it.sourceName, it.categoryName) }
        .map { (key, groupRows) ->
            UpdateIssueGroup(
                sourceName = key.sourceName,
                categoryName = key.categoryName,
                rows = groupRows.sortedWith(
                    compareBy<UpdateIssueRow> { it.issue.mangaTitle.lowercase() }
                        .thenBy { it.issue.lastUpdate },
                ),
            )
        }
        .sortedWith(
            compareByDescending<UpdateIssueGroup> { it.rows.size }
                .thenBy { it.sourceName.lowercase() }
                .thenBy { it.categoryName.lowercase() },
        )
}

private fun ChimahonSnapshot.sourceLanguage(sourceId: Long): String {
    return sources.firstOrNull { it.id == sourceId }?.language?.sourceLanguageCode() ?: "MULTI"
}

private fun ChimahonSnapshot.sourceLanguageOrNull(sourceId: Long): String? {
    val language = sourceEntry(sourceId)?.language?.takeIf { it.isNotBlank() } ?: return null
    return language.sourceLanguageCode().takeIf { it.isNotBlank() }
}

private fun ChimahonSnapshot.libraryCategoryTabs(): List<ChimahonLibraryCategory> {
    val defaultCategory = libraryCategories.firstOrNull { it.id == DEFAULT_LIBRARY_CATEGORY_ID }
        ?: ChimahonLibraryCategory(
            id = DEFAULT_LIBRARY_CATEGORY_ID,
            name = "",
            order = -1L,
            hidden = false,
        )
    val userCategories = libraryCategories
        .asSequence()
        .filter { !it.hidden }
        .filterNot { it.id == DEFAULT_LIBRARY_CATEGORY_ID }
        .sortedWith(compareBy<ChimahonLibraryCategory> { it.order }.thenBy { it.displayName().lowercase() })
        .toList()

    return listOf(
        ChimahonLibraryCategory(
            id = ALL_LIBRARY_CATEGORY_ID,
            name = "All",
            order = -2L,
            hidden = false,
        ),
        defaultCategory.copy(hidden = false),
    ) + userCategories
}

private fun ChimahonSnapshot.libraryForCategory(categoryId: Long): List<ChimahonMangaEntry> {
    if (categoryId == ALL_LIBRARY_CATEGORY_ID) return library
    return library.filter { manga ->
        libraryCategoryMemberships[manga.id].orEmpty().contains(categoryId)
    }
}

private fun ChimahonLibraryCategory.displayName(): String {
    return when {
        id == ALL_LIBRARY_CATEGORY_ID -> "All"
        name.isBlank() -> "Default"
        else -> name
    }
}

private fun List<ChimahonChapterEntry>.androidReadingOrder(
    manga: ChimahonMangaEntry,
): List<ChimahonChapterEntry> {
    return sortedForDetail(
        sort = manga.defaultChapterSort(),
        descending = manga.chapterSortDescending(),
    )
}

private fun List<ChimahonChapterEntry>.nextReadableChapter(
    manga: ChimahonMangaEntry,
): ChimahonChapterEntry? {
    if (isEmpty()) return null
    firstOrNull { it.lastPageRead > 0L && !it.read }?.let { return it }
    return if (manga.chapterSortDescending()) {
        lastOrNull { !it.read } ?: lastOrNull()
    } else {
        firstOrNull { !it.read } ?: firstOrNull()
    }
}

private fun List<ChimahonChapterEntry>.toChapterListSummary(
    downloadStatuses: Map<Long, ChimahonChapterDownloadStatus>,
): ChapterListSummary {
    return ChapterListSummary(
        readCount = count { it.read },
        unreadCount = count { !it.read },
        startedCount = count { it.lastPageRead > 0L && !it.read },
        bookmarkedCount = count { it.bookmarked },
        downloadedCount = count { downloadStatuses[it.id]?.status == ChimahonDownloadState.Downloaded },
        scanlatorCount = mapNotNull { it.scanlator?.takeIf { scanlator -> scanlator.isNotBlank() } }.distinct().size,
    )
}

private fun ChimahonSnapshot.readingProgressSummary(): ReadingProgressSummary {
    val chapterLists = library.map { manga -> chaptersByMangaId[manga.id].orEmpty() }
    val allChapters = chapterLists.flatten()
    val completedManga = chapterLists.count { chapters ->
        chapters.isNotEmpty() && chapters.all { it.read }
    }
    val inProgressManga = chapterLists.count { chapters ->
        val hasProgress = chapters.any { it.read || it.lastPageRead > 0L }
        val complete = chapters.isNotEmpty() && chapters.all { it.read }
        hasProgress && !complete
    }
    return ReadingProgressSummary(
        libraryManga = library.size,
        totalChapters = allChapters.size,
        readChapters = allChapters.count { it.read },
        unreadChapters = allChapters.count { !it.read },
        startedChapters = allChapters.count { it.lastPageRead > 0L && !it.read },
        bookmarkedChapters = allChapters.count { it.bookmarked },
        completedManga = completedManga,
        inProgressManga = inProgressManga,
        untouchedManga = (library.size - completedManga - inProgressManga).coerceAtLeast(0),
        historyEntries = history.size,
        historyManga = history.map { it.mangaId }.distinct().size,
        readDuration = history.sumOf { it.readDuration },
        lastReadAt = history.mapNotNull { it.readAt }.maxOrNull(),
    )
}

private fun ChimahonChapterEntry.matchesChapterQuery(query: String): Boolean {
    if (query.isBlank()) return true
    return name.contains(query, ignoreCase = true) ||
        scanlator.orEmpty().contains(query, ignoreCase = true) ||
        chapterNumber.toDisplayChapter().contains(query, ignoreCase = true) ||
        chapterStateLabel().contains(query, ignoreCase = true)
}

private fun ChimahonRemoteChapterEntry.matchesRemoteChapterQuery(query: String): Boolean {
    if (query.isBlank()) return true
    return name.contains(query, ignoreCase = true) ||
        scanlator.orEmpty().contains(query, ignoreCase = true) ||
        chapterNumber.toDisplayChapter().contains(query, ignoreCase = true) ||
        remoteChapterDetailMetadata().contains(query, ignoreCase = true) ||
        dateUpload.takeIf { it > 0L }?.toDateBucket("Uploaded")?.contains(query, ignoreCase = true) == true
}

private fun ChimahonRemoteChapterEntry.matchesRemoteChapterFilter(filter: RemoteChapterFilter): Boolean {
    return when (filter) {
        RemoteChapterFilter.All -> true
        RemoteChapterFilter.Numbered -> chapterNumber > 0.0
        RemoteChapterFilter.WithUploadDate -> dateUpload > 0L
        RemoteChapterFilter.UnknownDate -> dateUpload <= 0L
        RemoteChapterFilter.WithScanlator -> !scanlator.isNullOrBlank()
        RemoteChapterFilter.NoScanlator -> scanlator.isNullOrBlank()
    }
}

private fun List<ChimahonRemoteChapterEntry>.toRemoteChapterListSummary(): RemoteChapterListSummary {
    return RemoteChapterListSummary(
        totalCount = size,
        numberedCount = count { it.chapterNumber > 0.0 },
        datedCount = count { it.dateUpload > 0L },
        unknownDateCount = count { it.dateUpload <= 0L },
        scanlatorCount = count { !it.scanlator.isNullOrBlank() },
    )
}

private fun List<ChimahonChapterEntry>.sortedForDetail(
    sort: ChapterSort,
    descending: Boolean,
): List<ChimahonChapterEntry> {
    val comparator = when (sort) {
        ChapterSort.SourceOrder -> compareBy<ChimahonChapterEntry> { it.sourceOrder }
        ChapterSort.ChapterNumber -> compareBy<ChimahonChapterEntry> { it.chapterNumber }
            .thenBy { it.name.lowercase() }
        ChapterSort.UploadDate -> compareBy<ChimahonChapterEntry> { it.dateUpload }
            .thenBy { it.chapterNumber }
            .thenBy { it.name.lowercase() }
        ChapterSort.Name -> compareBy<ChimahonChapterEntry> { it.name.lowercase() }
            .thenBy { it.chapterNumber }
        ChapterSort.Scanlator -> compareBy<ChimahonChapterEntry> { it.scanlator.orEmpty().lowercase() }
            .thenBy { it.chapterNumber }
            .thenBy { it.name.lowercase() }
    }
    val sorted = sortedWith(comparator)
    return sorted.withAndroidChapterDirection(sort = sort, descending = descending)
}

private fun List<ChimahonRemoteChapterEntry>.sortedForRemoteDetail(
    sort: ChapterSort,
    descending: Boolean,
): List<ChimahonRemoteChapterEntry> {
    val comparator = when (sort) {
        ChapterSort.SourceOrder -> compareBy<ChimahonRemoteChapterEntry> { it.sourceOrder }
        ChapterSort.ChapterNumber -> compareBy<ChimahonRemoteChapterEntry> { it.chapterNumber }
            .thenBy { it.name.lowercase() }
            .thenBy { it.sourceOrder }
        ChapterSort.UploadDate -> compareBy<ChimahonRemoteChapterEntry> { it.dateUpload }
            .thenBy { it.chapterNumber }
            .thenBy { it.name.lowercase() }
        ChapterSort.Name -> compareBy<ChimahonRemoteChapterEntry> { it.name.lowercase() }
            .thenBy { it.chapterNumber }
            .thenBy { it.sourceOrder }
        ChapterSort.Scanlator -> compareBy<ChimahonRemoteChapterEntry> { it.scanlator.orEmpty().lowercase() }
            .thenBy { it.chapterNumber }
            .thenBy { it.name.lowercase() }
    }
    val sorted = sortedWith(comparator)
    return sorted.withAndroidChapterDirection(sort = sort, descending = descending)
}

private fun <T> List<T>.withAndroidChapterDirection(
    sort: ChapterSort,
    descending: Boolean,
): List<T> {
    return when (sort) {
        ChapterSort.SourceOrder -> if (descending) this else asReversed()
        else -> if (descending) asReversed() else this
    }
}

private fun ChimahonMangaEntry.defaultChapterSort(): ChapterSort {
    return when (chapterFlags and CHIMAHON_CHAPTER_SORTING_MASK) {
        CHIMAHON_CHAPTER_SORTING_NUMBER -> ChapterSort.ChapterNumber
        CHIMAHON_CHAPTER_SORTING_UPLOAD_DATE -> ChapterSort.UploadDate
        CHIMAHON_CHAPTER_SORTING_ALPHABET -> ChapterSort.Name
        else -> ChapterSort.SourceOrder
    }
}

private fun ChimahonMangaEntry.chapterSortDescending(): Boolean {
    return chapterFlags and CHIMAHON_CHAPTER_SORT_DIR_MASK == CHIMAHON_CHAPTER_SORT_DESC
}

private fun ChimahonMangaEntry.defaultChapterFilter(): ChapterFilter {
    return when {
        chapterFlags and CHIMAHON_CHAPTER_UNREAD_MASK == CHIMAHON_CHAPTER_SHOW_UNREAD -> ChapterFilter.Unread
        chapterFlags and CHIMAHON_CHAPTER_UNREAD_MASK == CHIMAHON_CHAPTER_SHOW_READ -> ChapterFilter.Read
        chapterFlags and CHIMAHON_CHAPTER_BOOKMARKED_MASK == CHIMAHON_CHAPTER_SHOW_BOOKMARKED -> ChapterFilter.Bookmarked
        chapterFlags and CHIMAHON_CHAPTER_DOWNLOADED_MASK == CHIMAHON_CHAPTER_SHOW_DOWNLOADED -> ChapterFilter.Downloaded
        chapterFlags and CHIMAHON_CHAPTER_DOWNLOADED_MASK == CHIMAHON_CHAPTER_SHOW_NOT_DOWNLOADED -> ChapterFilter.NotDownloaded
        else -> ChapterFilter.All
    }
}

private fun ChimahonMangaEntry.defaultChapterDisplayMode(): ChapterDisplayMode {
    return when (chapterFlags and CHIMAHON_CHAPTER_DISPLAY_MASK) {
        CHIMAHON_CHAPTER_DISPLAY_NUMBER -> ChapterDisplayMode.ChapterNumber
        else -> ChapterDisplayMode.SourceTitle
    }
}

private fun ChapterFilter.toPersistedChapterFlags(currentFlags: Long): Long? {
    return when (this) {
        ChapterFilter.All -> currentFlags
            .withChimahonFlag(0L, CHIMAHON_CHAPTER_UNREAD_MASK)
            .withChimahonFlag(0L, CHIMAHON_CHAPTER_BOOKMARKED_MASK)
            .withChimahonFlag(0L, CHIMAHON_CHAPTER_DOWNLOADED_MASK)
        ChapterFilter.Unread -> currentFlags
            .withChimahonFlag(CHIMAHON_CHAPTER_SHOW_UNREAD, CHIMAHON_CHAPTER_UNREAD_MASK)
            .withChimahonFlag(0L, CHIMAHON_CHAPTER_BOOKMARKED_MASK)
            .withChimahonFlag(0L, CHIMAHON_CHAPTER_DOWNLOADED_MASK)
        ChapterFilter.Read -> currentFlags
            .withChimahonFlag(CHIMAHON_CHAPTER_SHOW_READ, CHIMAHON_CHAPTER_UNREAD_MASK)
            .withChimahonFlag(0L, CHIMAHON_CHAPTER_BOOKMARKED_MASK)
            .withChimahonFlag(0L, CHIMAHON_CHAPTER_DOWNLOADED_MASK)
        ChapterFilter.Bookmarked -> currentFlags
            .withChimahonFlag(0L, CHIMAHON_CHAPTER_UNREAD_MASK)
            .withChimahonFlag(CHIMAHON_CHAPTER_SHOW_BOOKMARKED, CHIMAHON_CHAPTER_BOOKMARKED_MASK)
            .withChimahonFlag(0L, CHIMAHON_CHAPTER_DOWNLOADED_MASK)
        ChapterFilter.Downloaded -> currentFlags
            .withChimahonFlag(0L, CHIMAHON_CHAPTER_UNREAD_MASK)
            .withChimahonFlag(0L, CHIMAHON_CHAPTER_BOOKMARKED_MASK)
            .withChimahonFlag(CHIMAHON_CHAPTER_SHOW_DOWNLOADED, CHIMAHON_CHAPTER_DOWNLOADED_MASK)
        ChapterFilter.NotDownloaded -> currentFlags
            .withChimahonFlag(0L, CHIMAHON_CHAPTER_UNREAD_MASK)
            .withChimahonFlag(0L, CHIMAHON_CHAPTER_BOOKMARKED_MASK)
            .withChimahonFlag(CHIMAHON_CHAPTER_SHOW_NOT_DOWNLOADED, CHIMAHON_CHAPTER_DOWNLOADED_MASK)
        ChapterFilter.Started -> null
    }
}

private fun ChapterSort.toChapterSortingFlag(): Long? {
    return when (this) {
        ChapterSort.SourceOrder -> CHIMAHON_CHAPTER_SORTING_SOURCE
        ChapterSort.ChapterNumber -> CHIMAHON_CHAPTER_SORTING_NUMBER
        ChapterSort.UploadDate -> CHIMAHON_CHAPTER_SORTING_UPLOAD_DATE
        ChapterSort.Name -> CHIMAHON_CHAPTER_SORTING_ALPHABET
        ChapterSort.Scanlator -> null
    }
}

private fun ChapterDisplayMode.toChapterDisplayFlag(): Long {
    return when (this) {
        ChapterDisplayMode.SourceTitle -> CHIMAHON_CHAPTER_DISPLAY_NAME
        ChapterDisplayMode.ChapterNumber -> CHIMAHON_CHAPTER_DISPLAY_NUMBER
    }
}

private fun ChapterSort.defaultPersistedDescending(): Boolean = false

private fun Boolean.toChapterSortDirectionFlag(): Long {
    return if (this) CHIMAHON_CHAPTER_SORT_DESC else CHIMAHON_CHAPTER_SORT_ASC
}

private fun chapterSortDirectionTitle(sort: ChapterSort, descending: Boolean): String {
    return when (sort) {
        ChapterSort.SourceOrder -> if (descending) "Source order" else "Reverse source order"
        ChapterSort.ChapterNumber -> if (descending) "Highest first" else "Lowest first"
        ChapterSort.UploadDate -> if (descending) "Newest first" else "Oldest first"
        ChapterSort.Name -> if (descending) "Z-A" else "A-Z"
        ChapterSort.Scanlator -> if (descending) "Z-A groups" else "A-Z groups"
    }
}

private fun List<ChimahonRemoteChapterEntry>.remoteStartReadingOrder(): List<ChimahonRemoteChapterEntry> {
    return sortedForRemoteDetail(sort = ChapterSort.SourceOrder, descending = true)
}

private fun ChimahonChapterEntry.chapterMarker(): String {
    return when {
        bookmarked -> "B"
        read -> "R"
        chapterNumber > 0.0 -> chapterNumber.toDisplayChapter()
        else -> "C"
    }
}

private fun ChimahonChapterEntry.chapterDisplayTitle(displayMode: ChapterDisplayMode): String {
    return when {
        displayMode == ChapterDisplayMode.ChapterNumber && chapterNumber > 0.0 ->
            "Chapter ${chapterNumber.toDisplayChapter()}"
        else -> name.ifBlank { "Chapter ${chapterMarker()}" }
    }
}

private fun ChimahonChapterEntry.chapterStateLabel(): String {
    return when {
        read -> "Read"
        lastPageRead > 0L -> "Page ${lastPageRead + 1}"
        bookmarked -> "Bookmarked"
        else -> "Unread"
    }
}

private fun ChimahonChapterEntry.chapterDetailMetadata(
    downloadStatus: ChimahonChapterDownloadStatus?,
    showChapterNumber: Boolean = true,
    sourceTitle: String? = null,
): String {
    return listOfNotNull(
        chapterNumber.takeIf { showChapterNumber && it > 0.0 }?.let { "Ch. ${it.toDisplayChapter()}" },
        sourceTitle,
        chapterStateLabel().takeIf { it != "Unread" },
        scanlator?.takeIf { it.isNotBlank() },
        dateUpload.takeIf { it > 0L }?.toDateBucket("Uploaded"),
        downloadStatus?.chapterDownloadStatusLabel(),
    ).joinToString("  -  ").ifBlank { "No chapter metadata" }
}

private fun ChimahonRemoteChapterEntry.remoteChapterMarker(): String {
    return if (chapterNumber > 0.0) chapterNumber.toDisplayChapter() else "C"
}

private fun ChimahonRemoteMangaDetail.remoteCreatorLine(): String {
    val authorName = author?.takeIf { it.isNotBlank() }
    val artistName = artist?.takeIf { it.isNotBlank() }
    return when {
        authorName != null && artistName != null && authorName != artistName -> "$authorName / $artistName"
        authorName != null -> authorName
        artistName != null -> artistName
        else -> "Unknown author"
    }
}

private fun ChimahonRemoteChapterEntry.remoteChapterTitle(): String {
    return name.ifBlank {
        if (chapterNumber > 0.0) {
            "Chapter ${chapterNumber.toDisplayChapter()}"
        } else {
            "Source chapter"
        }
    }
}

private fun ChimahonRemoteChapterEntry.remoteChapterDetailMetadata(): String {
    return listOfNotNull(
        chapterNumber.takeIf { it > 0.0 }?.let { "Ch. ${it.toDisplayChapter()}" },
        scanlator?.takeIf { it.isNotBlank() },
        dateUpload.takeIf { it > 0L }?.toDateBucket("Uploaded"),
        sourceOrder.takeIf { it != Int.MAX_VALUE }?.let { "Source #${it + 1}" },
    ).joinToString("  -  ").ifBlank { "Source chapter" }
}

private fun ChimahonRemoteChapterEntry.toReaderRequest(
    detail: ChimahonRemoteMangaDetail,
    chapters: List<ChimahonRemoteChapterEntry>,
): ChimahonReaderRequest {
    val queue = chapters.map(ChimahonRemoteChapterEntry::toReaderChapterRef)
    return ChimahonReaderRequest(
        sourceId = detail.sourceId,
        mangaTitle = detail.title,
        chapterName = name,
        chapterUrl = url,
        chapterNumber = chapterNumber,
        scanlator = scanlator,
        dateUpload = dateUpload,
        chapterQueue = queue,
        chapterIndex = chapters.indexOf(this),
    )
}

private fun ChimahonChapterEntry.toReaderRequest(
    manga: ChimahonMangaEntry,
    chapters: List<ChimahonChapterEntry>,
): ChimahonReaderRequest {
    val queue = chapters.map(ChimahonChapterEntry::toReaderChapterRef)
    return ChimahonReaderRequest(
        sourceId = manga.sourceId,
        mangaTitle = manga.title,
        chapterName = name,
        chapterUrl = url,
        chapterNumber = chapterNumber,
        scanlator = scanlator,
        dateUpload = dateUpload,
        mangaId = manga.id,
        chapterId = id,
        initialPage = lastPageRead.coerceAtLeast(0L).coerceAtMost(Int.MAX_VALUE.toLong()).toInt(),
        chapterQueue = queue,
        chapterIndex = chapters.indexOf(this),
    )
}

private fun ChimahonRemoteChapterEntry.toReaderChapterRef(): ChimahonReaderChapterRef {
    return ChimahonReaderChapterRef(
        chapterId = null,
        chapterName = name,
        chapterUrl = url,
        chapterNumber = chapterNumber,
        scanlator = scanlator,
        dateUpload = dateUpload,
    )
}

private fun ChimahonChapterEntry.toReaderChapterRef(): ChimahonReaderChapterRef {
    return ChimahonReaderChapterRef(
        chapterId = id,
        chapterName = name,
        chapterUrl = url,
        chapterNumber = chapterNumber,
        scanlator = scanlator,
        dateUpload = dateUpload,
        initialPage = lastPageRead.coerceAtLeast(0L).coerceAtMost(Int.MAX_VALUE.toLong()).toInt(),
        read = read,
        bookmarked = bookmarked,
        lastPageRead = lastPageRead,
    )
}

private fun ChimahonReaderChapterRef.toReaderRequest(
    current: ChimahonReaderRequest,
): ChimahonReaderRequest {
    return current.copy(
        chapterName = chapterName,
        chapterUrl = chapterUrl,
        chapterNumber = chapterNumber,
        scanlator = scanlator,
        dateUpload = dateUpload,
        chapterId = chapterId,
        initialPage = initialPage,
        chapterIndex = current.chapterQueue.indexOf(this),
    )
}

private fun Long.toDateBucket(prefix: String): String {
    if (this <= 0L) return "Unknown date"
    val day = this / 86_400L
    return "$prefix day $day"
}

private fun Double.toDisplayChapter(): String {
    return if (this.rem(1.0) == 0.0) {
        toLong().toString()
    } else {
        toString()
    }
}

private fun coverColor(seed: Long, title: String): Color {
    val colors = listOf(
        Color(0xFF6F5B8E),
        Color(0xFF3F6F73),
        Color(0xFF87654A),
        Color(0xFF526D43),
        Color(0xFF7B5260),
        Color(0xFF4F6387),
    )
    val index = ((seed xor title.hashCode().toLong()) and Long.MAX_VALUE).rem(colors.size).toInt()
    return colors[index]
}

private fun nativeCheckpointSnapshot(): ChimahonSnapshot = ChimahonSnapshot(
    summary = ChimahonSummary(
        extensionCount = 0,
        sourceCount = 0,
        mangaCount = 0,
